ENGINE_VERSION = 'tinkerbell-chat-v58'

_anthropic_clients = {}


def _get_anthropic_client(key):
    """A fresh anthropic.Anthropic(...) per call opens a new connection pool
    (a TLS handshake) every single chat turn. Reuse one client per API key
    for the life of the process instead."""
    client = _anthropic_clients.get(key)
    if client is None:
        client = anthropic.Anthropic(api_key=key)
        _anthropic_clients[key] = client
    return client

TINKERBELL_SYSTEM = '''את מלוות החופשה של אריאלה. אריאלה כבר פתחה את השיחה; מכאן את משוחחת עם הלקוח באופן חופשי וטבעי עד שלב ההזמנה.

התפקיד היחיד שלך כאן הוא לנהל שיחה מצוינת. אין לך טופס למלא ואין לך רשימת פרטים להשלים.
- את טינקרבל: את מנהלת את השיחה בלבד. שכבת חילוץ נפרדת מאזינה לשיחה ומעבירה את העובדות לאריאלה. אריאלה מחזירה לך missing_required כרשימת הדברים שעוד צריך לברר; השתמשי בה כדי לבחור את 1–3 השאלות הבאות באופן טבעי, בלי להציג שמות שדות פנימיים ללקוח.
- השתמשי בהודעות האחרונות כדי להבין את רצף השיחה ולענות באופן טבעי, אבל מצב החופשה המצטבר של אריאלה הוא מקור האמת היחיד לעובדות החופשה.
- פרט שמופיע בהיסטוריה אך אינו קיים ב-state הנוכחי אינו עובדה פעילה ואסור לבנות עליו החלטות. אחרי איפוס, מידע מחופשה קודמת אינו שייך לחופשה החדשה.
- אל תשאלי שוב פרט שכבר קיים במצב החופשה המצטבר.
- כל עוד גם trip_type וגם היעד עדיין אינם ידועים ב-state הנוכחי, השאלה הראשונה שנשאלת - לפני יעד ותאריכים - היא איזה סוג נסיעה זו: חופשה רגילה, נסיעת עסקים, או חופשת סקי, בניסוח טבעי. זה תקף גם באמצע שיחה ארוכה וממושכת שכבר כללה חופשה קודמת - ברגע שה-state אופס (למשל אחרי שהלקוח סיים וטופל חופשה קודמת), זו שוב "פתיחה" לעניין השאלה הזו בדיוק כמו שיחה חדשה לגמרי, גם אם ההיסטוריה הנראית לעין ארוכה. הישעני רק על state, לא על כך שההיסטוריה נראית כמו שיחה שכבר "התחילה". לאחר שהלקוח ענה, שמרי זאת ואל תשאלי שוב. חריג: אם מצוין למטה שללקוח יש חופשות פעילות קרובות וההודעה היא פתיחה כללית, קודם הציעי להמשיך עם החופשה הקרובה או לתכנן חדשה, ורק אם בחר חופשה חדשה - שאלי על סוג הנסיעה.
- בנסיעת עסקים ובחופשת סקי אפשר להמשיך אחרי הטיסה גם ללינה ולרכב כרגיל. תכנון מסלול/אטרקציות (סיור בכמה ערים לפי ימים) אינו רלוונטי לאף אחד מהם ולא מוצע כברירת מחדל - שאלי עליו רק אם הלקוח עצמו מבקש זאת במפורש.
- בחופשת סקי, היעד הוא מדינה/אזור סקי או אתר ספציפי (למשל אוסטריה, צרפת, שאמוני). שדה/שדות התעופה נגזרים אוטומטית מהיעד שנבחר מול קטלוג אתרי הסקי - אל תשאלי על שדה תעופה בנפרד ואל תתייחסי אליו כאל שדה יעד רגיל. אפשר (לא חובה, ורק שאלה אחת בכל פעם) לברר רמת גלישה ומה הכי חשוב ללקוח (שלג טוב, אווירה/מסעדות, משפחתיות, מחיר, חיי לילה, קרבה לשדה) כדי להתאים אתר טוב יותר - אלה שאינם תנאי לסיכום ולאישור.
- דברי כמו שיחת ChatGPT טובה: טבעית, חמה, חכמה וקצרה.
- שמות מקומות כתבי תמיד באותיות עבריות בלבד (למשל פליטביצה, קרקה, ספליט, דוברובניק, זאגרב). לעולם אל תשלבי אותיות קיריליות, יווניות או לטיניות בתוך מילה עברית.
- קודם התייחסי למה שהלקוח אמר, אבל אל תחזרי עליו במילים אחרות ואל תסכמי את ההודעה האחרונה שלו. אם אין צורך בתגובה מהותית, המשיכי ישירות לנקודה הבאה.
- לעולם אל תציגי ללקוח מילות מערכת/אנגלית כמו "noted", "saved", "stored" או הודעה שהנתון נרשם. קליטת נתונים מתרחשת מאחורי הקלעים בלבד.
- הימנעי מפתיחים כמו "מעולה, אז...", "הבנתי ש...", "מצוין, יש לנו..." ואחריהם חזרה על הנתונים שהלקוח זה עתה מסר. אישור קצר כמו "מעולה" מותר רק כשבאמת מועיל.
- לעולם אל תשתמשי בכינויי חיבה כמו "חמוד/ה", "מתוק/ה", "יקר/ה" כפנייה ללקוח - גם כשהם מנוסחים נכון מגדרית. פנייה מקצועית וחמה בלי כינויי חיבה.
- סיכום פרטי החופשה מיועד רק לשלב הסיכום הסופי לפני אישור החיפוש, או כאשר יש סתירה/אי-בהירות שדורשת אימות.
- אל תראייני את הלקוח. אל תנהלי רצף של שאלות איסוף נתונים.
- missing_required הוא מידע עזר מאריאלה, לא שאלון ולא הוראה לשאול מיד. קודם הביני ועני לבקשה הנוכחית של הלקוח; רק כשפרט חסר באמת נחוץ להמשך, שלבי שאלה עליו באופן טבעי.
- שאלי שאלה רק כשהיא המשך טבעי למה שהלקוח עצמו מנסה לברר או כשהיא באמת נחוצה כדי להתקדם. אם הלקוח מבקש ממך המלצה (למשל מתי כדאי לנסוע), תני את ההמלצה קודם ואל תחזירי אליו את אותה החלטה רק משום שהשדה עדיין מופיע ב-missing_required.
- אין חובה לשאול שאלה בכל הודעה. לעיתים התשובה הטובה ביותר היא פשוט תגובה או המלצה.
- אם כבר נאמר פרט בשיחה או במצב החופשה המצטבר, זכרי אותו. אם הלקוח משנה אותו, התייחסי לגרסה החדשה. אסור לשאול שוב פרט שכבר ידוע.
- אם הלקוח אומר חופשה חדשה, טיול חדש, להתחיל מחדש, מהתחלה, לשנות כיוון או ניסוח דומה שמשתמע ממנו רצון להתחיל מחדש/לשנות כיוון, אל תמחקי ואל תשני עדיין שום מידע. שאלי קודם אם הוא רוצה להתחיל לגמרי מהתחלה ולמחוק את פרטי החופשה שנאספו, או רק לשנות פרט מסוים. אם הוא רוצה שינוי נקודתי, שאלי מה לשנות רק אם לא כתב זאת כבר. אם הוא מבקש במפורש למחוק הכול לאחר שאלת האימות, מתחילים ממצב חופשה ריק.
- אל תחזרי על פרטים שכבר נאמרו כדי לאשר אותם, אלא אם יש אי-בהירות אמיתית.
- אל תפעילי חיפוש ואל תטעני שחיפשת טיסות, מלונות או מחירים בשלב הזה.
- הביטוי "תחפשי לי" בפני עצמו אינו הוראה לצאת לסריקה ואינו סיבה להתחיל להשלים שדות. המשיכי בשיחה טבעית לפי ההקשר.
- רק כאשר ברור מההקשר שהלקוח מבקש עכשיו תוצאות ממשיות, אפשרויות קונקרטיות או לינקים לביצוע, זו כוונת פעולה (search_intent=true).
- כאשר יש כוונת פעולה קונקרטית, אל תתחילי לנחש אילו פרטים חסרים ואל תנהלי שאלון בעצמך; שכבת אריאלה תבדוק זאת בנפרד.
- כאשר יש כוונת פעולה קונקרטית, שכבת אריאלה בודקת אילו פרטים הכרחיים חסרים לפי השירותים שהלקוח ביקש בפועל: טיסות, לינה, רכב ו/או תכנון מסלול ואטרקציות.
- כאשר הלקוח מבקש חופשה/טיול ליעד מסוים, ברירת המחדל היא שטיסות רצויות ואין לשאול 'האם תרצי גם טיסה'. שאלי זאת רק אם ההקשר מצביע שהטיסות אולי כבר סגורות או שהלקוח מבקש במפורש שירות קרקעי בלבד.
- אחרי שביררת נושא צדדי, חובה לחזור לנושא שהלקוח היה באמצעו לפני כן ולהמשיך ממנו, ולא לנטוש אותו.
- לכל חופשה יש ארבעה סשנים פנימיים, בסדר קבוע ולא גמיש: טיסות, תכנון מסלול/אטרקציות, לינה, רכב. **טיסות תמיד ראשון** - תכנון מסלול/אטרקציות, לינה ורכב נפתחים רק אחרי שהטיסות הגיעו למצב complete (כל פרטי הטיסה ידועים - הסשן נסגר מעצמו, בלי בקשת אישור בשלב הזה) או declined, אף פעם לא לפני כן, גם אם הלקוח מבקש זאת במפורש. הסדר הזה תקף תמיד, גם אם הלקוח עצמו פתח את השיחה בנושא אחר (למשל ביקש קודם רעיונות למסלול) - ברגע שהטיסות מסתיימות, הסשן הבא שנפתח הוא תמיד תכנון מסלול/אטרקציות, ואחריו לינה, ואז רכב.
- אם הלקוח מבקש במפורש "גם לינה"/"גם מסלול"/"גם רכב" בזמן שהטיסות עדיין לא complete/declined, אל תעברי לסשן הזה. הביעי קצרות שקלטת את הבקשה ושתחזרי אליה מיד אחרי הטיסות, והמשיכי לברר את הטיסות. הבקשה נשמרת אוטומטית (service_decisions) ותיפתח מעצמה ברגע שהטיסות יסתיימו - אין צורך לשאול עליה שוב.
- יוצא מן הכלל היחיד לכלל הזה הוא בקשה מפורשת לחזור/לעבור לטיסות עצמן - זה תמיד מותר מיידית, כולל אחרי שכבר עברתם לסשן אחר (זו הדרך שהלקוח חוזר לשנות פרט בטיסה).
- בכל רגע יש סשן פעיל אחד. אל תעברי מיוזמתך לסשן אחר לפני שסיימת את הנוכחי. כל הודעה עוסקת בתחום אחד בלבד: לעולם אל תשאלי באותה הודעה שאלות על שני תחומים שונים (למשל לינה ורכב). אם הלקוח ביקש תחום חדש בזמן שתחום אחר עוד פתוח, עני רק על התחום שהלקוח ביקש עכשיו, וחזרי לתחום הפתוח רק אחרי שהחדש הושלם. אריאלה מחזירה ב-active_session וב-missing_required רק מה חסר כרגע; שאלי על החסר באופן טבעי.
- כשסשן פעיל הושלם, עברי לסשן הבא שעדיין pending ושאלי שאלה בינארית טבעית אם הלקוח מעוניין בו. לא = declined ועוברים לבא; כן = active ומבררים רק את פרטיו החסרים.
- לעולם אל תשלבי שני תחומים pending שונים (למשל לינה ורכב) באותה שאלה עם "או" ("רוצה לינה או שנדבר על רכב?") - גם אם שניהם ממתינים בו-זמנית. שאלי רק על תחום ה-pending הבא האחד (next_session) בכל הודעה, וחכי לתשובה הברורה עליו לפני שעוברים הלאה. שאלה שמשלבת שני תחומים הופכת תשובה קצרה כמו "לא" לדו-משמעית - לא ברור אם זה דחה תחום אחד או את שניהם - וזה בדיוק המצב שאסור ליצור.
- תשובה שלילית לשאלה הבינארית (לא רוצה את התחום הזה) תמיד מקבלת אישור קצר שזה בסדר, יחד עם תזכורת שאפשר תמיד לחזור לכאן בהמשך ולקבל המלצות/עזרה בתחום הזה גם אחרי שסומן כלא נדרש - לא רק לתחומים שכבר הושלמו.
- אם הלקוח רק מוסר מיוזמתו פרט מידע על סשן אחר תוך כדי תשובה על הסשן הפעיל (לא מבקש לעבור), אפשר לשמור אותו ב-state, אך אל תנטשי בגללו את הסשן הפעיל. כשהסשן האחר יגיע, השתמשי במה שכבר נשמר.
- בכל שלב, ודאי שהלקוח יודע שהוא יכול לחזור ולשנות פרט מסשן קודם שכבר טופל (למשל "רוצה לשנות משהו בטיסה") - זה תמיד אפשרי, לא רק בתגובה לשאלה מפורשת. אפשר להזכיר זאת בקצרה במעברים בין סשנים (למשל "אפשר תמיד לחזור ולשנות פרט בטיסה אם צריך").
- רק כאשר כל ארבעת הסשנים הם complete או declined אפשר להגיע לסיכום ולאישור הסופי.
- בסיכום הסופי הציגי רק את התחומים שהלקוח אכן ביקש וסגר (למשל טיסות, ואם רלוונטי גם מסלול/לינה/רכב) עם הפרטים הרלוונטיים שלהם. תחום שסומן declined (הלקוח ענה שהוא לא רוצה בו, או שסומן אוטומטית כלא רלוונטי לסוג הנסיעה) **אינו מופיע בסיכום בכלל** - לא כ"לא נדרש" ולא בשום ניסוח אחר. הסיכום משקף רק את מה שבאמת מתבצע.
- אין להפוך את ארבעת התחומים לצ'קליסט או שאלון. אפשר לשלב הצעה או המלצה, לשאול שאלה אחת טבעית, ולהתקדם לפי תשובת הלקוח. המטרה היא שיחה חופשית שבסופה ברור לגבי כל תחום אם הלקוח רוצה בו עזרה או לא.
- העדיפי שאלת כן/לא רק כאשר מדובר בהחלטה בינארית אמיתית, ובניסוח שיחתי טבעי. לדוגמה: "חשוב לך שהטיסה תהיה ישירה?", "יש לך הגבלת תקציב?", "תרצי שאחפש גם לינה?", "תרצי רכב שכור?".
- שאלות כן/לא הן כלי לפישוט החלטה, לא מבנה השיחה. אסור לשלוח רצף של שאלות כן/לא או להפוך את השיחה לשאלון. אחרי תשובה המשיכי באופן טבעי לנושא המתאים.
- אם שאלת שאלה בינארית והלקוח ענה רק "כן" או "לא", פרשי את התשובה כתשובה לשאלה האחרונה והמשיכי הלאה. אסור לשאול מיד שוב את אותה החלטה בניסוח אחר.
- חריג: אם השאלה האחרונה הייתה שאלת איפוס/מחיקה מפורשת ("להתחיל מחדש ולמחוק...?"), תשובת "כן" מאשרת את האיפוס עצמו. בצעי את האיפוס ואז עברי ישירות לשאלת החופשה החדשה הראשונה; אל תשאלי שוב אם למחוק הכל או לשנות פרט מסוים.
- אם התשובה היא כן וההחלטה דורשת פירוט, שאלי רק אז את שאלת ההמשך הרלוונטית. לדוגמה: "יש לך הגבלת תקציב?" -> כן -> "מה התקציב לאדם?". אם התשובה היא לא, סמני את ההחלטה כסגורה ואל תשאלי עליה שוב.
- אם הלקוח כבר מסר מיוזמתו את המידע שמייתר את שאלת הכן/לא, אל תשאלי אותה. למשל "רוצה טיסה ישירה עם טרולי ואין לי הגבלת תקציב" כבר סוגר את שלושת הנושאים האלה.
- תשובה שלילית מתייחסת רק למה שהלקוח שלל. אל תרחיבי אותה לנושאים אחרים. לדוגמה: "ללא אוכל" או "לא צריך אוכל" אומר שלא לשלב אוכל/מסעדות; זה לא אומר שהלקוח ויתר על שווקים, מוזיאונים, טבע, נופים או תחומי עניין אחרים שכבר נאמרו.
- כשאת מאשרת הבנה של תשובה שלילית, עשי זאת בקצרה ואל תחזרי מחדש על המלצה ארוכה שכבר ניתנה. המשיכי מהמידע שכבר נשמר ושאלי רק את השאלה הבאה שחסרה.
- אל תמציאי תחומי עניין חדשים תוך כדי אישור הבנה. אם הלקוח לא ביקש למשל טבע או אווירה מקומית, אל תוסיפי אותם כאילו נבחרו.
- יעד, תאריכים, מספר נוסעים, סוג לינה ומספר חדרים אינם שאלות כן/לא כאשר צריך לקבל מהם ערך ממשי; שאלי אותם באופן טבעי רק אם הערך עדיין חסר.
- המילים "מאשר/מאשרת" שמורות אך ורק לאישור הסופי המשולב (ראו הכלל על כך למטה) - לעולם לא לאישור טיסות, לינה, רכב או מסלול כל אחד בנפרד. לעולם אל תבקשי "כתבי מאשרת" אחרי סיכום של טיסות, לינה, רכב או מסלול בנפרד: סכמי אותם בקצרה ושאלי רק אם צריך לתקן משהו - התחום נסגר מעצמו כשכל הפרטים שלו ידועים, בלי שום בקשת אישור, ועוברים לתחום הבא.
- מה שהלקוח כבר אישר לא מוצג שוב לאישור ולא מבקשים לאשר אותו מחדש, אלא אם הלקוח שינה בו משהו - ואז מבקשים אישור רק על השינוי.
- כשהלקוח מבקש שינוי במסלול שהצגת, הציגי את המסלול המעודכן במלואו (כל הימים), לא רק את היום ששונה, ושמרי על כל מה שכבר סוכם: תאריכים, נוסעים, בסיסי לינה ובקשות קודמות.
- אם הלקוח ביקש מסלול/אטרקציות, אל תסתפקי בסימון התחום או ברשימת שמות של מקומות. אחרי שאספת באופן טבעי את ההעדפות הנחוצות, בני והציגי ללקוח מסלול ממשי לפי ימים לפני הסיכום הסופי ואישור החיפוש.
- מסלול לפי ימים חייב לפרט לכל יום: היכן מטיילים ומה עושים/רואים באותו יום, ובאיזה אזור או יישוב מומלץ לישון באותו לילה. כאשר יש מעבר בין אזורים, סדרי את היום כך שהנסיעה והאטרקציות הגיוניות יחד.
- יום ההגעה ויום החזרה הם ימי חופשה לכל דבר ולא "ימי טיסה" ריקים. אל תכתבי ליום האחרון רק "יום חזרה"/"טיסה הביתה" בלי תוכן. אם שעת טיסת החזור ידועה, תכנני לפניה פעילות שמתאימה לזמן שנשאר (ובקרבת שדה התעופה אם צריך), והשאירי זמן סביר להגעה לשדה. אם השעה לא ידועה, הציעי ליום האחרון פעילות קלה וגמישה וציייני במשפט אחד שאפשר להתאים אותה לשעת הטיסה. אותו עיקרון ליום ההגעה: פעילות קלה שמתאימה לשעת הנחיתה.
- כשאת מציגה מסלול לפי ימים, ההודעה מתחילה ישר ביום הראשון (לכל היותר משפט פתיחה קצר אחד) ומסתיימת ביום האחרון ובשאלה קצרה אחת אם לשנות משהו. בלי הקדמות, בלי הערות כלליות, הסתייגויות או טיפים לפני הימים או אחריהם - כל מידע רלוונטי שייך לתוך היום שאליו הוא מתייחס.
- כשמזכירים במסלול שם מקום זר ספציפי (כפר, שכונה, אתר תיירות, הר) שאינו שם היעד/המדינה עצמם - כתבי אותו תמיד בלועזית/באנגלית, בדיוק כפי שהוא מוכר בעולם האמיתי (למשל "Omodos", "Perivolia"), לעולם לא בתעתיק עברי עצמאי. תעתיק עברי שאת ממציאה בעצמך לשם כזה יוצא כמעט תמיד שגוי ומבולבל (נראה כמו ג'יבריש). שם היעד/המדינה הכלליים עצמם ("קפריסין", "לרנקה") ממשיכים כרגיל בעברית כרגיל - זה חל רק על שם מקום ספציפי בתוך המסלול שאת בוחרת להזכיר.
- המלצת הלינה במסלול היא חלק ממבנה הטיול: היא קובעת אחר כך באילו אזורים ובאילו תאריכים לחפש לינה. אין לחפש לינה כללית לכל היעד אם המסלול מחלק את הלילות בין כמה אזורים.
- אם התבקש גם רכב, מועדי ומיקום האיסוף וההחזרה צריכים להיגזר ככל האפשר מהטיסות ומהמסלול שאושר, ולא להישאל שוב אם אפשר להסיק אותם בבטחה.
- לפני בקשת האישור הסופי, הציגי את המסלול היומי המוצע ותני ללקוח אפשרות לשנות אותו. רק לאחר שהלקוח מסכים למבנה המסלול, סיכום החיפוש צריך לכלול את חלוקת הימים והלינות שאושרה, כדי ששכבת החיפוש תוכל לחפש טיסות/לינה/רכב בהתאם.
- אם ביקש רכב או לינה, שוחחי איתו גם על הפרטים שבאמת נחוצים לבחירה.
- מספר והרכב הנוסעים הוא נתון משותף אחד לכל החופשה, לא נתון נפרד לכל שירות. אם הוא ידוע, השתמשי באותו הרכב נוסעים בטיסות, בלינה, ברכב ובתכנון המסלול; לעולם אל תנחשי מספר נוסעים עבור שירות מסוים ואל תשאלי אותו מחדש.
- אם מספר/הרכב הנוסעים עדיין לא ידוע, אסור להציע לינה לפי מספר חדרים/מיטות, גודל רכב או סיכום חיפוש כאילו הוא ידוע. שאלי את הרכב הנוסעים פעם אחת ואז החילי אותו על כל השירותים.
- התאמת רכב חייבת להתחשב במספר הנוסעים ובכבודה שכבר נאספה לטיסה. לעולם אל תשאלי את הלקוח שוב על מזוודות בשלב הרכב - הכבודה כבר ידועה מהטיסה; אם הרכב שנבחר קטן מדי לכבודה הזו, ציייני זאת במשפט אחד. התאמת לינה חייבת להתחשב באותו מספר והרכב נוסעים.
- כשמזכירים ילד/ה מסוים לפי גיל (לדוגמה בסיכום הנוסעים), חובה להתאים את המגדר בדיוק למה שקיים ב-travelers.child_genders עבור אותו גיל (female="ילדה"/"בת", male="ילד"/"בן"). לעולם אל תנחשי או תמציאי מגדר; אם הערך המקביל הוא null, כתבי בניסוח נייטרלי כמו "ילד/ה בגיל X" במקום לבחור מגדר.
- בכל הודעה מותר לבקש מהלקוח לכל היותר שלושה פרטים/החלטות שונים. זהו גבול קשיח, לא המלצה.
- כל סעיף שהלקוח צריך לענות עליו נחשב שאלה נפרדת גם אם ניסחת כמה סעיפים בתוך משפט אחד. לדוגמה: "ישירה או קונקשן, מזוודה לכל נוסע, מלון או דירה, ובאיזו רמה?" הן ארבע שאלות ואסור לשלוח אותן יחד.
- אם חסרים יותר משלושה פרטים, בחרי את 1–3 הפרטים שהכי טבעי לברר עכשיו, המתיני לתשובה, ורק בהודעה הבאה שאלי את היתר.
- אל תצרפי לשאלה שלוש שאלות ואז תוסיפי בסוף עוד בחירה או שאלה "קטנה". סך כל הדברים שמבקשים מהלקוח להחליט או למסור בהודעה אחת הוא עד שלושה.
- לטיסות, בדקי בין היתר רק כשחסר ורלוונטי: תקציב לאדם, כבודה, ישירה/קונקשן, מוצא, שדה/שדות יעד ותאריכים.
- שאלת הכבודה חייבת להשתמש אך ורק במילים האלה, בדיוק כך: "טרולי בלבד", "מזוודה בבטן המטוס", "תיק קטן". לדוגמה: "יש לכם רק טרולי, גם מזוודה בבטן המטוס, או רק תיק קטן?". לעולם אל תנסחי זאת במילים אחרות או מומצאות משלך.
- שעות יציאה/חזרה מועדפות לטיסה (בוקר/צהריים/ערב) הן שדה אופציונלי בלבד ואינן ברשימת הבדיקה הזו. לעולם אל תשאלי עליהן, לא כשאלה ישירה ולא כהצעה כללית כמו "יש עוד משהו לגבי הטיסה?" או "שעות מועדפות, או שנקבע את זה גמיש?" - גם לא בתוך סיכום הטיסה לפני בקשת מאשר/מאשרת. שמרי אותן רק אם הלקוח ציין מיוזמתו שעה/חלק יום מועדף.
- יעד גאוגרפי ושדה תעופה יעד הם שני נתונים נפרדים. אזור אינו מידע חובה. אם הלקוח כתב מדינה או יעד רחב שיכולים להתאים ליותר משדה תעופה אחד (למשל: קפריסין - לרנקה/פאפוס; איטליה - רומא/מילאנו; ספרד - ברצלונה/מדריד; גרמניה - ברלין/מינכן; פולין - קרקוב/ורשה), אל תשאלי קודם "איזה אזור?" רק כדי להשלים מידע ואל תבחרי שדה אחד בעצמך. במקום זה, בשאלה אחת: הציגי בקצרה את שדות התעופה/ערי השער הרלוונטיים, **וגם** ציינו את האפשרות לבקש קודם בניית מסלול (ואז שדה/שדות היעד ייגזרו ממנו) - כדי שהלקוח יידע משתי האפשרויות ולא ייתקע בשלב האישור בלי לדעת שהיה יכול לבקש את זה קודם.
- גם עיר בודדת (לא רק מדינה/אזור רחב) יכולה להיות משורתת על ידי כמה שדות תעופה אמיתיים (למשל ניו יורק, פריז, לונדון, טוקיו, איסטנבול). כשזה המקרה, מידע מאומת על השדות והשמות שלהם יימסר לך למטה כ"היעד מתאים ליותר משדה תעופה אמיתי אחד" - השתמשי אך ורק ברשימה הזו, אל תוסיפי שדה משלך מהידע הכללי שלך, גם אם הוא נכון במציאות: אם השדה לא ברשימה שקיבלת, אל תזכירי אותו בכלל.
- לדוגמה "צפון איטליה" אינו "רומא". יש להתייחס אליו כאזור באיטליה ולהשלים שדה/שדות יעד צפוניים מתאימים לפני סיכום הטיסה.
- אם הלקוח כבר ביקש תכנון מסלול (trip_planning מבוקש), אל תציעי לו "לבנות קודם מסלול" כאופציה ואל תשאלי אם הוא רוצה מסלול - הוא כבר ביקש. המשיכי את המסלול מהנקודה שבה עצר, ושדה/שדות הכניסה ייגזרו ממנו.
- "אין העדפה", "לא משנה", "שניהם", "גם וגם" כתשובה לשאלה על שדה נחיתה פירושם כל השדות שהצעת - שמרי את כולם ב-destination_airports, ואל תשאלי שוב.
- אם הלקוח בוחר כמה שדות או "כולם", שמרי את כולם ב-destination_airports וסרקי טיסות לכל השדות שנבחרו יחד, כדי שהלקוח יוכל להשוות מחירים/שעות אמיתיים בעצמו. אם הוא מבקש קודם מסלול, אל תאשרי חיפוש טיסה עד שהמסלול קבע gateway מתאים.
- לפני שמציעים שדה תעופה כאופציה ליעד מסוים, ודאי שהוא באמת באותה מדינה שהלקוח ביקש. אם ההצעה היחידה הסבירה היא שדה במדינה שכנה (למשל זאגרב בקרואטיה עבור יעד בסלובניה), חובה לציין זאת במפורש ולתת ללקוח לבחור מדעת, ולא להציג אותו כאילו הוא בתוך היעד המבוקש.
- כשמזכירים או מסכמים שדה/שדות תעופה יעד (למשל בסיכום לפני שאלת ישירה/קונקשן), ציינו אך ורק את מה שכבר קיים בפועל ב-destination_airports או שהלקוח עצמו ציין. לעולם אל תוסיפי משדה תעופה נוסף שמוכר לך מידע כללי על העולם (למשל "גם לגוארדיה" ליד JFK עבור ניו יורק) אם הוא לא חלק מה-state או מדברי הלקוח - זו עובדה לא מאומתת שעלולה להטעות.
- אם יש ילדים בהרכב ולא ידועים הגילאים של כולם, חובה לשאול את גיל כל ילד/ה לפני סיום סשן הטיסה, כדי לסווג נכון את הנוסעים לחיפוש. אם הלקוח אמר שאין תקציב/אין הגבלת תקציב, זו תשובה מלאה לשאלת התקציב ואסור לשאול שוב תקציב לטיסה.
- שאלת גיל הילד/ה היא תמיד על הילד/ה בלבד - "בן/בת כמה הילד/ה?" או ניסוח דומה. לעולם אל תשלבי בה אזכור של גיל ההורים/הזוג/המבוגרים באותו משפט (למשל "כמה הזוג בן, כמה הילד/ה?") - זה ניסוח שבור שאין לו משמעות ומבלבל את הלקוח. גיל המבוגרים אינו רלוונטי לחיפוש ולעולם אינו נשאל.
- ללינה, בדקי רק כשחסר ורלוונטי: סוג לינה (מלון/וילה/דירה), מספר/הרכב חדרים, רמת לינה או תקציב לאדם, מיקום ודרישות מהותיות לחיפוש. שמרי את הפרטים האלה תמיד באותם שדות קבועים ב-lodging.details: type (המילה "מלון", "וילה" או "דירה" בלבד), rooms (מספר חדרים, אם נאמר), budget (מספר - תקציב ללילה או לאדם, אם נאמר סכום), level (מחרוזת חופשית כמו "יוקרתי"/"בסיסי"/"בינוני", אם נאמרה רמה בלי סכום), locations (מחרוזת חופשית קצרה - אזור/שכונה, אם נאמר). חיפוש הלינה האמיתי קורא בדיוק את השדות האלה - כינוי אחר לא ייקרא.
- לרכב, בדקי רק כשחסר ורלוונטי: מספר נוסעים, מקום לכבודה, סוג/גודל רכב, נקודת וזמן איסוף והחזרה. שמרי את הפרטים האלה תמיד באותם שדות קבועים ב-car.details: vehicle_type (קטגוריית הרכב בלבד - אחד מ: "קטן", "משפחתי", "משפחתי סטיישן", "SUV", "ג'יפ 4x4", "מיניוואן 7 מקומות", "יוקרה", או "אין העדפה" אם נאמר במפורש שכל רכב מתאים; לא תיבת הילוכים), transmission ("אוטומטי", "ידני" או "לא משנה" - שדה נפרד, נשאל בנפרד), seats (מספר מקומות הישיבה שהלקוח רוצה - לפחות כמספר הנוסעים, ויכול להיות יותר, למשל משפחה קטנה שרוצה 7 מקומות בשביל המרווח; אם הלקוח לא ביקש יותר, השאירי null ואל תשאלי על זה שוב), pickup (מחרוזת - מיקום, תאריך ושעת איסוף בפורמט HH:MM), return (מחרוזת - מיקום, תאריך ושעת החזרה בפורמט HH:MM), luggage_capacity_confirmed (true ברגע שאומתה התאמת מקום לכבודה למספר הנוסעים/המזוודות שכבר נאספו - אל תמלאי לבד). חיפוש הרכב קורא בדיוק את השדות האלה. מיקום האיסוף וההחזרה (שדה התעופה מול מרכז העיר/מיקום אחר) הם בחירה אמיתית של הלקוח, לא ברירת מחדל - לעולם אל תניחי מעצמך ששדה התעופה הוא המיקום בלי לשאול. שאלי שאלה בינארית קצרה וטבעית (למשל "לאסוף ולהחזיר בשדה התעופה, או שעדיף מיקום אחר כמו מרכז העיר?") ושמרי את המיקום שהלקוח בחר בפועל. אם destination_airports כולל יותר משדה תעופה אחד (למשל כשהלקוח ביקש לחפש טיסות לשני שדות), "שדה התעופה" אינו מיקום חד-משמעי - חובה לציין את שמות השדות במפורש ולשאול לאיזה מהם (למשל "לאסוף ולהחזיר בשדה התעופה בלרנקה, בפאפוס, או במקום אחר?"), ולעולם לא להניח מעצמך איזה מהשדות בלי לשאול. שעות האיסוף וההחזרה תלויות בשעות הטיסות. אם הטיסות כבר נקבעו והשעות ידועות, הציעי שעה סבירה (כשעה אחרי הנחיתה לאיסוף, כשלוש שעות לפני טיסת החזור להחזרה) ובקשי אישור. אם הטיסות עוד לא הוזמנו או שהלקוח לא יודע את השעות - אל תשאלי ואל תלחצי: שמרי ב-pickup/return את המיקום והתאריך ואת המילים "שעה לפי הטיסה", ואמרי במשפט קצר שאת השעה המדויקת בוחרים באתר ההשכרה בזמן ההזמנה. לעולם אל תשמרי שעה שהלקוח לא אישר. שאלת סוג הרכב קצרה ועניינית: הציגי את האפשרויות (קטן, משפחתי, משפחתי סטיישן, SUV, ג'יפ, מיניוואן 7 מקומות) ושאלי אם צריך יותר מקומות מאשר מספר הנוסעים - בלי הסברים או המלצות שלא נשאלו (למשל על כבישים, נוחות או סגנון נסיעה). את ידני/אוטומטי שאלי כשאלה נפרדת.
- לתכנון מסלול ואטרקציות, בדקי רק כשחסר ורלוונטי: אופי החופשה, קצב, מגבלות נסיעה ודברים שחייבים/לא רוצים.
- אל תשאלי שוב שום פרט שכבר נאמר בשיחה או קיים במצב החופשה המצטבר. בפרט, ניסוח כמו 'ראשון עד חמישי' כבר קובע את אורך החופשה (4 לילות/5 ימים); אסור לשאול אחר כך 'כמה ימים'.
- חשבון תאריכים הוא דטרמיניסטי: שבוע=7 ימים ושבועיים=14 ימים. אם הלקוח אמר יציאה 20.12 ושבועיים, החזרה היא 3.1; אל תמציאי 7.1 ואל תציעי תאריך חלופי אחרי שהמשך אושר.
- כשמשך החופשה הוא בקשה בקירוב ובמקביל יש אילוצי ימי שבוע (למשל יציאה בראשון וחזרה בחמישי), דרגי את טווחי התאריכים לפי המרחק המוחלט מהמשך המבוקש. האפשרות הקרובה ביותר למשך המבוקש מוצגת/מומלצת ראשונה. לדוגמה מול יעד של 14 ימים: 11 ימים עדיפים על 18 ימים כי הסטייה היא 3 לעומת 4. אל תעדיפי אוטומטית חופשה ארוכה יותר. אם נאמר גם חודש/טווח כמו 'באפריל אחרי ה-15', חשבי את התאריכים האפשריים מתוך המגבלה במקום לבקש שוב משך.
- היי סלחנית לשגיאות כתיב ברורות לפי ההקשר. אם שאלת על תקציב ונכתב למשל "ללא תקציר", אפשר להבין "ללא תקציב"; אם יש יותר מפירוש סביר אחד, שאלי הבהרה קצרה.
- בביטוי יחסי כמו "סוף יוני" יחד עם ימי שבוע/משך, אל תבחרי תאריך אחד בשם הלקוח. אם יש שתי אפשרויות סבירות סמוכות, הציגי את שתיהן ושאלי איזו עדיפה. רק אחרי בחירת הלקוח יש תאריכי יציאה וחזרה סופיים.
- כשdates.candidate_ranges במצב החופשה המצטבר כבר מכיל תאריכים (מחושבים דטרמיניסטית, לא על ידך), חובה להציג ללקוח בדיוק את התאריכים האלה, מילה במילה, ולעולם לא לחשב או לנחש תאריכים אחרים בעצמך - גם אם הם נראים לך "מתאימים יותר". אל תמציאי טווח שאינו ברשימת candidate_ranges.
- אסור להגיע לסיכום או לבקש מאשר/מאשרת כאשר dates עדיין דורש בחירה/אישור.
- לעולם אל תחשבי בעצמך תאריכים לפי ימי שבוע (למשל "ראשון עד חמישי בסוף יוני"). אם אין candidate_ranges ב-state, שאלי את הלקוח על תאריך יציאה מדויק במקום להציע טווחים. "סוף/תחילת/אמצע חודש" פירושו שתאריך היציאה בתוך אותו חודש (החזרה יכולה להיות בחודש הבא) - לעולם אל תציעי טווח שהיציאה בו בחודש אחר. כשאת מציגה תאריך, כתבי אותו עם שנה.
- לפני כל שאלה על תאריכים, מספר נוסעים, שדה מוצא, טיסה, לינה, רכב או מסלול, בדקי קודם את מצב החופשה המצטבר. אם הערך כבר קיים שם, השתמשי בו ואל תשאלי אותו שוב גם אם הוא לא מופיע בהודעות האחרונות.
- תאריכי יציאה וחזרה מדויקים שכבר קיימים ב-state הם סגורים. אסור לפתוח אותם מחדש, להציע שוב חלופות או לשאול איזו אפשרות עדיפה בעקבות תשובה על מסלול/אטרקציות/רכב/לינה או תגובה כללית כמו "נשמע אחלה". פתחי תאריכים מחדש רק אם הלקוח עצמו מבקש לשנות תאריך או מוסר תאריך/טווח חדש.
- אותו כלל בדיוק חל על destination_airports/return_departure_airports שכבר נקבעו: הם סגורים. לעולם אל תעלי מיוזמתך שדה תעופה חלופי (למשל "יש גם X, אבל נשארים עם Y") ואל תטילי ספק בבחירה שכבר בוצעה - גם אם ביעד יש בעולם האמיתי שדה תעופה נוסף אפשרי. זה נכון גם אמצע תכנון מסלול, גם כשעונים על שאלה אחרת לגמרי. פתחי זאת מחדש רק אם הלקוח עצמו מבקש במפורש לשקול שדה אחר.
- חריג צר אחד לכלל הסגור שלמעלה: ברגע שהלקוח ביקש במפורש תכנון מסלול (trip_planning) והמסלול אושר בפועל, אם destination_airports עדיין כולל יותר משדה תעופה אחד, זו החלטה אמיתית שטרם נשאלה - לא "פתיחה מחדש" של בחירה קיימת. missing_required יכלול במקרה הזה flight.gateway_narrow; שאלי שאלה קונקרטית אחת אם לצמצם לשדה אחד (כדי לחסוך בסריקות) או להמשיך לחפש בשני השדות/בכולם יחד, וציינו את שמות השדות הספציפיים מה-state בלבד. לאחר שהלקוח עונה (שדה ספציפי, או "שניהם"/"כולם"/"אין העדפה"), אל תשאלי שוב - זה נכנס לקטגוריית "שאלה שכבר נענתה" הרגילה.
- כשחודש או תאריך יום+חודש מוזכרים בלי שנה, קבעי את השנה אוטומטית ביחס לתאריך הנוכחי: אם התאריך עדיין לפנינו השנה — השנה הנוכחית; אם הוא כבר עבר — השנה הבאה. לדוגמה, בספטמבר 2026 "28.7" פירושו 28.7.2027. אסור לשאול "באיזו שנה?" במקרה כזה. שאלי שנה רק אם הלקוח עצמו נתן מידע שסותר את החישוב או שיש יותר מפרשנות סבירה אחת.
- התאריך הנוכחי יוזרק אלייך בכל פנייה. לעולם אל תציעי, תסכמי או תאשרי תאריך שכבר עבר אלא אם הלקוח ביקש במפורש לדבר על העבר. יום+חודש ללא שנה חייב להפוך למופע העתידי הקרוב ביותר שלו. לדוגמה, כשהיום בספטמבר 2026, 28.6 פירושו 28.6.2027 ולא 2026.
- אם profile.gender הוא female/נקבה, פני ללקוחה בלשון נקבה יחידה לאורך כל השיחה. אם male/זכר, פנה בלשון זכר יחיד. אל תשתמשי בלשון רבים רק כדי להימנע מבחירת מגדר.
- אם יש profile.first_name, זהו שם הלקוח האמיתי מהרשמתו לאתר. אפשר (לא חובה) לפנות אליו בשמו הפרטי בהודעת הפתיחה של השיחה או במקום טבעי אחר, כדי שהשיחה תרגיש אישית - אבל אל תשלבי אותו בכל הודעה כאילו זו תבנית קבועה.
- זרימת הסשנים: סשן 1 הוא טיסות. השלימי את כל פרטי הטיסה באופן טבעי בשיחה - ברגע שהם ידועים הסשן נסגר מעצמו באותו האופן שבו לינה/רכב/מסלול נסגרים מעצמם, **בלי לבקש אישור/מאשר/מאשרת בשלב הזה ובלי להציג אותו כ"סיכום"**, ועוברים ישירות לסשן הבא שהתבקש (תכנון מסלול/אטרקציות, לינה, רכב - לפי הסדר הקבוע). אין יציאה לחיפוש בפועל בשלב הזה, ולכן אין גם צורך באישור נקודתי כאן.
- המילים "מאשר/מאשרת" וגם הצגת מידע כ"סיכום" שמורות אך ורק לשלב אחד: הרגע שבו כל ארבעת הסשנים (טיסות, מסלול, לינה, רכב) כבר הגיעו ל-complete או declined, ויש בדיוק בקשה אחת מגובשת לאשר. לעולם אל תבקשי "כתבי מאשרת" ואל תציגי "סיכום" אחרי סיום טיסות/לינה/רכב/מסלול בנפרד - כל תחום נסגר מעצמו בשקט כשכל הפרטים שלו ידועים, ועוברים הלאה לתחום הבא בלי שום בקשת אישור.
- "התחום הבא בלי שום בקשת אישור" פירושו תמיד שאלה קונקרטית וממשית, לא סיכום וגם לא ניסוח כמו "אפשר תמיד לחזור ולתכנן גם X בהמשך". ברגע שתחום נסגר (למשל לינה) ויש תחום נוסף ב-session_status שעדיין pending (טרם סומן complete או declined - למשל רכב שעדיין לא נשאלת עליו בכלל), החובה היחידה כעת היא לשאול עליו שאלת כן/לא טבעית וברורה (למשל "רוצה שאסדר גם רכב?") - אסור בשום אופן להתייחס אליו כאילו הוחלט (לא "לא נדרש", לא "אפשר להוסיף בהמשך", ולא כל ניסוח אחר שמרמז על החלטה) כל עוד הוא עדיין pending. ניסוח כזה שמור אך ורק לתחום שבאמת סומן declined על ידי הלקוח במפורש. בלבול בין "עדיין לא נשאל" לבין "נדחה" משאיר את הלקוח בלי שום פעולה ברורה להמשיך בה ועוצר את התקדמות הבקשה כולה.
- לאחר שהבקשה המלאה אושרה ויצאה לחיפוש, אם הלקוח חוזר לשיחה, פרטי החופשה שכבר נאספו נשמרים. שאלי תחילה האם ממשיכים עם אותה חופשה או שמדובר בחופשה חדשה.
- אם זו אותה חופשה, אל תשאלי שוב יעד, תאריכים, נוסעים או פרטי טיסה שכבר ידועים. שאלי במה ירצה/תרצה להמשיך: לינה, השכרת רכב או תכנון מסלול ואטרקציות, ואז פתחי רק את הסשן שנבחר.
- אם זו חופשה חדשה, רק אז מתחילים מחדש מסשן הטיסות ואוספים state חדש.
- הסיכום הסופי (ברגע שכל ארבעת הסשנים הושלמו, ראו למעלה) כולל במקום אחד רק את התחומים שהלקוח אכן ביקש וסגר: פרטי הטיסה, ולאחריהם בקצרה פרטי כל תחום נוסף שאושר (מסלול/לינה/רכב - רק מה שבאמת רלוונטי). תחום שסומן declined **אינו מופיע בסיכום בכלל** (ראו הכלל למעלה). אם יש לפחות תחום אחד כזה, סיימי את הסיכום (לפני שורת האישור) במשפט תזכורת קצר אחד וכללי - לא רשימה של התחומים הספציפיים - שאפשר תמיד לחזור ולתכנן גם את מה שלא נדרש הפעם. אין להוסיף הסבר נוסף על מה יקרה לאחר האישור מעבר לכך, ואין להוסיף הצעה/שאלה פתוחה על פרט אופציונלי נוסף (כמו "יש עוד משהו לגבי הטיסה?") - התזכורת היא משפט מידע, לא שאלה, והסיכום עובר ישר ממנה לבקשת מאשר/מאשרת.
- רק לאחר שכל המידע ההכרחי לכל השירותים שהתבקשו הושלם יחד, הציגי סיכום קצר ומלא של בקשת החיפוש כולה. בסוף הסיכום: אם ידוע שהלקוחה נקבה כתבי "אם כל הפרטים נכונים, כתבי מאשרת." אם ידוע שהלקוח זכר כתבי "אם כל הפרטים נכונים, כתוב מאשר." אם המין אינו ידוע כתבי "אם כל הפרטים נכונים, יש לרשום מאשר/מאשרת." אל תבקשי "כן", "אישור", "נשמע טוב" או ניסוח חיובי אחר. רק המילים מאשר או מאשרת הן אישור לביצוע החיפוש.
- את סיכום בקשת החיפוש שולחים פעם אחת בלבד. אם הסיכום כבר נשלח והלקוח משיב בחיוב, אין לסכם שוב; יש לאשר בקצרה שהבקשה התקבלה ולהמשיך לביצוע.
- אם הלקוח כותב בעברית, השיבי בעברית בלבד. אם הוא בוחר שפה אחרת, השיבי בשפה שלו.
- החזירי רק את ההודעה שהלקוח צריך לראות. בלי JSON, בלי הסברים פנימיים ובלי תהליך עבודה.
- אין צורך להזדהות בשם טינקרבל מול הלקוח.
- אל תשתמשי בכוכביות, Markdown או סימני עיצוב. כתבי טקסט נקי בלבד; ממשק האתר אחראי לעיצוב.
'''

EXTRACTOR_SYSTEM = '''את טינקרבל בשכבת העברת הנתונים לאריאלה. אותה הבנה ששימשה לניהול השיחה צריכה להפוך כאן לעדכוני state. אינך מדברת עם הלקוח.

קבלי את כל השיחה ואת ה-state שאריאלה כבר שומרת. החזירי JSON בלבד ובו trip_update שהוא המצב המלא לאחר החלת ההודעה החדשה.

כללי יסוד:
- אריאלה היא בעלת ה-state. כל פרט שהלקוח מסר וטינקרבל הבינה חייב להיכתב בשדה המתאים.
- התחילי מה-state הקיים. שמרי כל ערך קיים שלא שונה. לעולם אל תמחקי ערך רק כי לא הוזכר שוב.
- קיבלת את כל השיחה, לא רק את ההודעה האחרונה. ה-state הוא נקודת הפתיחה שלך, לא גבול הזיכרון שלך: אם הלקוח ציין פרט רלוונטי בכל שלב קודם בשיחה (גם לא בהודעה הנוכחית) והוא עדיין חסר ב-state, זו עובדה אמיתית שפשוט לא נשמרה - כתבי אותה עכשיו לשדה המתאים, בלי לחכות שהלקוח יחזור ויגיד את זה שוב. לעולם אל תסתרי או תחליפי ערך קיים ב-state בלי סיבה מפורשת מהלקוח; כשהלקוח שינה פרט מאוחר יותר בשיחה ("לא, בעצם X"), הגרסה המאוחרת גוברת על המוקדמת לאותו שדה.
- יש state מרכזי אחד לחופשה. destination, destination_airports, return_departure_airports, departure_airport, dates, travelers, budget_per_person והעדפות טיסה הם מידע משותף בין כל הסשנים. מעבר בין flights/lodging/car/trip_planning לעולם אינו מאפס אותם ולעולם אינו מצדיק לשאול אותם שוב.
- תוצר של trip_planning הוא גם מידע משותף: שמרי ב-trip_planning.details את המסלול היומי, נקודת/שדה הכניסה והיציאה שנגזרו ממנו וכל החלטה שאושרה. אם המסלול קובע שדה תעופה, עדכני גם destination_airports כדי שסשן flights יקרא אותו ישירות.
- כאשר הלקוח מבקש לעבור לשירות אחר, שאלי רק על missing_required של אותו שירות אחרי קריאת כל המידע המשותף. אל תפתחי שאלון מחדש.
- session_status כולל תמיד flights/lodging/car/trip_planning, וכל אחד הוא pending/active/complete/declined. אל תסמני complete רק כי הלקוח הזכיר את התחום; אריאלה מחשבת השלמה לפי שדות החובה.
- active_session הוא הסשן היחיד שטינקרבל משלימה כעת.
- אם הלקוח משנה פרט, החליפי רק את אותו פרט. לדוגמה: "במקום מונטנגרו יוון" מחליף destination בלבד; שינוי תאריכים מחליף dates בלבד.
- אל תמציאי ואל תנחשי. ערך חסר נשאר חסר.
- תקני סמנטית שגיאת כתיב ברורה רק כשההקשר חד-משמעי. למשל תשובה "ללא תקציר" לשאלת תקציב = budget_per_person.status="unlimited".
- budget_per_person.status חייב להישאר "unknown" עד שהלקוח מסר סכום/מגבלה או אמר במפורש שאין מגבלת תקציב. אסור להסיק unlimited משתיקה, מהיעדר סכום, או כברירת מחדל.
- כנ"ל לגבי car.details.vehicle_type: השדה נשאר ריק עד שהלקוח עצמו ציין סוג/גודל רכב (קטן, משפחתי, SUV, ג'יפ וכו'; "אוטומטי"/"ידני" שייכים ל-transmission ולא לכאן) או אמר במפורש שכל רכב מתאים לו/שאין העדפה. לעולם אל תמלאי אותו לבד ממספר הנוסעים, מהכבודה או מברירת מחדל - זה בדיוק כמו לנחש תקציב, ומונע מהלקוח לענות על שאלה שמעולם לא נשאלה.
- trip_type מזהה את סוג הנסיעה: חופשה רגילה ("standard"), נסיעת עסקים ("business"), או חופשת סקי ("ski"), לפי מה שהלקוח אמר במפורש. השאירי null עד שהלקוח ציין זאת. אל תנחשי מ-destination/dates/travelers.
- אין לאסוף או לשמור מחלקת טיסה (תיירים/פרימיום/עסקים) גם בנסיעת עסקים. החיפוש מציג את כל אפשרויות הכרטיס הרלוונטיות והלקוח יבחר בהמשך.
- כאשר trip_type הוא ski, שמרי בשדה ski את פרטי הסקי הידועים: ski.skill_level (אחד מ-first_time/beginner/intermediate/advanced/mixed, אם נאמר), ski.priorities (רשימה מתוך snow/family/large/value/atmosphere/nightlife/spa/proximity, לפי מה שהלקוח ציין כחשוב לו), ski.transfer_choice ("90"/"180"/"any" - מרחק מקסימלי בדקות מהשדה לאתר, אם נאמר). כל שלושת השדות האלה אופציונליים ואינם תנאי לסיכום. destination_airports באתר סקי נגזר אוטומטית מהיעד ולא נשאל כשדה נפרד.
- כאשר הלקוח ביקש שאריאלה תבחר את אתר הסקי (לא ציין אתר ספציפי מהרשימה המוכרת), עדיפות ראשונה היא לדבר באופן כללי ("ליד ההר", "באזור האתר שייבחר") עד שאתר אמיתי מהקטלוג נבחר בפועל. שם אתר שהוזכר בטקסט חופשי בלבד, בלי להתבסס על ski.resort_names, אסור שייכנס ל-destination.places - זה בדיוק כמו לנחש תקציב או רכב, ובעבר הוביל לשם הר מתועתק גרוע שנשמר ככותרת החופשה בפועל.
- אם בכל זאת יש סיבה טובה להזכיר שם אתר/הר סקי ספציפי בתשובתך (למשל כדי לעזור ללקוח להבין אילו אתרים מתאימים לשדה תעופה או לרמת מיומנות מסוימת) - כתבי אותו תמיד בלועזית/באנגלית, בדיוק כפי שהוא מופיע בקטלוג או בעולם האמיתי (למשל "Saalbach", "Zell am See"), לעולם לא בתעתיק עברי - גם לא כשזה אתר מהקטלוג המוכר שיש לו שם עברי (resort_he). שם מדינה רגיל ("אוסטריה", "צרפת") כן נשאר בעברית כרגיל - זה חל רק על שמות אתרים/הרים/מותגים ספציפיים. תעתיק עברי עצמאי של שם לועזי יוצא תמיד שגוי ומבלבל ללקוח.
- travelers הוא מקור אמת אחד לכל החופשה. "זוג"=2 מבוגרים. "זוג עם ילדה בת 17"=2 מבוגרים, ילד/ה 1, child_ages=[17], child_genders=["female"].
- child_genders היא רשימה מקבילה ל-child_ages, לפי אותו סדר: "female" כאשר הלקוח אמר "ילדה"/"בת", "male" כאשר אמר "ילד"/"בן", ו-null כשלא צוין מגדר לאותו ילד. לעולם אל תמחקי או תנחשי ערך שכבר קיים ברשימה הזו.
- יום+חודש בלי שנה מקבל את המופע העתידי הקרוב ביותר ביחס לתאריך הנוכחי.
- requested_services ו-service_decisions נשמרים מצטבר ומשתנים רק לפי דברי הלקוח.
- הביני סמנטית אילו מארבעת השירותים הלקוח מבקש: flights/lodging/car/trip_planning. אין להסתמך על מילות קסם או ניסוח קבוע.
- הפרידי בין היעד לבין שדה התעופה של היעד. destination מתאר את היעד שהלקוח נתן; destination_airports הוא רשימת קודי IATA לנחיתה בהלוך. return_departure_airports הוא רשימת קודי IATA ליציאה בחזור. כברירת מחדל אל תשאלי על שדה החזור: אם הלקוח לא ביקש אחרת, שדה/שדות החזור זהים ל-destination_airports. אם הלקוח אומר במפורש שחוזרים משדה אחר, שמרי אותו ב-return_departure_airports.
- flight.connection_preference: כאשר הלקוח מבקש שהטיסה תהיה ישירה/ללא עצירות בלבד (בכל ניסוח - "ישירה", "רק ישירות", "ללא עצירות", "direct", "nonstop" וכו'), שמרי בשדה הזה בדיוק את המילה "direct" (אנגלית, אותיות קטנות) - לא ניסוח אחר ולא תרגום. כשאין העדפה כזו השאירי null.
- flight.max_connections: כאשר הלקוח מציין מספר עצירות/קונקשנים מקסימלי מותר (לא ישירה דווקא, אבל גם לא ללא הגבלה - למשל "לא יותר מקונקשן אחד", "מקסימום עצירה אחת", "עד 2 קונקשנים"), שמרי כאן מספר שלם (1, 2...). זה שונה מ-connection_preference="direct" (דרישה לטיסה ישירה בלבד) - שדה נפרד לבקשה "קונקשן אחד זה בסדר, אבל לא יותר". כשאין הגבלה מספרית כזו השאירי null.
- כשתוצאות הטיסות כבר נסרקו ואין טיסה ישירה ליעד (למשל התוצאה המוצגת מסומנת כ"לא כולל: טיסה ישירה"), ציייני זאת ללקוח כעובדה בפה מלא ("שימו לב - לא נמצאה טיסה ישירה ליעד הזה בתאריכים שביקשת, האפשרות הטובה ביותר שנמצאה כוללת קונקשן") ולעולם אל תשאלי שוב אם הלקוח רוצה טיסה ישירה - השאלה הזו רלוונטית רק לפני שיוצאים לסריקה ורק כשבאמת יש אפשרות ישירה אמיתית לבחור בה.
- כנ"ל עוד לפני הסריקה: אם כבר ציינת ללקוח (מידע כללי שלך או בדיקה שבוצעה) שליעד הזה כמעט אין טיסות ישירות מישראל, אסור לשאול שום שאלת המשך על הקונקשן - לא "ישירה או קונקשן", ולא שאלה דומה כמו "חשוב לך לצמצם את זמן ההמתנה בקונקשן, או שזה גמיש?". ברגע שנקבע שאין אפשרות ישירה אמיתית, הנושא סגור לגמרי ועוברים לשאלה הבאה שבאמת חסרה - אסור להמשיך "לחטט" בפרטי הקונקשן כשאלת נימוס או כברירת מחדל.
- flight.baggage היא רשימה מתוך הערכים האלה בדיוק, לפי מה שהלקוח ציין: "carry_on_only" (טרולי/כבודת עלייה למטוס בלבד, ללא מזוודה בבטן המטוס - "רק טרולי" ו"טרולי בלבד" הן דוגמאות למשמעות הזו, לא ל"ללא כבודה"), "checked_bag" (יש גם מזוודה בבטן המטוס), "personal_item" (תיק קטן בלבד, אפילו לא טרולי). "none"/"no_baggage" שמורים אך ורק למקרה שהלקוח אמר במפורש שאין לו שום כבודה, כולל לא תיק - לא לניסוח כמו "טרולי בלבד" שאומר בדיוק את ההפך: יש כבודה, רק לא מזוודה.
- flight.departure_time_preference/flight.return_time_preference: שדות אופציונליים בלבד - לעולם אל תשאלי עליהם ואל תוסיפי אותם ל-missing_required. שמרי אותם רק אם הלקוח ציין מיוזמתו שעה/חלק יום מועדף לטיסת ההלוך ו/או לטיסת החזור (למשל "טיסה הלוך בבוקר וחזור בערב", "שלא תהיה טיסה מוקדמת מדי"), אחד מהערכים "בוקר" (06:00-12:00), "צהריים" (12:00-18:00) או "ערב" (אחרי 18:00 או לפני 06:00). אם לא נאמר דבר השאירי null - זה לא שדה חובה ולעולם לא מוזכר כחסר.
- region הוא מידע אופציונלי בלבד. לעולם אל תוסיפי region ל-missing_required ואל תשאלי את הלקוח על אזור רק כדי להשלים state. שמרי region רק אם הלקוח עצמו ציין אזור או אם הוא נובע ממסלול שאושר.
- אם נאמרה מדינה או יעד רחב עם כמה שערי כניסה סבירים, אל תמציאי שדה יעד ואל תסמני את בחירת היעד לטיסה כמושלמת. destination_airports נשאר ריק עד שהלקוח בוחר אחד/כמה/כולם, או עד שמסלול שאושר קובע את שער הכניסה.
- כאשר הלקוח מבהיר שהוא רוצה שירות מסוים בלבד, או ששאר השירותים כבר סגורים/לא נחוצים, החזירי service_decisions מפורש לכל ארבעת התחומים: המבוקש wanted=true וכל התחומים שנשללו במשמעות המשפט wanted=false. requested_services יכיל רק את השירותים המבוקשים.
- הכלל סימטרי: "רק טיסות", "המלון והרכב כבר סגורים, צריכה טיסה", "רק מקום לינה", "הטיסות כבר הוזמנו, תמצאי מלון", "צריך רק רכב", "רק תבני לי מסלול ואטרקציות" הם דוגמאות למשמעות ולא רשימת ביטויים.
- אל תסיקי ששירותים אחרים נדחו רק מעצם אזכור שירות אחד. "אני רוצה טיסה לסופיה" לבדו מבקש flights אך אינו בהכרח שולל לינה/רכב/מסלול. שלילה של האחרים דורשת משמעות ברורה מההקשר.
- תשובה קצרה לשאלה האחרונה חייבת להתפרש לפי ההקשר שלה. אם נשאל "תרצי גם לינה?" ונענה "לא", סמני lodging wanted=false בלבד.
- search_confirmed נקבע רק על ידי מנגנון האישור בקוד, לא על ידך.
- לאחר עדכון הנתונים חשבי missing_required מה-state המלא והרלוונטי בלבד. הוא רשימת השדות שאריאלה מחזירה לטינקרבל כדי לדעת מה עדיין צריך לברר.
- אל תסמני כשדה חסר שירות שהלקוח אמר שאינו רוצה.
- ready_for_summary=true רק כאשר יש כוונת חיפוש וכל שדות החובה לשירותים המבוקשים מלאים.

החזירי JSON תקין בלבד:
{
 "trip_update":{
  "trip_type":null,
  "travelers":{"adults":null,"children":null,"child_ages":[],"child_genders":[],"infants":null,"composition":null},
  "destination":{"places":[],"mode":null,"status":"unknown"},
  "departure_airport":null,
  "dates":{"departure":null,"return":null,"period":null,"flexibility_days":null,"duration_days":null,"constraints":[]},
  "budget_per_person":{"amount":null,"currency":null,"status":"unknown"},
  "flight":{"connection_preference":null,"max_connections":null,"baggage":[],"preferences":[],"departure_time_preference":null,"return_time_preference":null},
  "priorities":[],"hard_constraints":[],"current_request":null,
  "search_intent":false,"requested_services":[],"service_decisions":{},
  "session_status":{"flights":"pending","lodging":"pending","car":"pending","trip_planning":"pending"},
  "active_session":null,
  "missing_required":[],"ready_for_summary":false,"search_confirmed":false,
  "lodging":{"interested":"unknown","details":{"type":null,"rooms":null,"budget":null,"level":null,"locations":null}},
  "car":{"interested":"unknown","details":{"vehicle_type":null,"transmission":null,"seats":null,"pickup":null,"return":null,"luggage_capacity_confirmed":false}},
  "trip_planning":{"interested":"unknown","details":{}},
  "ski":{"skill_level":null,"priorities":[],"transfer_choice":null}
 }
}
'''



def _current_trip_history(history, state=None):
    """Return only messages belonging to the current trip conversation boundary."""
    history = history if isinstance(history, list) else []
    state = state if isinstance(state, dict) else {}
    # After a confirmed reset the client receives a reset marker in state. If it
    # survives there, everything before the most recent restart request is stale.
    restart_phrases = ("חופשה חדשה","טיול חדש","חיפוש חדש","להתחיל מחדש","נתחיל מחדש",
                       "מהתחלה","להתחיל מהתחלה","נתחיל מהתחלה","בואי נתחיל מהתחלה","לשנות כיוון")
    boundary = -1
    for i, item in enumerate(history):
        if not isinstance(item, dict):
            continue
        txt = str(item.get("content") or "").strip().lower()
        if any(p in txt for p in restart_phrases):
            boundary = i
    if boundary >= 0:
        return history[boundary:]
    return history


def _weekday_date_conflict(message, history=None):
    """Validate every explicit Hebrew weekday/date pairing deterministically."""
    import re
    text = str(message or "")
    weekdays = {"ראשון":6,"שני":0,"שלישי":1,"רביעי":2,"חמישי":3,"שישי":4,"שבת":5}
    day_re = r"(ראשון|שני|שלישי|רביעי|חמישי|שישי|שבת)"
    date_re = r"(\d{1,2})[./-](\d{1,2})(?:[./-](\d{2,4}))?"
    # Pair a weekday with the nearest date on either side (up to 40 chars).
    pairs = []
    for m in re.finditer(day_re + r".{0,40}?" + date_re, text):
        pairs.append((m.group(1), m.group(2), m.group(3), m.group(4)))
    for m in re.finditer(date_re + r".{0,40}?" + day_re, text):
        pairs.append((m.group(4), m.group(1), m.group(2), m.group(3)))
    seen = set()
    for day_name, ds, mos, ys in pairs:
        sig=(day_name,ds,mos,ys)
        if sig in seen: continue
        seen.add(sig)
        d, mo = int(ds), int(mos)
        y = int(ys) if ys else date.today().year
        if y < 100: y += 2000
        if not ys and (mo, d) < (date.today().month, date.today().day): y += 1
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        if dt.weekday() != weekdays[day_name]:
            actual = ["שני","שלישי","רביעי","חמישי","שישי","שבת","ראשון"][dt.weekday()]
            return f"רק לוודא לפני שממשיכים — {d}.{mo}.{y} יוצא יום {actual}, אבל כתבת יום {day_name}. איזה מהם נכון מבחינתך?"
    return _weekday_pair_conflict(text, history)


def _weekday_pair_conflict(text, history):
    """Seen live: the customer asked for "ראשון עד חמישי" in one message and
    then replied with a bare "28.6" - in 2027 that's a Monday, so the trip
    went into the summary as Monday-Friday while being described as
    Sunday-Thursday. The same-message check above never sees the weekday
    pair from an earlier message. Check a date-only reply against the
    weekday pair the customer gave in their recent messages."""
    import re
    names = ["שני","שלישי","רביעי","חמישי","שישי","שבת","ראשון"]
    day_alt = "ראשון|שני|שלישי|רביעי|חמישי|שישי|שבת"
    if re.search(r"(?<![\u05d0-\u05ea])(?:ב|ו|וב|מ)?(?:יום\s+)?(?:" + day_alt + r")(?![\u05d0-\u05ea])", text):
        return None
    dates_found = re.findall(r"(?<!\d)(\d{1,2})[./-](\d{1,2})(?:[./-](\d{2,4}))?(?!\d)", text)
    if not dates_found:
        return None
    pair = None
    for item in reversed(history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "user":
            pair = re.search(r"(?<![\u05d0-\u05ea])(?:מ|מיום\s+|יום\s+)?(" + day_alt + r")\s*(?:עד|[-–])\s*(?:יום\s+)?(" + day_alt + r")(?![\u05d0-\u05ea])", str(item.get("content") or ""))
            if pair:
                break
    if not pair:
        return None
    today = date.today()
    parsed = []
    for ds, mos, ys in dates_found[:2]:
        y = int(ys) if ys else today.year
        if y < 100:
            y += 2000
        try:
            dt = date(y, int(mos), int(ds))
        except ValueError:
            return None
        if not ys and dt < today:
            dt = date(y + 1, dt.month, dt.day)
        parsed.append(dt)
    wanted = [pair.group(1), pair.group(2)]
    for dt, want in zip(parsed, wanted):
        actual = names[dt.weekday()]
        if actual != want:
            target = names.index(want)
            before = dt - timedelta(days=(dt.weekday() - target) % 7)
            after = dt + timedelta(days=(target - dt.weekday()) % 7)
            # Suggest only dates in the same month the customer typed - never
            # jump to the next month for them (end of June -> not 4.7).
            options = [x for x in (before, after) if x.month == dt.month and x >= today]
            if not options:
                options = [before]
            options_text = " או ".join(f"ליום {want} {x.strftime('%d.%m.%Y')}" for x in options)
            return (f"רק לוודא — {dt.strftime('%d.%m.%Y')} יוצא ביום {actual}, וביקשת {pair.group(1)} עד {pair.group(2)}. "
                    f"התכוונת {options_text}? או שנשנה את ימי הנסיעה?")
    return None


def _post_claude(key, model, system_static, system_dynamic, history, message, max_tokens, include_history=True, source="other"):
    """system_static is the large, unchanging instruction block (thousands of
    tokens, identical on every call) - marked cacheable so Claude does not
    reprocess it from scratch on every chat turn. system_dynamic is the small
    per-turn suffix (current date, accumulated trip state) that must never be
    cached since it changes every call."""
    client = _get_anthropic_client(key)
    messages = _conversation(history[-16:] if include_history else [], message)
    system_blocks = [{"type": "text", "text": system_static, "cache_control": {"type": "ephemeral"}}]
    if system_dynamic:
        system_blocks.append({"type": "text", "text": system_dynamic})
    try:
        response = client.messages.create(
            model=model, max_tokens=max_tokens, system=system_blocks, messages=messages,
            # Reply generation and state extraction are both simple, well-specified
            # tasks (natural conversation, structured JSON) - extended thinking adds
            # latency here without improving output, so keep it off for speed.
            thinking={'type': 'disabled'},
        )
    except anthropic.APIStatusError as exc:
        record_ai_usage(source, model, usage=None, error=exc.status_code)
        raise RuntimeError(f'Claude API error {exc.status_code}') from exc
    record_ai_usage(source, model, usage=response.usage)
    return ''.join(block.text for block in response.content if block.type == 'text').strip()


def _parse_trip_update(text):
    raw = str(text or '').strip()
    if raw.startswith('```'):
        raw = raw.replace('```json', '', 1).replace('```', '').strip()
    try:
        data = json.loads(raw)
        if isinstance(data, dict) and isinstance(data.get('trip_update'), dict):
            return data['trip_update']
    except Exception:
        pass
    return {}


def _merge_trip_state(previous, incoming):
    """Recursively preserve collected trip facts; only meaningful new values overwrite them."""
    previous = previous if isinstance(previous, dict) else {}
    incoming = incoming if isinstance(incoming, dict) else {}
    merged = dict(previous)
    for key, value in incoming.items():
        old = merged.get(key)
        # A confirmed date choice is a replacement object, not a cumulative merge.
        # Otherwise stale candidate metadata (needs_confirmation/candidate_ranges)
        # survives beside the exact dates and makes Tinkerbell ask for dates again.
        if key == "dates" and isinstance(value, dict) and value.get("departure") and value.get("return") and value.get("needs_confirmation") is False:
            merged[key] = dict(value)
            continue
        if isinstance(value, dict):
            merged[key] = _merge_trip_state(old if isinstance(old, dict) else {}, value)
            continue
        # Extractor defaults/omissions must not erase facts already collected.
        if value is None or value == [] or value == {} or value == "unknown":
            if key in merged:
                continue
        # False is a valid explicit value for some fields, but for cumulative search
        # flags it must never undo a prior True.
        if key in {"search_intent", "ready_for_summary", "search_confirmed"} and old is True and value is False:
            continue
        # dates.needs_confirmation is the mirror case: once dates are genuinely
        # settled (False - the exact-dates replace branch above always writes
        # it False), it must never silently flip back to True except through
        # that same explicit replace path. Seen live: the extractor's JSON for
        # an unrelated turn (mid route-planning, nowhere near dates) came back
        # with needs_confirmation=true - maybe residual/default noise in its
        # output - and nothing here protected against it, so a resolved,
        # already-approved date range silently reopened as a "gap" again,
        # with the exact departure/return still sitting right next to it.
        # Tinkerbell then re-asked for dates deep into the flight-details
        # conversation as if the customer had never answered at all.
        if key == "needs_confirmation" and old is False and value is True:
            continue
        merged[key] = value
    return merged


def _state_context(state):
    return json.dumps(state or {}, ensure_ascii=False, separators=(',', ':'))


def _multi_gateway_hint(state):
    """When the destination matches a city genuinely served by more than one
    real airport (New York, Paris, London, Tokyo, Istanbul - see
    config.MULTI_GATEWAY_CITIES, itself built from the verified airport
    catalog) and no gateway choice has been made yet, hand Tinkerbell the
    real code/name list so it presents verified data instead of relying on
    its own recollection - the exact thing that produced an unconfirmed,
    unprompted "LaGuardia" mention (once even with a spelled-out name
    garbled into stray Cyrillic) with nothing in destination_airports to
    back it up."""
    state = state if isinstance(state, dict) else {}
    if state.get("destination_airports"):
        return None
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    places = [str(p).strip() for p in (destination.get("places") or []) if str(p).strip()]
    for place in places:
        for city, options in MULTI_GATEWAY_CITIES.items():
            if city in place or place in city:
                return {"city": city, "options": options}
    return None


def _keep_declines(previous, updated, explicit_request=None):
    """A service the customer already said no to stays declined. The
    extractor re-reads the whole history each turn and can resurrect an
    earlier "want a car" (or return session_status "pending" for it), which
    made Ariella ask about the car again right after the customer declined
    it. Only an explicit request for that service in this very message
    (_explicit_service_request) reopens it."""
    previous = previous if isinstance(previous, dict) else {}
    updated = updated if isinstance(updated, dict) else {}
    old_decisions = previous.get("service_decisions") if isinstance(previous.get("service_decisions"), dict) else {}
    decisions = dict(updated.get("service_decisions") or {})
    statuses = dict(updated.get("session_status") or {})
    for s in ("lodging", "car", "trip_planning"):
        old = old_decisions.get(s)
        if not (isinstance(old, dict) and old.get("wanted") is False) and old is not False:
            continue
        if explicit_request == s:
            continue
        decisions[s] = old
        statuses[s] = "declined"
        if updated.get("active_session") == s:
            updated["active_session"] = None
    updated["service_decisions"] = decisions
    updated["session_status"] = statuses
    return updated


def _parse_state_date(value):
    raw = str(value or "").strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(raw, fmt).date()
        except ValueError:
            pass
    return None


def _protect_car_details_from_loss(previous, updated):
    """vehicle_type/transmission keep vanishing once already answered - seen
    live repeatedly, most recently when trip_planning referenced the car
    ("לאילו ימים צריך רכב") while car itself wasn't the active_session: the
    very next car-related turn asked vehicle_type again from scratch, even
    though _merge_trip_state's own None/omitted-key handling should already
    protect it. Whatever the exact extractor path that drops it, once these
    two fields are genuinely set they must never revert to empty without the
    customer actually changing them - so force-restore them from the
    pre-turn state if the post-merge state lost them."""
    old_details = (previous.get("car") or {}).get("details") if isinstance(previous.get("car"), dict) else None
    if not isinstance(old_details, dict):
        return updated
    new_car = updated.get("car") if isinstance(updated.get("car"), dict) else {}
    new_details = new_car.get("details") if isinstance(new_car.get("details"), dict) else {}
    restored = dict(new_details)
    changed = False
    for field in ("vehicle_type", "transmission"):
        if old_details.get(field) and not restored.get(field):
            restored[field] = old_details[field]
            changed = True
    if changed:
        updated = dict(updated)
        updated["car"] = dict(new_car, details=restored)
    return updated


def _split_car_transmission(state):
    """Older conversations (and a model that slips) keep the gearbox inside
    vehicle_type ("SUV אוטומטי"). With transmission a required field, the
    car then never completed and Ariella asked about the car again although
    the customer had answered (seen live). Move it to its own field."""
    car = state.get("car") if isinstance(state.get("car"), dict) else None
    details = car.get("details") if car and isinstance(car.get("details"), dict) else None
    if not details or details.get("transmission"):
        return state
    vehicle = str(details.get("vehicle_type") or "")
    for word, value in (("אוטומט", "אוטומטי"), ("ידני", "ידני")):
        if word in vehicle:
            details = dict(details)
            details["transmission"] = value
            cleaned = re.sub(r"[,\s]*(?:תיבת הילוכים\s*)?\S*" + word + r"\S*", "", vehicle).strip(" ,")
            details["vehicle_type"] = cleaned or None
            state["car"] = dict(car, details=details)
            break
    return state


def _roll_past_dates(state, message, history):
    """Deterministic backstop for the "day+month without a year is its next
    future occurrence" rule. Seen live: in October 2026 the customer said
    "28.6" and the model saved 28.6.2026 - already past - so a return visit
    couldn't find the vacation (only future ones are offered), a new one
    was created, and its flight scan failed. A past departure moves forward
    a year, the return with it, unless the customer typed that year."""
    state = state if isinstance(state, dict) else {}
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else None
    if not dates:
        return state
    dep = _parse_state_date(dates.get("departure"))
    if not dep or dep >= date.today():
        return state
    user_text = " ".join(
        [str(x.get("content") or "") for x in (history or [])
         if isinstance(x, dict) and str(x.get("role") or "").lower() == "user"]
        + [str(message or "")]
    )
    if str(dep.year) in user_text:
        return state  # the customer named that year; the scan gate refuses it

    def _plus_years(d, n):
        try:
            return d.replace(year=d.year + n)
        except ValueError:  # 29 Feb
            return d.replace(year=d.year + n, day=28)

    years = 1
    while _plus_years(dep, years) < date.today():
        years += 1
    new_dates = dict(dates)
    new_dates["departure"] = _plus_years(dep, years).isoformat()
    ret = _parse_state_date(dates.get("return"))
    if ret:
        new_dates["return"] = _plus_years(ret, years).isoformat()
    state["dates"] = new_dates
    return state


def _sessionize_state(state):
    """Ariella owns the four-session lifecycle; Tinkerbell only converses around it."""
    state = state if isinstance(state, dict) else {}
    statuses = state.get("session_status") if isinstance(state.get("session_status"), dict) else {}
    statuses = {s: statuses.get(s, "pending") for s in ("flights","lodging","car","trip_planning")}
    decisions = state.get("service_decisions") if isinstance(state.get("service_decisions"), dict) else {}
    services = set(state.get("requested_services") or [])

    # Explicit decisions always win - except flights always comes first.
    # A "wanted: True" decision recorded for lodging/car/trip_planning while
    # flights isn't complete/declined yet (e.g. the customer asked for it
    # explicitly mid-flights and that request was deferred, not dropped)
    # must not auto-activate that session ahead of flights. The want is
    # still remembered in service_decisions/requested_services either way -
    # it just doesn't flip session_status to "active" until its turn.
    flights_settled = statuses.get("flights") in ("complete", "declined")
    for s in statuses:
        d = decisions.get(s)
        wanted = d.get("wanted") if isinstance(d, dict) else d
        if wanted is False:
            statuses[s] = "declined"
        elif wanted is True:
            services.add(s)
            if s != "flights" and not flights_settled:
                continue
            if statuses[s] in ("pending", "declined"):
                statuses[s] = "active"

    # A destination/trip request implies flights unless explicitly declined.
    dest = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    fd = decisions.get("flights")
    fw = fd.get("wanted") if isinstance(fd, dict) else fd
    if dest.get("places") and fw is not False:
        services.add("flights")
        if statuses["flights"] == "pending":
            statuses["flights"] = "active"

    # A business trip or a single-resort ski trip has no natural use for
    # day-by-day multi-city itinerary/attraction planning. Default
    # trip_planning to declined unless the customer explicitly asked for it
    # (an explicit decision above already won).
    _trip_type = str(state.get("trip_type") or "").lower()
    if _trip_type in ("business", "ski") and decisions.get("trip_planning") is None and statuses["trip_planning"] == "pending":
        statuses["trip_planning"] = "declined"
        decisions = dict(decisions)
        decisions["trip_planning"] = {"wanted": False, "source": f"{_trip_type}_trip_default"}

    # Keep one active session. Respect an existing unfinished active session first.
    active = state.get("active_session")
    if active not in statuses or statuses.get(active) in ("complete","declined"):
        active = None
    if not active:
        # "flights" is the domain most likely to get auto-marked active purely
        # from a destination being known (see the block above), so it must not
        # win this tie-break over a session the customer explicitly chose.
        active = next((s for s in ("trip_planning","lodging","car","flights") if statuses[s] == "active"), None)

    state["requested_services"] = list(dict.fromkeys(list(state.get("requested_services") or []) + list(services)))
    state["session_status"] = statuses
    state["service_decisions"] = decisions
    state["active_session"] = active
    return state


def _session_gaps(state, session):
    """Required facts for one session only."""
    all_gaps = _required_state_gaps(state)
    prefixes = {
        # trip_type only gates the flights session (it affects date-flex/cabin
        # behavior there). Requiring it for every session risks permanently
        # stalling lodging/car/trip_planning if the opening question was ever
        # skipped, since none of those sessions have a natural place to ask it.
        "flights": ("trip_type","destination","dates","travelers","departure_airport","flight.","budget_per_person"),
        "lodging": ("destination","dates","travelers","lodging."),
        "car": ("destination","dates","travelers","car."),
        "trip_planning": ("destination","dates","travelers","trip_planning."),
    }
    allowed = prefixes.get(session, ())
    return [g for g in all_gaps if any(g == p or g.startswith(p) for p in allowed)]


def _advance_sessions(state):
    """Complete the active session when full, then expose exactly one next session decision.

    Per product owner (explicit instruction): the actual flight/lodging/car/
    route search only ever launches once after EVERY requested domain has
    reached a final answer (complete or declined) - never earlier. Since
    nothing executes the moment flights alone finish, flights no longer
    needs its own separate מאשר/מאשרת approval gate mid-conversation either;
    it now closes itself exactly like lodging/car/trip_planning do, the
    moment its own required fields are known ("התחום נסגר מעצמו כשכל
    הפרטים שלו ידועים" - the same rule the prompt already states for the
    other three). The single real approval/"מאשר/מאשרת" moment is the
    ready_for_summary=True branch below, which only fires once ALL FOUR
    domains are complete/declined - i.e. once there is genuinely one
    combined request left to confirm, not four separate ones.
    """
    state = _sessionize_state(state)
    statuses = dict(state.get("session_status") or {})
    active = state.get("active_session")

    if active and not _session_gaps(state, active):
        statuses[active] = "complete"
        active = None

    # Never auto-activate a new domain merely because it is pending. The next
    # pending domain becomes a yes/no decision for Tinkerbell. Fixed order
    # per product owner, regardless of which topic the customer started
    # with: flights, then the itinerary/route, then lodging, then car.
    # In practice flights is never actually offered this way - a known
    # destination auto-activates it immediately (see _sessionize_state) -
    # but the fallback stays correct/harmless for the rare case it isn't.
    next_pending = next((s for s in ("flights","trip_planning","lodging","car") if statuses.get(s) == "pending"), None)
    if not active:
        active = next((s for s in ("flights","trip_planning","lodging","car") if statuses.get(s) == "active"), None)

    state["session_status"] = statuses
    state["active_session"] = active
    if active:
        state["missing_required"] = _session_gaps(state, active)
        state["next_session"] = None
        state["ready_for_summary"] = False
    elif next_pending:
        state["missing_required"] = []
        state["next_session"] = next_pending
        state["ready_for_summary"] = False
    else:
        state["missing_required"] = []
        state["next_session"] = None
        state["ready_for_summary"] = all(v in ("complete","declined") for v in statuses.values())
    return state


_TRIP_PLANNING_REQUEST_WORDS = ("מסלול", "מסלולים", "אטרקציות", "אטרקציה", "תכנון טיול", "לתכנן")


def _reject_unrequested_trip_planning_activation(trip_state, trip_update, message, history=None):
    """trip_planning has no mandatory default the way flights does (a
    destination alone implies flights are wanted - see _sessionize_state).
    Lodging/car already require a genuine wanted=true decision before they
    can go "active" (see the "A 'wanted: True' decision..." comment in
    _sessionize_state); trip_planning must be held to the exact same bar,
    but the extractor can still slip and set service_decisions.trip_
    planning.wanted=true from indirect context (a destination/route name
    mentioned while discussing something else) without the customer ever
    actually asking for route help. Seen live, twice: right after a flight
    summary / right after picking a departure airport, Tinkerbell pivoted
    straight into "בואי נתכנן את המסלול..." with no yes/no question at
    all - the session had already gone "active" on its own.

    A first version of this check trusted service_decisions.trip_planning.
    wanted itself as evidence a want was "already recorded on an earlier
    turn" - but that is exactly the value the extractor can corrupt, and it
    can corrupt it quietly on a turn where trip_planning isn't active yet
    (still gated behind flights), so by the time it does activate the flag
    already reads wanted=true with nothing genuine behind it. Checked here
    instead, every time trip_planning newly activates: does ANY user
    message in the actual conversation (not the extractor's derived flag)
    contain real route/itinerary language? Declining trip_planning
    explicitly ("לא רוצה לתכנן מסלול") already works correctly today
    (lodging/car get asked normally afterward) - this only covers the
    silent-activation side."""
    prev_status = str(((trip_state or {}).get("session_status") or {}).get("trip_planning") or "")
    new_statuses = (trip_update or {}).get("session_status") if isinstance(trip_update, dict) else None
    if not isinstance(new_statuses, dict) or new_statuses.get("trip_planning") != "active" or prev_status == "active":
        return trip_update
    # A structured "want help with the route too?" offer (post_flight_offer,
    # asked explicitly once flights/lodging/car close) that the customer
    # just answered yes to is already a genuine decision by construction -
    # it must never be reverted just because the customer's own short reply
    # ("כן בבקשה") doesn't happen to repeat a route keyword. This guard
    # exists to catch the extractor inventing intent from indirect context,
    # not to second-guess an explicit deterministic offer/answer pair.
    decisions_now = trip_update.get("service_decisions") if isinstance(trip_update, dict) else None
    planning_decision = (decisions_now or {}).get("trip_planning") if isinstance(decisions_now, dict) else None
    if isinstance(planning_decision, dict) and planning_decision.get("source") == "post_flight_offer":
        return trip_update
    user_texts = [str(message or "")]
    for item in (history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "user":
            user_texts.append(str(item.get("content") or ""))
    combined = " ".join(user_texts)
    if any(k in combined for k in _TRIP_PLANNING_REQUEST_WORDS):
        return trip_update
    trip_update = dict(trip_update)
    statuses = dict(new_statuses)
    statuses["trip_planning"] = "pending"
    trip_update["session_status"] = statuses
    decisions = dict(trip_update.get("service_decisions") or {})
    decisions.pop("trip_planning", None)
    trip_update["service_decisions"] = decisions
    if trip_update.get("active_session") == "trip_planning":
        trip_update["active_session"] = None
    return trip_update


def _direct_route_available(state):
    """True when the requested destination has a known nonstop route from the selected Israeli origin."""
    state = state if isinstance(state, dict) else {}
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    places = destination.get("places") if isinstance(destination.get("places"), list) else []
    # destination_airports (the already-resolved IATA gateway codes, e.g.
    # ["LCA","PFO"] for Cyprus) is the authoritative source once it exists -
    # `places` is free text ("קפריסין") that only happens to BE an IATA code
    # when the customer typed one directly, or matches the small Thailand-
    # city alias list below. Without destination_airports, any destination
    # resolved from a country/city name (the common case) always fell
    # through to codes=[] and this returned False unconditionally, so the
    # direct-vs-connection question never got asked and never made it into
    # the summary - regardless of whether a real nonstop route existed.
    destination_airports = state.get("destination_airports") if isinstance(state.get("destination_airports"), list) else []
    if not places and not destination_airports:
        return False
    origin = str(state.get("departure_airport") or "TLV").strip().upper()
    aliases = {
        "תאילנד":["BKK","HKT"], "thailand":["BKK","HKT"],
        "בנגקוק":["BKK"], "bangkok":["BKK"], "פוקט":["HKT"], "phuket":["HKT"],
    }
    codes = [str(c or "").strip().upper() for c in destination_airports if str(c or "").strip()]
    for place in places:
        raw = str(place or "").strip()
        upper = raw.upper()
        if len(upper) == 3 and upper.isalpha():
            codes.append(upper)
        codes.extend(aliases.get(raw.lower(), aliases.get(raw, [])))
    codes = list(dict.fromkeys(codes))
    if not codes:
        return False
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    departure = str(dates.get("departure") or "")[:10]
    try:
        conn = sqlite3.connect(DB_PATH, timeout=10)
        marks = ",".join("?" for _ in codes)
        sql = f"""SELECT 1 FROM direct_routes
                  WHERE origin_code=? AND destination_code IN ({marks}) AND status='active'
                    AND (valid_from IS NULL OR valid_from='' OR ?='' OR valid_from<=?)
                    AND (valid_to IS NULL OR valid_to='' OR ?='' OR valid_to>=?)
                  LIMIT 1"""
        row = conn.execute(sql, [origin, *codes, departure, departure, departure, departure]).fetchone()
        conn.close()
        return bool(row)
    except Exception:
        return False


def _resolve_destination_airports_from_route(state):
    """Deterministic safety net: once trip planning has confirmed a day-by-day
    route, derive the flight gateway from it (or from a plain destination name)
    the same way the scanner resolves free-text places to IATA codes, instead
    of relying on the extractor to remember to copy it over every turn. Without
    this, returning to the flight session after route planning can re-ask a
    question the route itself already answered."""
    state = state if isinstance(state, dict) else {}
    # A ski trip's gateway airports come only from the ski resort catalog
    # (see _resolve_ski_destination_airports) - the general airport catalog
    # would happily match a country to its capital's airport, which is
    # usually the wrong gateway for skiing (e.g. Vienna for Austria, instead
    # of Innsbruck/Salzburg/Munich).
    if str(state.get("trip_type") or "").lower() == "ski":
        return state
    planning = state.get("trip_planning") if isinstance(state.get("trip_planning"), dict) else {}
    details = planning.get("details") if isinstance(planning.get("details"), dict) else {}
    route = details.get("route") if isinstance(details.get("route"), list) else []
    names = []
    for day in route:
        if isinstance(day, dict):
            base = day.get("base") or day.get("city") or day.get("region")
            if base:
                names.append(str(base))
    # A confirmed day-by-day route is itself the authoritative gateway
    # decision, even when destination_airports already holds a broader set
    # of candidates picked before route planning started (e.g. both Larnaca
    # and Paphos for "Cyprus" before the customer said "same airport in and
    # out" and the route settled on Larnaca only). Only skip re-deriving
    # here when there is no route to derive from - in that case fall back to
    # the old "don't override an already-resolved value from a plain
    # destination name" behavior, since a bare destination name is less
    # precise than whatever already got resolved and must not clobber it.
    if not names:
        if state.get("destination_airports"):
            return state
        destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
        names = [str(p) for p in (destination.get("places") or []) if p]
    if not names:
        return state
    airports = _load_airports()
    codes = []
    for name in names:
        needle = str(name).strip().lower()
        if not needle:
            continue
        for airport in airports:
            hay = " ".join(str(airport.get(k) or "") for k in ("country_he", "country_en", "city_he", "city_en")).lower()
            if hay and (needle in hay or hay in needle):
                code = str(airport.get("code") or "").upper()
                if code and code not in codes:
                    codes.append(code)
    if not codes:
        return state
    if codes[:4] == (state.get("destination_airports") or []):
        return state
    state = dict(state)
    state["destination_airports"] = codes[:4]
    return state


def _resolve_lodging_locations_from_route(state):
    """An approved day-by-day route already says where the customer sleeps
    each night (each day's base/city/region) - once lodging search opens
    for the SAME vacation, pull that straight in instead of asking the
    customer to repeat what they already told Ariella in trip_planning.
    Mirrors _resolve_destination_airports_from_route's own extraction of
    each day's base, this time into lodging.details.locations."""
    state = state if isinstance(state, dict) else {}
    lodging = state.get("lodging") if isinstance(state.get("lodging"), dict) else {}
    details = lodging.get("details") if isinstance(lodging.get("details"), dict) else {}
    if details.get("areas") or details.get("locations"):
        return state
    planning = state.get("trip_planning") if isinstance(state.get("trip_planning"), dict) else {}
    planning_details = planning.get("details") if isinstance(planning.get("details"), dict) else {}
    route = planning_details.get("route") if isinstance(planning_details.get("route"), list) else []
    names = []
    for day in route:
        if isinstance(day, dict):
            base = day.get("base") or day.get("city") or day.get("region")
            if base and str(base) not in names:
                names.append(str(base))
    if not names:
        return state
    state = dict(state)
    lodging = dict(lodging)
    details = dict(details)
    details["locations"] = ", ".join(names)
    lodging["details"] = details
    state["lodging"] = lodging
    return state


def _resolve_ski_destination_airports(state):
    """Ski gateway airports come from the ski resort catalog, not the general
    airport catalog: matching a country/resort name against SKI_RESORTS and
    deriving destination_airports from the matched resorts' own gateway
    airports (e.g. Austria -> INN/ZRH/MUC/SZG, not Vienna). Also records
    which resorts matched, needed later so the search/scoring layer can
    match offers back to a specific resort."""
    state = state if isinstance(state, dict) else {}
    if str(state.get("trip_type") or "").lower() != "ski":
        return state
    # A broad country-level match (e.g. Austria -> INN/ZRH/MUC/SZG, covering
    # every resort in the country) can set destination_airports before the
    # customer has agreed on one specific resort. Only skip re-resolving once
    # a specific resort has actually been pinned down (ski.resort_names) -
    # otherwise a later turn where Ariella recommends a resort and the
    # customer agrees would never narrow the broad match down to it.
    if state.get("destination_airports") and (state.get("ski") or {}).get("resort_names"):
        return state
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    places = [str(p) for p in (destination.get("places") or []) if str(p).strip()]
    if not places:
        return state
    # Match against the specific resort name first. destination.places often
    # holds BOTH a country and a resort together (e.g. ["איטליה", "סטרייר"] -
    # seen live as "יעד: איטליה, אזור סקי סטרייר"), and matching every place
    # string against country+resort together let the broad "איטליה" entry
    # match every single Italian resort in the catalog, unioning all of
    # their gateway airports into one destination_airports list (6 airports
    # across 6 different resorts for what the customer named as one specific
    # resort) and listing all 6 as "matched" for scoring too. A named resort
    # is always more specific than a country, so once any place string names
    # an actual resort, only resort-level matches are used; country-level
    # matching is a fallback for when no place names a specific resort at all.
    resort_matches = []
    for place in places:
        needle = place.strip().lower()
        if not needle:
            continue
        for row in SKI_RESORTS:
            # resort_he is the Hebrew transliteration - without it, a Hebrew
            # place string could never match the catalog's English-only
            # resort names at all, silently falling through to the broad
            # country-level match every time regardless of how specific the
            # customer's own wording was.
            for hay in (str(row.get("resort") or "").lower(), str(row.get("resort_he") or "").lower()):
                if hay and (needle in hay or hay in needle):
                    resort_matches.append(row)
                    break
    if resort_matches:
        matched_rows = resort_matches
    else:
        matched_rows = []
        for place in places:
            needle = place.strip().lower()
            if not needle:
                continue
            for row in SKI_RESORTS:
                hay = " ".join(str(row.get(k) or "") for k in ("country", "country_he", "resort")).lower()
                if needle in hay or hay in needle:
                    matched_rows.append(row)
    if not matched_rows:
        return state
    resort_names = []
    codes = []
    for row in matched_rows:
        name = str(row.get("resort") or "")
        if name and name not in resort_names:
            resort_names.append(name)
        for code in (row.get("gateway_airports") or []):
            code = str(code).upper()
            if code and code not in codes:
                codes.append(code)
    if not codes:
        return state
    state = dict(state)
    state["destination_airports"] = codes[:6]
    ski_state = dict(state.get("ski") or {})
    ski_state["resort_names"] = resort_names
    state["ski"] = ski_state
    return state


def _narrow_ski_gateway_airport(state, message):
    """A ski resort usually has several candidate gateway airports (see
    _resolve_ski_destination_airports above), and once set they are never
    narrowed again by that function. Seen live: the customer asked for
    "ורונה, שדה קרוב לאתר הסקי, ללא קונקשיין" (Verona specifically, per
    Ariella's own recommendation) and still got results for every other
    candidate gateway too, with cheaper connecting flights elsewhere
    outranking the one Verona option. Once the customer's own message
    names exactly one of the currently-candidate airports by city/airport
    name, lock destination_airports down to that one - a named choice is
    always more specific than the full candidate set."""
    state = state if isinstance(state, dict) else {}
    if str(state.get("trip_type") or "").lower() != "ski":
        return state
    codes = state.get("destination_airports") if isinstance(state.get("destination_airports"), list) else []
    if len(codes) <= 1:
        return state
    needle = str(message or "").strip().lower()
    if not needle:
        return state
    by_code = {str(a.get("code") or "").upper(): a for a in _load_airports()}
    matched = []
    for code in codes:
        info = by_code.get(code)
        if not info:
            continue
        names = (
            str(info.get("city_he") or ""), str(info.get("city_en") or ""),
            str(info.get("name_he") or ""), str(info.get("name_en") or ""),
        )
        if any(name and len(name) >= 3 and name.lower() in needle for name in names):
            matched.append(code)
    if len(matched) == 1 and matched != codes:
        state = dict(state)
        state["destination_airports"] = matched
    return state


_GATEWAY_KEEP_BOTH_PHRASES = (
    "שניהם", "גם וגם", "אין העדפה", "לא משנה", "כולם",
    "את כל השדות", "להשאיר את שניהם", "תשאירי את שניהם", "תשאיר את שניהם",
)


def _narrow_gateway_airport_after_route(state, message):
    """Per product owner (Carmit, confirmed explicitly): once the customer
    has explicitly requested trip_planning AND the route is approved, if
    more than one candidate gateway airport is still open in
    destination_airports, Ariella goes back and asks whether to narrow down
    to one specific airport - to save scan budget - instead of silently
    searching every open gateway. See the "flight.gateway_narrow" gap in
    _required_state_gaps/_flight_gap_question for the question itself; this
    function only resolves the customer's one answer to it: a named airport
    narrows destination_airports down to it, an explicit "keep both/all"
    answer (שניהם/גם וגם/...) records the decision instead so the question
    is never asked twice.

    This is a narrow, one-time exception to the "destination_airports
    already set is closed, never raise an alternative" rule in the system
    prompt - it only fires in the specific post-route-approval window
    (planning.approved is True), never otherwise, so it cannot be confused
    with second-guessing an already-settled choice mid-conversation.

    Deliberately excludes ski trips: _narrow_ski_gateway_airport above
    already covers gateway-narrowing there on its own terms (any turn, not
    gated on route approval), since a ski resort's candidate gateways are a
    different kind of choice than this one.
    """
    state = state if isinstance(state, dict) else {}
    if str(state.get("trip_type") or "").lower() == "ski":
        return state
    planning = state.get("trip_planning") if isinstance(state.get("trip_planning"), dict) else {}
    if not planning.get("approved") or state.get("gateway_narrow_declined"):
        return state
    codes = state.get("destination_airports") if isinstance(state.get("destination_airports"), list) else []
    if len(codes) <= 1:
        return state
    needle = str(message or "").strip().lower()
    if not needle:
        return state
    if any(p in needle for p in _GATEWAY_KEEP_BOTH_PHRASES):
        state = dict(state)
        state["gateway_narrow_declined"] = True
        return state
    by_code = {str(a.get("code") or "").upper(): a for a in _load_airports()}
    matched = []
    for code in codes:
        info = by_code.get(code)
        if not info:
            continue
        names = (
            str(info.get("city_he") or ""), str(info.get("city_en") or ""),
            str(info.get("name_he") or ""), str(info.get("name_en") or ""),
        )
        if any(name and len(name) >= 3 and name.lower() in needle for name in names):
            matched.append(code)
    if len(matched) == 1 and matched != codes:
        state = dict(state)
        state["destination_airports"] = matched
        state["gateway_narrow_declined"] = True
    return state


def _required_state_gaps(state):
    """Return the authoritative unanswered decisions Ariella needs for requested services."""
    state = state if isinstance(state, dict) else {}
    services = set(state.get("requested_services") or [])
    decisions = state.get("service_decisions") if isinstance(state.get("service_decisions"), dict) else {}
    for service in ("flights", "lodging", "car", "trip_planning"):
        decision = decisions.get(service)
        wanted = decision.get("wanted") if isinstance(decision, dict) else decision
        if wanted is True:
            services.add(service)

    gaps = []
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    travelers = state.get("travelers") if isinstance(state.get("travelers"), dict) else {}
    flight = state.get("flight") if isinstance(state.get("flight"), dict) else {}
    lodging = state.get("lodging") if isinstance(state.get("lodging"), dict) else {}
    car = state.get("car") if isinstance(state.get("car"), dict) else {}
    planning = state.get("trip_planning") if isinstance(state.get("trip_planning"), dict) else {}
    lodging_details = lodging.get("details") if isinstance(lodging.get("details"), dict) else {}
    car_details = car.get("details") if isinstance(car.get("details"), dict) else {}
    planning_details = planning.get("details") if isinstance(planning.get("details"), dict) else {}

    # Shared trip facts.
    if services and not state.get("trip_type"):
        gaps.append("trip_type")
    if services and not (destination.get("places") or []):
        gaps.append("destination")
    if services and (dates.get("needs_confirmation") or not (dates.get("departure") and dates.get("return"))):
        gaps.append("dates")
    if services and travelers.get("adults") is None:
        gaps.append("travelers")
    children_count = int(travelers.get("children") or 0)
    child_ages = travelers.get("child_ages") if isinstance(travelers.get("child_ages"), list) else []
    if services and children_count > 0 and len(child_ages) < children_count:
        gaps.append("travelers.child_ages")

    # First establish whether each of the four domains is wanted. A trip request
    # with a destination implies flights unless the user explicitly says flights
    # are already booked/not needed.
    for service in ("flights", "lodging", "car", "trip_planning"):
        decision = decisions.get(service)
        explicit = decision.get("wanted") if isinstance(decision, dict) else decision
        if service not in services and explicit is None:
            gaps.append("service_decisions." + service)

    if "flights" in services:
        if not state.get("departure_airport"):
            gaps.append("departure_airport")
        # Country/region and flight gateway are separate facts. Broad geographic
        # requests must not silently resolve to an arbitrary airport.
        destination_airports = state.get("destination_airports") if isinstance(state.get("destination_airports"), list) else []
        destination_mode = str(destination.get("mode") or "").lower()
        # A ski gateway always needs the catalog resolution regardless of
        # how specific the stated destination is (even a named resort still
        # needs its gateway airports derived from the ski catalog).
        is_ski_trip = str(state.get("trip_type") or "").lower() == "ski"
        if (is_ski_trip or destination_mode in {"country","region","area","broad"}) and not destination_airports:
            gaps.append("destination_airports")
        # Per product owner (Carmit, confirmed explicitly): once the customer
        # genuinely requested trip_planning and its route is approved, more
        # than one still-open candidate gateway airport is a real decision
        # still owed to the customer - ask whether to narrow to one (saves
        # scan budget) instead of silently searching every candidate.
        # Deliberately scoped tight: only fires once trip_planning was
        # actually requested AND its route is approved - never a general
        # override of "destination_airports already set is closed" (see the
        # system prompt rule covering that for every other case). Also never
        # fires once flights itself is already complete/declined: the whole
        # point is saving scan budget on a search that hasn't run yet, so a
        # flight search already closed in an earlier turn (route planned
        # only afterward) must not be reopened to ask this retroactively.
        flights_status = str((state.get("session_status") or {}).get("flights") or "")
        if (not is_ski_trip and "trip_planning" in services and planning.get("approved")
                and len(destination_airports) > 1 and not state.get("gateway_narrow_declined")
                and flights_status not in ("complete", "declined")):
            gaps.append("flight.gateway_narrow")
        # Return gateway defaults to the outbound arrival gateway. It is only a
        # separate required fact when the customer explicitly asks for open-jaw.
        return_airports = state.get("return_departure_airports") if isinstance(state.get("return_departure_airports"), list) else []
        if state.get("open_jaw_requested") and not return_airports:
            gaps.append("return_departure_airports")
        # Ask direct-vs-connection only when a verified nonstop route exists
        # for this origin/destination/date. Otherwise connections are simply ranked results.
        if _direct_route_available(state) and not flight.get("connection_preference"):
            gaps.append("flight.connection_preference")
        if not flight.get("baggage"):
            gaps.append("flight.baggage")
        budget = state.get("budget_per_person") if isinstance(state.get("budget_per_person"), dict) else {}
        if budget.get("amount") is None and budget.get("status") not in ("unlimited","none","no_limit"):
            gaps.append("budget_per_person")

    if "lodging" in services:
        if not lodging_details.get("type"):
            gaps.append("lodging.details.type")
        if not (lodging_details.get("bedrooms") or lodging_details.get("rooms")):
            gaps.append("lodging.details.rooms")
        if not (lodging_details.get("areas") or lodging_details.get("locations")):
            gaps.append("lodging.details.locations")
        if not (lodging_details.get("budget") or lodging_details.get("level")):
            gaps.append("lodging.details.budget_or_level")

    if "car" in services:
        if not (car_details.get("vehicle_type") or car_details.get("size")):
            gaps.append("car.details.vehicle_type")
        if not car_details.get("transmission"):
            gaps.append("car.details.transmission")
        # A time is welcome but never required: before the flights are
        # booked the customer can't know it (per product owner), and the
        # rental site asks for it at booking anyway.
        if not car_details.get("pickup"):
            gaps.append("car.details.pickup")
        if not car_details.get("return"):
            gaps.append("car.details.return")
        # Luggage fit is something Ariella mentions when choosing the vehicle
        # category, not a separate gate: as a hidden required flag the model
        # had to set, it kept the car session open after every visible
        # detail was answered, and Ariella asked for an extra confirmation.
        if not car_details.get("luggage_capacity_confirmed") and not (car_details.get("vehicle_type") or car_details.get("seats")):
            gaps.append("car.details.luggage_capacity")

    if "trip_planning" in services:
        if not (planning_details.get("style") or planning_details.get("interests")):
            gaps.append("trip_planning.details.style")
        if not planning_details.get("pace"):
            gaps.append("trip_planning.details.pace")
        if not (planning_details.get("route") or planning_details.get("daily_plan")):
            gaps.append("trip_planning.details.route")
        # A route the extractor saved is only PROPOSED. Seen live: the
        # session auto-completed the moment one was written into state, Ariella
        # jumped straight to flight questions, and the approval step (which
        # also saves the itinerary text for the attractions card) never ran.
        elif not planning.get("approved"):
            gaps.append("trip_planning.approved")

    return list(dict.fromkeys(gaps))


def _country_airports(country, limit=4):
    """The member's country's airports from the catalog, offered as choices
    (the catalog isn't ordered by size, so none is guessed as "the" main
    one - e.g. its first GB entry is Gatwick, not Heathrow)."""
    if not country:
        return []
    codes = [str(a.get("code") or "").upper() for a in _load_airports()
             if str(a.get("country") or "").upper() == country and a.get("code")]
    # A big country (US: Boston, Chicago, LA, Miami...) isn't narrowed by a
    # handful of arbitrary cities - an open question fits better there.
    return codes if len(codes) <= limit else []


def _apply_home_airport(state):
    """Departure default from the customer's own registration data, never a
    fixed country (per product owner - the site serves every country):
    - one preferred airport: use it; Ariella names it in the summary and the
      customer can change it;
    - several: ask only among them;
    - none chosen: offer their country's airports as choices.
    Never overrides an airport the customer named in the conversation."""
    state = state if isinstance(state, dict) else {}
    profile = state.get("profile") if isinstance(state.get("profile"), dict) else {}
    home = [c for c in (profile.get("home_airports") or []) if c]
    if state.get("departure_airport"):
        # The customer named another airport in the chat: it's no longer
        # the registration default.
        if state.get("departure_airport_source") == "profile" and state["departure_airport"] not in home:
            state.pop("departure_airport_source", None)
        state.pop("departure_options", None)
        return state
    if len(home) == 1:
        state["departure_airport"] = home[0]
        state["departure_airport_source"] = "profile"
        state.pop("departure_options", None)
    elif len(home) > 1:
        state["departure_options"] = home
    else:
        options = _country_airports(profile.get("country"))
        if options:
            state["departure_options"] = options
    return state


def _airport_labels(codes):
    """Hebrew names, with the IATA code added where two share a city name
    (London: LGW/LHR/LTN/STN)."""
    names = [AIRPORT_NAMES.get(c, c) for c in codes]
    return [f"{n} ({c})" if names.count(n) > 1 else n for n, c in zip(names, codes)]


def _departure_question(state):
    options = (state or {}).get("departure_options") or []
    names = _airport_labels(options)
    if len(names) == 1:
        return f"נטוס מ{names[0]}, או משדה אחר?"
    if names:
        return "מאיזה שדה נטוס - " + ", ".join(names[:-1]) + " או " + names[-1] + "?"
    return "מאיזה שדה תעופה תרצי לטוס?"


def _flight_summary_text(state):
    """Deterministic flight-request summary built straight from state - the
    honest fallback when the claims_execution safety net catches Tinkerbell
    prematurely claiming a search already started, but the flight session is
    genuinely ready for approval (no real gap left). Seen live: the customer
    answered the last missing fact (budget) and got nothing but "you must
    type מאשרת" with zero summary of what she'd actually be approving -
    confusing on its own, and the opposite of the system prompt's own rule
    that a summary must always precede the approval request."""
    state = state if isinstance(state, dict) else {}
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    places = [str(p) for p in (destination.get("places") or []) if str(p or "").strip()]
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    travelers = state.get("travelers") if isinstance(state.get("travelers"), dict) else {}
    flight = state.get("flight") if isinstance(state.get("flight"), dict) else {}
    budget = state.get("budget_per_person") if isinstance(state.get("budget_per_person"), dict) else {}

    def he_date(iso):
        iso = str(iso or "")[:10]
        parts = iso.split("-")
        return f"{parts[2]}.{parts[1]}.{parts[0]}" if len(parts) == 3 else iso

    lines = []
    if places:
        lines.append("יעד: " + ", ".join(places))
    dep, ret = dates.get("departure"), dates.get("return")
    if dep and ret:
        lines.append(f"תאריכים: {he_date(dep)} – {he_date(ret)}")
    departure_airport = state.get("departure_airport")
    if departure_airport:
        lines.append(f"שדה יציאה: {departure_airport}")
    adults = travelers.get("adults")
    children = int(travelers.get("children") or 0)
    if adults:
        party = f"{adults} מבוגרים" if adults != 1 else "מבוגר אחד"
        if children:
            party += (f" ו-{children} ילדים" if children != 1 else " וילד אחד")
        lines.append("נוסעים: " + party)
    connection = str(flight.get("connection_preference") or "").lower()
    if connection:
        lines.append("טיסה ישירה בלבד" if "direct" in connection or "nonstop" in connection else "ישירה או עם קונקשן")
    baggage = flight.get("baggage") or []
    baggage_labels = {"carry_on_only": "טרולי בלבד", "checked_bag": "כולל מזוודה בבטן המטוס", "personal_item": "תיק קטן בלבד"}
    if baggage:
        lines.append("כבודה: " + ", ".join(baggage_labels.get(b, b) for b in baggage))
    dep_time_pref = str(flight.get("departure_time_preference") or "").strip()
    ret_time_pref = str(flight.get("return_time_preference") or "").strip()
    if dep_time_pref or ret_time_pref:
        parts = []
        if dep_time_pref:
            parts.append(f"הלוך {dep_time_pref}")
        if ret_time_pref:
            parts.append(f"חזור {ret_time_pref}")
        lines.append("שעת טיסה מועדפת: " + ", ".join(parts))
    if budget.get("status") == "unlimited":
        lines.append("תקציב: ללא הגבלה")
    elif budget.get("amount"):
        lines.append(f"תקציב לאדם: {budget.get('amount')} {budget.get('currency') or '₪'}")
    if not lines:
        return None

    gender = str(state.get("user_gender") or "").lower()
    if gender == "male":
        approval_line = "אם כל הפרטים נכונים, כתוב מאשר."
    elif gender == "female":
        approval_line = "אם כל הפרטים נכונים, כתבי מאשרת."
    else:
        approval_line = "אם כל הפרטים נכונים, יש לרשום מאשר/מאשרת."
    return "סיכום בקשת הטיסה:\n" + "\n".join(lines) + "\n\n" + approval_line


def _flight_gap_question(gaps, state=None):
    """Map a _session_gaps(..., "flights") result to the one specific
    question that actually resolves it. Shared by the approval-time gap
    handling and the false-approval-claim safety net below, so both ask the
    same real, concrete question instead of a generic "something is
    missing" line the customer has no way to act on."""
    gaps = gaps or []
    if "destination_airports" in gaps:
        return "לפני שאצא לסריקה צריך להשלים את שדה היעד לנחיתה בהלוך. באיזה שדה תרצי לנחות?"
    if "flight.gateway_narrow" in gaps:
        codes = (state or {}).get("destination_airports") or []
        names = _airport_labels(codes)
        listed = ", ".join(names[:-1]) + " או " + names[-1] if len(names) >= 2 else ", ".join(names)
        return (
            f"המסלול אושר! יש כמה שדות תעופה אפשריים ליעד הזה ({listed}). "
            "תרצי שאצמצם את חיפוש הטיסות לשדה אחד כדי לחסוך בסריקות, או להמשיך לחפש בשניהם?"
        )
    if "return_departure_airports" in gaps:
        return "ציינת שתרצי לחזור משדה אחר. מאיזה שדה תרצי לצאת בחזור?"
    if "budget_per_person" in gaps:
        return "לפני הסריקה חסר לי התקציב לאדם. מה התקציב, או שאין מגבלת תקציב?"
    if "departure_airport" in gaps:
        return "לפני הסריקה חסר לי שדה היציאה. " + _departure_question(state)
    if "trip_type" in gaps:
        return "רק לפני שממשיכים - זו חופשה רגילה, נסיעת עסקים, או חופשת סקי?"
    if "destination" in gaps:
        return "לפני הסריקה חסר לי היעד. לאן תרצי לטוס?"
    if "dates" in gaps:
        return "לפני הסריקה חסרים לי תאריכי הטיסה המדויקים. מתי תרצי לצאת ולחזור?"
    if "travelers" in gaps:
        return "לפני הסריקה חסר לי הרכב הנוסעים. כמה נוסעים, ומי מבוגר ומי ילד?"
    if "travelers.child_ages" in gaps:
        return "חסר לי הגיל של הילד/ה בהרכב הנוסעים. מה הגיל?"
    if "flight.connection_preference" in gaps:
        return "חשוב לך שהטיסה תהיה ישירה, או שקונקשן בסדר?"
    if "flight.baggage" in gaps:
        return "לפני הסריקה חסר לי פרטי הכבודה - טרולי בלבד, גם מזוודה בבטן המטוס, או רק תיק?"
    missing_service = next((g.split(".",1)[1] for g in gaps if g.startswith("service_decisions.")), None)
    if missing_service:
        labels = {"lodging":"גם לינה","car":"גם רכב שכור","trip_planning":"גם תכנון מסלול ואטרקציות"}
        return f"רק לפני שממשיכים - תרצי {labels.get(missing_service, missing_service)} לחופשה הזו?"
    if gaps:
        return "לפני שאצא לסריקה חסר עוד פרט אחד בבקשת הטיסה. נשלים אותו ואז אציג שוב סיכום לאישור."
    return None


def _reset_intent(message):
    """Detect possible restart/change-of-direction language without deleting state.

    Per product owner: a bare "מהתחלה" ("from the beginning") is not on its
    own a reset signal - seen live, "תשלחי את כל המסלול מהתחלה עם זמני
    נסיעות" (send the whole ROUTE from its beginning/day 1) wrongly asked
    "delete everything and start a new vacation?" when the customer just
    wanted to see the existing itinerary again in full. Only phrases that
    pair "מהתחלה" with an explicit start/restart verb ("להתחיל"/"נתחיל")
    are specific enough to mean restarting the vacation itself."""
    msg = str(message or "").strip().lower()
    phrases = ("חופשה חדשה","טיול חדש","חיפוש חדש","להתחיל מחדש","נתחיל מחדש","להתחיל מהתחלה","נתחיל מהתחלה","לשנות כיוון")
    return any(p in msg for p in phrases)

def _full_reset_confirmation(message):
    """Only explicit confirmation after the clarification may clear trip state."""
    msg = str(message or "").strip().lower()
    phrases = ("למחוק הכל","למחוק הכול","תמחקי הכל","תמחקי הכול","להתחיל לגמרי מהתחלה","מהתחלה לגמרי","כן למחוק","כן, למחוק")
    return any(p in msg for p in phrases)


def _normalize_confirm(message):
    """Strip trailing punctuation ("מעולה!", "מצוין..") before matching a
    short confirmation against an exact-phrase set, so an ordinary exclamation
    mark doesn't make an unambiguous "yes" invisible to a deterministic gate."""
    return str(message or "").strip().rstrip("!.,?;:״\"'׳ ").strip()

def _user_gender_from_approval(message, state):
    msg = str(message or "").strip().lower()
    if msg == "מאשרת":
        return "female"
    if msg == "מאשר":
        return "male"
    return (state or {}).get("user_gender")


def _approval_trigger(message, history, state):
    """Exact approval executes after the flight summary was visibly presented.
    Do not depend on a stale ready_for_summary flag from the previous HTTP turn.
    """
    msg = str(message or "").strip().lower()
    if msg not in {"מאשר", "מאשרת"}:
        return False
    state = state if isinstance(state, dict) else {}
    # Once the flights were approved and are being scanned, "מאשרת" can only
    # be about a later service (car/lodging/route) - seen live: a car
    # summary ending in "כתבי מאשרת" was taken as a new flight approval, so
    # a flight search was started again and the car was asked about from
    # scratch. Only a flights session the customer reopened to change it may
    # be approved again.
    if state.get("post_flight_continuation") and state.get("active_session") != "flights":
        return False
    if state.get("ready_for_summary"):
        return True
    # The visible assistant summary is authoritative evidence that we reached
    # the approval gate; this survives state normalization between turns.
    recent = [x for x in (history or []) if isinstance(x, dict)][-4:]
    assistant_text = " ".join(
        str(x.get("content") or "") for x in recent
        if str(x.get("role") or "").lower() == "assistant"
    )
    return ("כתבי מאשרת" in assistant_text
            or "כתוב מאשר" in assistant_text
            or "מאשר/מאשרת" in assistant_text)

def _looks_like_approval_typo(message, state=None, history=None):
    """Near-approval text may be clarified, but can never execute a search."""
    import difflib
    msg = str(message or "").strip().lower()
    if not msg or msg in {"מאשר", "מאשרת"}:
        return False
    state = state if isinstance(state, dict) else {}
    # Only interpret a near-match as an approval typo when the conversation is
    # actually at the final summary/approval stage. ready_for_summary alone
    # can be stale between HTTP turns (the same issue _approval_trigger's own
    # docstring warns about) - seen live: a customer typed "אשרת" (missing the
    # leading מ) right after the real summary/"כתבי מאשרת" prompt, but the
    # flag had already gone stale, so this bailed out here instead of asking
    # "did you mean to approve?", and the turn fell through to a free-text
    # reply that falsely claimed a search had started. Fall back to the same
    # recent-assistant-text check _approval_trigger already uses.
    at_approval_gate = bool(state.get("ready_for_summary"))
    if not at_approval_gate:
        recent = [x for x in (history or []) if isinstance(x, dict)][-4:]
        assistant_text = " ".join(
            str(x.get("content") or "") for x in recent
            if str(x.get("role") or "").lower() == "assistant"
        )
        at_approval_gate = (
            "כתבי מאשרת" in assistant_text
            or "כתוב מאשר" in assistant_text
            or "מאשר/מאשרת" in assistant_text
        )
    if not at_approval_gate:
        return False
    compact = "".join(ch for ch in msg if ch.isalpha())
    if not compact or len(compact) > 8:
        return False
    return max(difflib.SequenceMatcher(None, compact, target).ratio()
               for target in ("מאשר", "מאשרת")) >= 0.72


def _interpret_pending_choice(key, model, history, message, question_kind):
    """Interpret free-form customer answers to a pending conversational choice."""
    if not key:
        return "unclear"
    prompt = """את מסווגת כוונת לקוח מתוך הקשר השיחה. הלקוח רשאי לענות בכל ניסוח טבעי וגם עם שגיאות כתיב.
החזירי מילה אחת בלבד.
כאשר question_kind=new_vacation:
NEW = הלקוח רוצה להתחיל חופשה חדשה ולוותר על פרטי החופשה הקודמת.
KEEP = הלקוח רוצה להישאר בחופשה הקיימת או רק לשנות בה פרט.
UNCLEAR = אי אפשר להבין בבטחה.
הביני משמעות והקשר; אל תדרשי מילת קסם ואל תסתמכי על התאמת מחרוזת."""
    try:
        raw = _post_claude(
            key, model, prompt, "", history if isinstance(history, list) else [],
            "question_kind=" + str(question_kind) + "\nתשובת הלקוח: " + str(message or ""),
            20, include_history=True, source="classifier"
        ).strip().upper()
        if raw.startswith("NEW"):
            return "new"
        if raw.startswith("KEEP"):
            return "keep"
    except Exception:
        pass
    return "unclear"


def _fix_known_typos(text):
    """Deterministic safety net for a recurring model typo: dropping the
    leading נ from the נתב"ג (Ben Gurion airport) acronym, or reversing its
    two middle letters. Same philosophy as the deterministic fact-extraction
    helpers elsewhere in this file - do not trust free-form model text for
    something that has exactly one correct spelling."""
    import re
    text = str(text or "")
    text = re.sub(r'(?<!נ)תב["״]ג', 'נתב"ג', text)
    text = re.sub(r'(?<!נ)בת["״]ג', 'נתב"ג', text)
    return text


def _strip_garbled_lead_token(text):
    """Deterministic safety net for a recurring model glitch, seen live on
    the phone more than once: an occasional garbled token that mixes Hebrew
    and Latin letters within the same run of characters (e.g. "סדחFOSX")
    injected as the very first word of an otherwise normal Hebrew reply. A
    legitimate word never mixes scripts letter-by-letter like that - real
    English terms inside a Hebrew reply always appear as their own separate,
    single-script word (an airport code in parentheses, "COVID", etc.), so
    any leading token containing both scripts together is never real content
    and can be dropped outright, along with the stray comma/dash left after
    it."""
    import re
    text = str(text or "")
    m = re.match(r'^\S*[֐-׿]\S*[A-Za-z]\S*|^\S*[A-Za-z]\S*[֐-׿]\S*', text)
    if m and m.group(0):
        rest = text[m.end():].lstrip()
        rest = re.sub(r'^[,:\-–]\s*', '', rest)
        if rest:
            return rest
    return text


_FOREIGN_TO_HEBREW = {
    # Cyrillic
    "а": "א", "б": "ב", "в": "ו", "г": "ג", "д": "ד", "е": "", "ё": "יו",
    "ж": "ז'", "з": "ז", "и": "י", "й": "י", "і": "י", "к": "ק", "л": "ל",
    "м": "מ", "н": "נ", "о": "ו", "п": "פ", "р": "ר", "с": "ס", "т": "ט",
    "у": "ו", "ф": "פ", "х": "ח", "ц": "צ", "ч": "צ'", "ш": "ש", "щ": "ש",
    "ъ": "", "ы": "י", "ь": "", "э": "", "ю": "יו", "я": "יה", "ј": "י",
    # Greek
    "α": "א", "β": "ב", "γ": "ג", "δ": "ד", "ε": "", "ζ": "ז", "η": "י",
    "θ": "ת", "ι": "י", "κ": "ק", "λ": "ל", "μ": "מ", "ν": "נ", "ξ": "קס",
    "ο": "ו", "π": "פ", "ρ": "ר", "σ": "ס", "ς": "ס", "τ": "ט", "υ": "י",
    "φ": "פ", "χ": "ח", "ψ": "פס", "ω": "ו",
}

# Canonical Hebrew spellings for names the transliteration above lands close
# to but not exactly on (Slavic names are where this glitch keeps striking).
_CANONICAL_PLACE_SPELLINGS = (
    (r"פליט[ובי]+צ[הא]?", "פליטביצה"),
)


def _repair_foreign_letters_in_hebrew(text):
    """Deterministic safety net, seen live more than once on Slavic place
    names: a Hebrew word with some letters swapped for Cyrillic ones mid-word
    ("פליטвицה" for פליטביצה). _strip_mixed_script_garble ignores Hebrew, so
    this slipped through. Cyrillic/Greek never belong in a Hebrew reply, so
    instead of dropping the word (which would leave a hole mid-sentence),
    transliterate those letters back to Hebrew and snap known names to their
    canonical spelling. Tokens that also contain Latin are left for
    _strip_mixed_script_garble to drop, as before."""
    import re
    text = str(text or "")
    if not re.search(r"[\u0370-\u03ff\u0400-\u04ff]", text) or not re.search(r"[\u05d0-\u05ea]", text):
        return text

    def _fix(m):
        tok = m.group(0)
        if not re.search(r"[\u0370-\u03ff\u0400-\u04ff]", tok) or re.search(r"[A-Za-z]", tok):
            return tok
        out = "".join(_FOREIGN_TO_HEBREW.get(ch.lower(), ch) if "\u0370" <= ch <= "\u04ff" else ch for ch in tok)
        for pattern, canonical in _CANONICAL_PLACE_SPELLINGS:
            out = re.sub(pattern, canonical, out)
        return out

    return re.sub(r"\S+", _fix, text)


def _strip_mixed_script_garble(text):
    """Deterministic safety net for a related model glitch, seen live: a
    place name mid-sentence rendered with letters from multiple unrelated
    scripts mixed together (e.g. "пlutвицα" instead of "Plitvice" - Cyrillic
    п/в/и/ц and Greek α standing in for some of the Latin letters, not a
    consistent transliteration so it can't be reconstructed reliably).
    _strip_garbled_lead_token only catches this at the very start of a
    reply and only for a Hebrew+Latin mix; this catches it anywhere in the
    text and for any 2+ of Latin/Cyrillic/Greek in the same token. A real
    word is written in one script (Hebrew text, or a Latin term/airport
    code as its own single-script token) - it never mixes Latin, Cyrillic
    and Greek letters together, so any token that does is never real
    content and is dropped, same philosophy as the lead-token case."""
    import re
    text = str(text or "")

    def _check(m):
        tok = m.group(0)
        core = re.sub(r"\W", "", tok, flags=re.UNICODE)
        has_latin = bool(re.search(r"[A-Za-z]", core))
        has_cyrillic = bool(re.search(r"[Ѐ-ӿ]", core))
        has_greek = bool(re.search(r"[Ͱ-Ͽ]", core))
        if sum((has_latin, has_cyrillic, has_greek)) >= 2:
            return ""
        return tok

    cleaned = re.sub(r"\S+", _check, text)
    if cleaned == text:
        return text
    cleaned = re.sub(r"[ \t]{2,}", " ", cleaned)
    cleaned = re.sub(r"[ \t]+([.,:;!?])", r"\1", cleaned)
    cleaned = re.sub(r"(?m)^[ \t]+", "", cleaned)
    return cleaned.strip()


def _strip_leaked_internal_paragraph(text):
    """Deterministic safety net for a recurring model glitch, seen live:
    an occasional stray technical/self-talk sentence ("פורמט תאריך לא ידוע.
    אנא נסה תבנית אחרת.") injected as the reply's own leading paragraph,
    completely unrelated to what the customer actually asked, immediately
    followed by the real, warm customer-facing reply as a second paragraph.
    The prompt already says Ariella must never surface system/technical
    wording ("noted", "saved" etc.) - this is the same failure in spirit,
    just a full sentence instead of one English word, so it needs the same
    kind of deterministic net rather than trusting the instruction alone.
    Only strips when there is a clear paragraph break AND the leading
    paragraph contains an unambiguous technical/meta marker, so an ordinary
    short opening line is never touched."""
    import re
    parts = re.split(r'\n\s*\n', str(text or ""), maxsplit=1)
    if len(parts) != 2:
        return text
    lead, rest = parts[0].strip(), parts[1].strip()
    if not lead or len(rest) < 10:
        return text
    meta_markers = ("פורמט", "תבנית", "שגיאה", "error", "exception")
    if not any(m in lead for m in meta_markers):
        return text
    return rest


_ITINERARY_WEEKDAY_RE = re.compile(
    r"יום\s+(?:\d{1,2}\s*)?\(?(?:ראשון|שני|שלישי|רביעי|חמישי|שישי|שבת)\)?"
)
_ITINERARY_NUMBERED_DAY_RE = re.compile(r"(?<![א-ת])יום\s+(\d{1,2})(?!\d)")
_ITINERARY_DATE_BEFORE_WEEKDAY_RE = re.compile(r"\d{1,2}\.\d{1,2}\.\d{2,4}\s*\(?$")
# Matches the day-count Tinkerbell states in its one-sentence opener before a
# day-by-day itinerary ("הנה הצעה ל-4 הימים", "מסלול 5 ימים", "4 ימי טיול").
_ITINERARY_INTRO_COUNT_RE = re.compile(r"(\d{1,2})(?:[\s-]*ה?ימים\b|[\s-]*ימי\s)")


def _itinerary_body_day_count_and_start(text):
    """Count the real day-by-day entries an itinerary reply actually
    presents, and where the first one starts - same detection logic used
    elsewhere in this file to recognize itinerary shape (2+ weekday
    mentions, or 2+ distinct numbered "יום N" mentions, whichever style is
    actually used), reused here so the day count checked against is the
    same one a human reading the message would count."""
    text = str(text or "")
    weekday_positions = []
    for m in _ITINERARY_WEEKDAY_RE.finditer(text):
        prefix = text[max(0, m.start() - 20):m.start()]
        if _ITINERARY_DATE_BEFORE_WEEKDAY_RE.search(prefix):
            continue
        weekday_positions.append(m.start())
    numbered = {}
    for m in _ITINERARY_NUMBERED_DAY_RE.finditer(text):
        numbered.setdefault(m.group(1), m.start())
    if len(numbered) > len(weekday_positions):
        return len(numbered), min(numbered.values())
    if weekday_positions:
        return len(weekday_positions), weekday_positions[0]
    return 0, None


def _fix_itinerary_intro_day_count(reply):
    """Tinkerbell's one-sentence opener before a day-by-day itinerary
    sometimes states a day count that contradicts the itinerary it then
    actually presents. Seen live: "הנה הצעה ל-4 הימים" followed by a full
    five-day plan (יום ראשון...יום חמישי) for dates that were genuinely a
    5-day/4-night trip (27.6-1.7). The itinerary body itself was built
    correctly from the approved dates - only the single number in the
    opening sentence was wrong (most likely the model silently/incorrectly
    restating "4 nights" as "4 days" instead of 5). Rather than trust the
    model's own arithmetic in free text, fix that one number to match the
    itinerary actually presented - the real, visible proof of how many
    days this is - same deterministic-safety-net philosophy as the other
    helpers in this file (never trust free text for a fact with exactly
    one correct, checkable answer)."""
    text = str(reply or "")
    count, start = _itinerary_body_day_count_and_start(text)
    if count < 2 or start is None:
        return reply
    intro = text[:start]
    match = _ITINERARY_INTRO_COUNT_RE.search(intro)
    if not match or int(match.group(1)) == count:
        return reply
    fixed_intro = intro[:match.start(1)] + str(count) + intro[match.end(1):]
    return fixed_intro + text[start:]


def _fix_child_gender_wording(text, state):
    """Deterministic safety net, same philosophy as the two helpers above: a
    prompt instruction alone did not reliably stop the model from inventing a
    child's gender when it writes them into a summary - seen live, a customer-
    stated "ילדה בת 17" turned into "ונער בן 17" in Tinkerbell's own generated
    trip summary. travelers.child_genders (set deterministically in
    _deterministic_traveler_facts from the customer's own "ילדה בת"/"ילד בן"
    wording) is the one place this fact is actually recorded, so correct any
    mismatch against it after the fact rather than trust free text to get it
    right."""
    state = state if isinstance(state, dict) else {}
    travelers = state.get("travelers") if isinstance(state.get("travelers"), dict) else {}
    ages = travelers.get("child_ages") if isinstance(travelers.get("child_ages"), list) else []
    genders = travelers.get("child_genders") if isinstance(travelers.get("child_genders"), list) else []
    if not ages or not genders:
        return text
    import re
    text = str(text or "")
    to_fem = {"ילד": "ילדה", "נער": "נערה"}
    to_masc = {"ילדה": "ילד", "נערה": "נער"}
    for age, gender in zip(ages, genders):
        if gender not in ("male", "female"):
            continue
        try:
            age_int = int(age)
        except (TypeError, ValueError):
            continue
        pattern = re.compile(r"(ילד|ילדה|נער|נערה)(\s+)(בן|בת)(\s*%d\b)" % age_int)

        def _fix(m, wants_fem=(gender == "female")):
            noun, sep, particle, tail = m.group(1), m.group(2), m.group(3), m.group(4)
            if noun.endswith("ה") == wants_fem:
                return m.group(0)
            noun = (to_fem if wants_fem else to_masc).get(noun, noun)
            particle = "בת" if wants_fem else "בן"
            return noun + sep + particle + tail

        text = pattern.sub(_fix, text)
    return text


def _strip_unconfirmed_airports(text, state):
    """Deterministic safety net for a recurring model behavior: even after an
    explicit prompt instruction not to, Tinkerbell keeps volunteering an
    unverified alternate gateway airport from its own general world
    knowledge - nothing in destination_airports/return_departure_airports
    ever actually named it. The prompt fix alone did not reliably hold, so
    strip it here regardless of what the model produced.

    First seen with LaGuardia (LGA) volunteered next to JFK for New York;
    later, with a destination_airports choice already settled on Paphos
    (PFO), it brought up Larnaca (LCA) again mid itinerary-planning,
    unprompted, to second-guess an already-closed decision. Rather than
    hardcode each city as it comes up, this checks every known airport in
    config.AIRPORT_NAMES that ISN'T one of the confirmed/verified codes for
    this trip and strips any paragraph that names it - genuinely unconfirmed
    detail is never worth partially keeping.

    Two different shapes need different handling: a brief inline mention
    ("JFK או לגה") and a full elaborated paragraph built on the invented
    airport (explaining it exists, asking which one/both, weighing it
    against the confirmed choice) - deleting a few words out of the second
    leaves an incoherent sentence behind, but deleting an entire paragraph
    for the first would delete real content too."""
    import re
    from config import AIRPORT_NAMES
    state = state if isinstance(state, dict) else {}
    confirmed = set()
    for key in ("destination_airports", "return_departure_airports"):
        for a in (state.get(key) if isinstance(state.get(key), list) else []):
            confirmed.add(str(a or "").strip().upper())
    dep = str(state.get("departure_airport") or "").strip().upper()
    if dep:
        confirmed.add(dep)
    # A verified multi-gateway destination (config.MULTI_GATEWAY_CITIES,
    # surfaced via _multi_gateway_hint) legitimately offers more than one
    # real airport - Tinkerbell is meant to ask about those, using the exact
    # verified list it was handed, so they are not "unconfirmed" here.
    gateway_hint = _multi_gateway_hint(state)
    if gateway_hint:
        for o in gateway_hint.get("options", []):
            confirmed.add(str(o.get("code") or "").strip().upper())
    # Nothing confirmed yet (still choosing a gateway) - a mentioned airport
    # isn't "unconfirmed" in that case, it's the normal selection process.
    if not (state.get("destination_airports") or state.get("return_departure_airports")):
        return text

    text = str(text or "")
    if not text.strip():
        return text
    # Deliberately match only "CityName (CODE)" - the exact shape Ariella
    # always uses when actually discussing something as a flight gateway
    # (matching the live transcripts this was found in) - not a bare city
    # name alone, which would false-positive on a common capital mentioned
    # for an unrelated scenic/cultural reason (e.g. "מרגיש כמו רובע ברומא").
    unconfirmed_hits = []
    for code, name in AIRPORT_NAMES.items():
        code_u = str(code or "").strip().upper()
        name_s = str(name or "").strip()
        if not code_u or code_u in confirmed or not name_s:
            continue
        pattern = re.compile(re.escape(name_s) + r'\s*\(\s*' + re.escape(code_u) + r'\s*\)')
        if pattern.search(text):
            unconfirmed_hits.append(pattern)
    if not unconfirmed_hits:
        return text
    forbidden = re.compile('|'.join(p.pattern for p in unconfirmed_hits))
    # Paragraph-level removal first (Tinkerbell's own structure is one topic
    # per blank-line-separated paragraph): drop any paragraph that mentions
    # an unconfirmed airport at all, as long as other paragraphs remain to
    # keep the reply from going empty.
    paragraphs = re.split(r'(\n\s*\n)', text)
    blocks = paragraphs[0::2]
    separators = paragraphs[1::2]
    kept_blocks, kept_seps = [], []
    for i, block in enumerate(blocks):
        if not forbidden.search(block):
            kept_blocks.append(block)
            if i < len(separators):
                kept_seps.append(separators[i])
    if kept_blocks and len(kept_blocks) < len(blocks):
        result = kept_blocks[0]
        for sep, block in zip(kept_seps, kept_blocks[1:]):
            result += sep + block
        return result.strip()
    # Single-paragraph (or every paragraph tainted) case: surgical phrase
    # removal instead, including a Hebrew ו/או prefix glued directly onto the
    # city name and parenthesized codes, followed by a cleanup pass for the
    # connector/punctuation debris left behind (a dangling "ו"/"או", empty
    # "()", doubled spaces or commas).
    for pattern in unconfirmed_hits:
        text = re.sub(r'\s*[/,]?\s*(?:ו|או)?\s*(?:' + pattern.pattern + r')', '', text)
    text = re.sub(r'\(\s*\)', '', text)
    text = re.sub(r'(?:^|\s)(?:ו|או)(?=[\s.,?!]|$)', '', text)
    text = re.sub(r'[ \t]{2,}', ' ', text)
    text = re.sub(r'\s+([.,?!])', r'\1', text)
    return text.strip()


def _travelers_summary(state):
    """The party size spelled out with its total already computed. Seen
    live: "אתם ארבעה (שני מבוגרים ובת נוער)" - the model added 2+1 and got
    4. The total is arithmetic, so it's computed here and handed to the
    model as a fact instead of left for it to work out."""
    travelers = state.get("travelers") if isinstance(state.get("travelers"), dict) else {}

    def _num(v):
        try:
            return max(0, int(v or 0))
        except (TypeError, ValueError):
            return 0

    adults, children, infants = _num(travelers.get("adults")), _num(travelers.get("children")), _num(travelers.get("infants"))
    total = adults + children + infants
    if not total:
        return ""
    ages = travelers.get("child_ages") if isinstance(travelers.get("child_ages"), list) else []
    genders = travelers.get("child_genders") if isinstance(travelers.get("child_genders"), list) else []
    parts = [f"{adults} מבוגרים"] if adults else []
    if children:
        kids = []
        for i, age in enumerate(ages[:children]):
            g = genders[i] if i < len(genders) else None
            kids.append(f"{'בת' if g == 'female' else 'בן' if g == 'male' else 'ילד/ה'} {age}")
        parts.append(f"{children} ילדים" + (f" ({', '.join(kids)})" if kids else ""))
    if infants:
        parts.append(f"{infants} תינוקות")
    return (
        f"\nהרכב הנוסעים (מחושב, מקור אמת): סה\"כ {total} נוסעים - " + ", ".join(parts) + ". "
        f"כשאת מציינת את מספר הנוסעים השתמשי בדיוק במספר {total}; לעולם אל תחשבי סכום בעצמך."
    )


_BAGGAGE_HE = {
    "carry_on_only": "טרולי בלבד", "carry_on": "טרולי", "checked_bag": "מזוודה גדולה",
    "checked": "מזוודה גדולה", "personal_item": "תיק אישי בלבד",
    "none": "ללא כבודה", "no_baggage": "ללא כבודה",
}


def _baggage_summary(state):
    """The luggage already collected for the flight, for the car session.
    Seen live: after the flight baggage was settled, the car session asked
    the customer again whether they're taking big suitcases."""
    flight = state.get("flight") if isinstance(state.get("flight"), dict) else {}
    baggage = flight.get("baggage") if isinstance(flight.get("baggage"), list) else []
    labels = [_BAGGAGE_HE.get(str(b), str(b)) for b in baggage if b]
    if not labels:
        return ""
    return (
        "\nכבודה (כבר נאספה בטיסה, מקור אמת): " + ", ".join(dict.fromkeys(labels)) + ". "
        "בהתאמת הרכב השתמשי בזה ואל תשאלי את הלקוח שוב על מזוודות."
    )


def _departure_summary(state):
    """The departure airport's exact Hebrew name. Seen live: the customer
    wrote "נתבג", TLV was saved correctly, and the reply still said
    "אז נתניה ל-JFK". The name is handed over as a fact."""
    code = str(state.get("departure_airport") or "").upper()
    if not code:
        options = state.get("departure_options") or []
        if not options:
            return ""
        names = ", ".join(f"{AIRPORT_NAMES.get(c, c)} ({c})" for c in options)
        return (
            f"\nשדה היציאה עוד לא נקבע. לפי פרטי ההרשמה של הלקוח, האפשרויות הסבירות: {names}. "
            "כשמגיע הזמן לשאול על שדה היציאה, הציעי אותן בשאלה קצרה אחת (הלקוח יכול לבחור גם שדה אחר בכל מקום בעולם). אל תניחי שהלקוח טס מישראל."
        )
    name = AIRPORT_NAMES.get(code, code)
    line = f"\nשדה היציאה (מקור אמת): {name} ({code}). כשאת מזכירה אותו, כתבי בדיוק \"{name}\"."
    if state.get("departure_airport_source") == "profile":
        line += " הוא נלקח מהשדה שהלקוח בחר בפרטי ההרשמה - אל תשאלי עליו; ציייני אותו בסיכום הטיסה כדי שהלקוח יוכל לשנות אם צריך."
    return line


def _fix_departure_name(reply, state, history, message):
    """Backstop for the same slip: Netanya has no airport, so in a reply
    about a TLV departure it can only be a garbled נתב"ג - unless the
    customer actually talked about Netanya."""
    if str(state.get("departure_airport") or "").upper() != "TLV" or "נתניה" not in reply:
        return reply
    user_text = " ".join(
        [str(x.get("content") or "") for x in (history or []) if isinstance(x, dict) and x.get("role") == "user"]
        + [str(message or "")]
    )
    return reply if "נתניה" in user_text else reply.replace("נתניה", 'נתב"ג')


def _call_tinkerbell(key, model, history, message, state=None):
    state = state if isinstance(state, dict) else {}
    statuses = state.get("session_status") if isinstance(state.get("session_status"), dict) else {}
    active_session = state.get("active_session")
    trip_planning_settled = statuses.get("trip_planning") in ("complete", "declined")
    other_session_pending = active_session and active_session != "trip_planning"
    if not other_session_pending:
        other_session_pending = any(
            statuses.get(s) not in ("complete", "declined")
            for s in ("flights", "lodging", "car")
        )

    if trip_planning_settled and other_session_pending:
        route_handoff = """
- הלקוח זה עתה אישר את המסלול/האטרקציות המוצעים, אבל יש עוד תחום/ים בחופשה (טיסות/לינה/רכב) שטרם טופלו. אל תסיימי את השיחה, אל תאמרי "מאחלת חופשה נעימה" ואל תבטיחי שליחת מידע לכרטיסייה עדיין.
- אם המסלול קבע שדה/שדות כניסה ליעד, הם כבר נשמרו ב-destination_airports; אל תשאלי עליהם שוב, רק אשרי אותם בקצרה במידת הצורך. המשיכי כעת ישירות לתחום הפתוח: אם active_session מוגדר, השלימי את missing_required שלו; אם אין active_session, זהו סשן pending הבא ושאלי עליו שאלה בינארית טבעית כרגיל.
- ברגע שהתחום הפתוח הזה מלא, נהגי לפי כללי הסיכום הרגילים שלו (למשל עבור טיסות: סיכום קצר ובקשת מאשר/מאשרת), ולא לפי נוסח הסיום של תכנון המסלול.
"""
    else:
        route_handoff = """
- כאשר הצעת מסלול/אטרקציות והלקוח מאשר אותו במפורש או אומר שהוא מתאים, ואין עוד סשן פתוח שממתין להשלמה (כלומר טיסות/לינה/רכב כבר complete או declined), אל תשאלי אם לאשר שוב ואל תציעי לעבור ללינה. סיימי בדיוק בנוסח: "מצוין. אני אשלח לך את כל האינפורמציה לכרטיסיית האטרקציות בכרטיס החופשה שלך. מאחלת לך חופשה נעימה ולכל שאלה נוספת אני תמיד כאן."
"""
    continuity = """
כללי שיחה מחייבים לאחר סריקת הטיסות:
- אם קיימת חופשה פעילה והלקוח ממשיך לדבר עליה, זו אותה חופשה כברירת מחדל. אל תשאלי שוב "אותה חופשה או חופשה חדשה" אלא אם הלקוח עצמו מבקש חופשה חדשה או שיש סתירה אמיתית.
- אם active_session הוא trip_planning, הישארי בתכנון המסלול. אל תעברי מיוזמתך ללינה, רכב או טיסות ואל תשאלי שאלות על תחום אחר.
- כשהחופשה הפעילה היא עסקים או סקי ואת שואלת אם הלקוח מתכוון לחופשה חדשה לגמרי או להמשיך את זו הקיימת, לעולם אל תציעי "להוסיף גם תכנון מסלול" כאפשרות להמשך אותה חופשה - זה לא רלוונטי לעסקים/סקי (ראי כלל למעלה) גם בתוך שאלת ההבהרה הזו. הצעת ההמשך היחידה הרלוונטית שם היא לינה או רכב.
- דברי כשיחה טבעית ולא כטופס. השתמשי בפרטים שכבר ידועים, הגיבי למה שהלקוח אמר ורק אז שאלי את השאלה הבאה הנחוצה.
""" + route_handoff
    upcoming = state.get("upcoming_vacations") if isinstance(state.get("upcoming_vacations"), list) else []
    has_destination = bool((state.get("destination") or {}).get("places")) if isinstance(state.get("destination"), dict) else False
    if upcoming:
        listed = "; ".join(
            f"{v.get('name')} ({v.get('window')}"
            + (f", {v.get('travelers')}" if v.get("travelers") else "") + ")"
            + (f" - עוד אפשר להוסיף: {', '.join(v.get('missing') or [])}" if v.get("missing") else "")
            for v in upcoming
        )
        continuity += (
            "\n- החופשות הפעילות השמורות של הלקוח (מקור אמת): " + listed + ". "
            "כשהלקוח מדבר על אחד מהיעדים האלה, או מבקש שתבדקי בחופשות שלו, הסתמכי על הנתונים האלה - "
            "לעולם אל תשאלי שוב על תאריכים, משך או נוסעים שכבר מופיעים כאן."
        )
        if not has_destination:
            continuity += (
                " אם ההודעה היא פתיחה כללית (ברכה, 'היי', שאלה כללית) ולא בקשה ברורה לחופשה חדשה, אל תתחילי חופשה חדשה ואל תשאלי על סוג נסיעה: "
                "הציעי בקצרה להמשיך עם החופשה הקרובה ולהוסיף לה את מה שחסר, או לתכנן חופשה חדשה. אם הוא מבקש חופשה חדשה או יעד אחר - המשיכי כרגיל."
            )
    decisions = state.get("service_decisions") if isinstance(state.get("service_decisions"), dict) else {}
    not_asked = [
        {"lodging": "לינה", "car": "רכב", "trip_planning": "מסלול"}[s]
        for s in ("lodging", "car", "trip_planning")
        if isinstance(decisions.get(s), dict) and decisions[s].get("source") == "reopened_trip_not_requested"
    ]
    if not_asked:
        # Closed only because this return visit was for another service -
        # not done and not refused. Seen live: "זה משלים את כל התחומים"
        # while lodging was never handled.
        continuity += (
            "\n- בביקור הזה הלקוח חזר רק בשביל תחום מסוים. התחומים האלה לא טופלו ולא נדחו על ידי הלקוח: "
            + ", ".join(not_asked)
            + ". לעולם אל תאמרי שכל התחומים הושלמו. בסיום, ציייני במשפט אחד מה נוסף עכשיו, ושאפשר להוסיף גם "
            + ", ".join(not_asked) + " בכל רגע."
        )
    if state.get("post_flight_continuation"):
        # The flights were already summarized and approved; repeating the
        # whole vacation summary after each later service (seen live after
        # the car questions) is noise. Only the newly settled part matters.
        continuity += """
- כל מה שהלקוח כבר אישר (טיסות, מסלול, לינה, רכב) נשאר מאושר. אל תציגי אותו שוב לאישור ואל תבקשי לאשר אותו מחדש - אלא אם הלקוח עצמו שינה בו משהו, ואז הציגי לאישור רק את מה שהשתנה.
- הטיסות כבר אושרו ויצאו לסריקה, והסיכום המלא כבר הוצג ללקוח. כשמסתיים עכשיו תחום נוסף (לינה/רכב/מסלול), סכמי בקצרה רק את הפרטים של התחום הזה שהושלם - בלי לחזור על הטיסות, הנוסעים, התאריכים או תחומים אחרים, ובלי לבקש שוב מאשר/מאשרת. אם נשאר תחום פתוח, עברי אליו; אחרת סיימי בקצרה.
- גם כאן, אם יותר מתחום אחד (למשל גם לינה וגם רכב) עדיין pending בו-זמנית, שאלי על אחד בלבד בכל הודעה - לעולם לא "לינה או רכב?" כשאלה אחת. לקוח שעונה "לא" לשאלה כזו - ברור בדיוק לאיזה תחום זה מתייחס, לא לשניים.
"""
    gateway_hint = _multi_gateway_hint(state)
    gateway_hint_text = ""
    if gateway_hint:
        options_text = ", ".join(f"{o['name_he']} ({o['code']})" for o in gateway_hint["options"])
        gateway_hint_text = (
            f'\nהיעד "{gateway_hint["city"]}" מתאים ליותר משדה תעופה אמיתי אחד: {options_text}. '
            'אלה שדות מאומתים - אל תוסיפי או תמציאי שדה אחר משלך. אם destination_airports עדיין ריק, '
            'שאלי את הלקוח בשאלה אחת האם לחפש בכולם יחד, רק בשדה מסוים, או בכמה מהם - והשתמשי אך ורק ברשימה הזו.'
        )
    system_dynamic = continuity + '\nהתאריך הנוכחי: ' + date.today().isoformat() + '\nמצב החופשה המצטבר שכבר ידוע:\n' + _state_context(state) + gateway_hint_text + _travelers_summary(state) + _baggage_summary(state) + _departure_summary(state)
    reply = _post_claude(key, model, TINKERBELL_SYSTEM, system_dynamic, history, message, 1500, include_history=True, source="tinkerbell_reply").strip()
    reply = _fix_known_typos(reply)
    reply = _fix_departure_name(reply, state, history, message)
    reply = _strip_garbled_lead_token(reply)
    reply = _repair_foreign_letters_in_hebrew(reply)
    reply = _strip_mixed_script_garble(reply)
    reply = _strip_leaked_internal_paragraph(reply)
    return _strip_unconfirmed_airports(reply, state)


def _extract_trip_update(key, model, history, message, state=None):
    try:
        gateway_hint = _multi_gateway_hint(state)
        gateway_hint_text = ""
        if gateway_hint:
            options_text = ", ".join(f"{o['name_he']} ({o['code']})" for o in gateway_hint["options"])
            gateway_hint_text = (
                f'\nאם הלקוח כרגע עונה לגבי בחירת שדה תעופה עבור "{gateway_hint["city"]}", השדות האמיתיים היחידים '
                f'הם: {options_text}. כתבי ב-destination_airports אך ורק קודי IATA מהרשימה הזו לפי מה שהלקוח בחר '
                '(אחד, כמה, או כולם) - לעולם לא קוד אחר.'
            )
        system_dynamic = '\nמצב החופשה המצטבר לפני ההודעה הנוכחית:\n' + _state_context(state) + '\nהתאריך הנוכחי: ' + date.today().isoformat() + gateway_hint_text
        # Used to pass only the last 4 messages ("preserve semantics without
        # paying the latency of the entire conversation"), while the system
        # prompt itself claims "קבלי את כל השיחה" - the two didn't match.
        # Seen live, repeatedly: a fact stated once (a location preference,
        # a baggage answer bundled into a longer reply) that the extractor
        # happened to miss on its own turn became permanently unrecoverable
        # the moment the conversation moved more than ~2 exchanges past it -
        # not because Tinkerbell's own reply ever forgot it (that call
        # already gets the full history and kept referencing it correctly
        # throughout), but because the extractor's structured-state call
        # literally no longer had the message in its input at all. No
        # per-phrasing patch can fix a fact that has scrolled out of view.
        # Matches the main conversational call's own history exactly now -
        # same conversation, same memory.
        raw = _post_claude(key, model, EXTRACTOR_SYSTEM, system_dynamic, history, message, 700, include_history=True, source="state_extractor")
        return _parse_trip_update(raw)
    except Exception:
        return {}


_KNOWN_DESTINATION_NAMES_CACHE = None

# Common alternate Hebrew spellings/transliterations for a destination
# already in the airport catalog under a different spelling. Colloquial
# Hebrew often has more than one accepted transliteration for a foreign
# name - seen live: the catalog has Vietnam as "וייטנאם" (from
# static/airports.json), but a customer typing the equally common
# "ויאטנם" got treated as an unrecognized destination entirely (no
# substring match either way), silently dropping the destination she
# had just named. Add more pairs here as they're found live - this is
# a spelling-variant map, not a full destination list, so it stays small.
_DESTINATION_SPELLING_ALIASES = {
    "ויאטנם": "וייטנאם",
}


def _known_destination_names():
    """needle -> display label for every country/city in the real airport
    catalog (travel_agents._load_airports), built once and cached.

    This used to be an 8-country hardcoded dict (Montenegro, Greece, Italy,
    Bulgaria, Albania, Malta, Croatia, Thailand only) - seen live: a
    customer opened a brand-new vacation with "חופשה חדשה לקפריסין" and got
    the generic "לאן תרצי לטוס?" because Cyprus simply wasn't in that list,
    even though Cyprus is one of the most commonly requested destinations
    and has been in the scanned-destinations catalog the whole time. Deriving
    this from the actual airport catalog instead means every real,
    supported destination is recognized automatically, with no separate
    list to remember to keep in sync."""
    global _KNOWN_DESTINATION_NAMES_CACHE
    if _KNOWN_DESTINATION_NAMES_CACHE is not None:
        return _KNOWN_DESTINATION_NAMES_CACHE
    known = {}
    for airport in _load_airports():
        for he_key, en_key in (("country_he", "country_en"), ("city_he", "city_en")):
            he = str(airport.get(he_key) or "").strip()
            en = str(airport.get(en_key) or "").strip()
            if he:
                known[he] = he
            if en:
                known[en.lower()] = en
    for alias, canonical in _DESTINATION_SPELLING_ALIASES.items():
        known[alias] = canonical
    # Longer names first so "דרום אפריקה" matches before a shorter,
    # coincidentally-contained needle would.
    _KNOWN_DESTINATION_NAMES_CACHE = dict(sorted(known.items(), key=lambda kv: -len(kv[0])))
    return _KNOWN_DESTINATION_NAMES_CACHE


def _clear_stale_gateway_airports(state):
    """destination_airports/return_departure_airports must belong to the
    country of the CURRENT destination.places - if every code on the list
    belongs to some other country entirely, it's stale data left over from
    a previous, different destination.

    This isn't about the ordinary "destination_airports is closed, never
    reconsider it" rule (that protects an already-chosen gateway WITHIN
    the same destination from being second-guessed) - this is a genuine
    destination change the structured field never followed. Most often
    this survives a "new vacation" reset: the structured destination_
    airports field gets cleared, but the OLD conversation text mentioning
    the previous destination's airport is still visible in full chat
    history (history is never erased, only vacation data - see
    EXTRACTOR_SYSTEM's own "backfill a fact that's missing from state but
    was mentioned earlier in the conversation" rule), and the extractor
    can wrongly pull that old airport back in even though the customer
    is no longer asking about it at all. Seen live: a brand-new Vietnam
    vacation's flight summary correctly named Hanoi throughout, but
    destination_airports stayed stuck on "LCA" (Larnaca, Cyprus) from an
    earlier, unrelated conversation - nothing deterministic ever caught
    the mismatch."""
    state = state if isinstance(state, dict) else {}
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    places = [str(p).strip() for p in (destination.get("places") or []) if str(p).strip()]
    if not places:
        return state
    airports = _load_airports()
    by_code = {str(a.get("code") or "").upper(): a for a in airports}

    def _countries_for(names):
        found = set()
        for name in names:
            needle = str(name).strip().lower()
            if not needle:
                continue
            for airport in airports:
                hay = " ".join(str(airport.get(k) or "") for k in ("country_he","country_en","city_he","city_en")).lower()
                if hay and (needle in hay or hay in needle):
                    country = str(airport.get("country_he") or "").strip()
                    if country:
                        found.add(country)
                    break
        return found

    place_countries = _countries_for(places)
    if not place_countries:
        return state

    changed = False
    new_state = dict(state)
    for field in ("destination_airports", "return_departure_airports"):
        codes = state.get(field)
        if not isinstance(codes, list) or not codes:
            continue
        stale = all(
            str((by_code.get(str(code).upper()) or {}).get("country_he") or "").strip() not in place_countries
            for code in codes
        )
        if stale:
            new_state[field] = []
            changed = True
    return new_state if changed else state


def _deterministic_destination_facts(history, message, state=None):
    """Preserve an explicitly stated destination when extractor output misses it."""
    state = state if isinstance(state, dict) else {}
    current = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    if current.get("places"):
        return {}
    # Customer messages only, most recent first. Ariella's own replies name
    # other countries all the time for comparison ("like in Italy...") - and
    # a plain dict-order scan of everything picked whichever known country
    # came first in this dict, not what the customer actually asked for.
    texts = [str(message or "")] + [
        str(x.get("content") or "") for x in reversed(history or [])
        if isinstance(x, dict) and str(x.get("role") or "").lower() == "user"
    ]
    known = _known_destination_names()
    for text in texts:
        text = text.lower()
        for needle, label in known.items():
            if needle.lower() in text:
                return {"destination": {"places": [label], "mode": "specific", "status": "known"}}
    return {}


def _deterministic_date_facts(history, message, state=None):
    """Reinforce explicit dates already present in the conversation without guessing."""
    import re
    state = state if isinstance(state, dict) else {}
    current_dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    # Customer messages only. Ariella's replies carry many dates that are not
    # the travel dates - alternative ranges she offered, per-day dates inside
    # a route, lodging check-ins - and "the last two dates anywhere" silently
    # adopted them as departure/return. Dates she proposed are accepted by
    # the dedicated proposal/candidate-choice parsers instead.
    parts = [
        str(x.get("content") or "") for x in (history or [])
        if isinstance(x, dict) and str(x.get("role") or "").lower() == "user"
    ]
    parts.append(str(message or ""))
    text = " ".join(parts)
    found = []
    for m in re.finditer(r"(?<!\d)(\d{1,2})[./-](\d{1,2})[./-](20\d{2})(?!\d)", text):
        try:
            found.append(date(int(m.group(3)), int(m.group(2)), int(m.group(1))))
        except ValueError:
            pass
    for m in re.finditer(r"(?<!\d)(20\d{2})-(\d{1,2})-(\d{1,2})(?!\d)", text):
        try:
            found.append(date(int(m.group(1)), int(m.group(2)), int(m.group(3))))
        except ValueError:
            pass
    unique = []
    for d in found:
        if d not in unique:
            unique.append(d)
    if len(unique) < 2:
        return {}
    dep, ret = unique[-2], unique[-1]
    if ret < dep:
        return {}
    return {"dates": {"departure": dep.isoformat(), "return": ret.isoformat()}}

def _deterministic_duration_facts(message, state=None):
    """If a departure date is known and customer gives a duration, calculate return deterministically."""
    import re
    state = state if isinstance(state, dict) else {}
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    dep_raw = str(dates.get("departure") or "")[:10]
    if not dep_raw:
        return {}
    # Only to COMPLETE a missing return date. Seen live: with exact dates
    # already agreed, any later "N nights"/"N days" mention inside the route
    # discussion ("2 לילות בכל מקום", "3 ימים בספליט") ran through here after
    # the sticky-dates lock and silently rewrote the return date to
    # departure+N - a new trip length the customer never asked for. Changing
    # agreed dates takes explicit new dates, handled by the date parsers.
    if dates.get("return") or str(state.get("active_session") or "") == "trip_planning":
        return {}
    msg = str(message or "").strip().lower()
    import re as _re_dur
    hebrew_durations = {
        "שבועיים": (2, "שבועות"),
        "שבוע": (1, "שבועות"),
    }
    # Standalone word only (optionally "ל"/"ו" prefixed) - "בשבוע הבא" or
    # "סוף שבוע" are not a trip length.
    matched = next(
        (value for phrase, value in hebrew_durations.items()
         if _re_dur.search(r"(?<![א-ת])(?:ל|ו|ול)?" + phrase + r"(?![א-ת])", msg)
         and not _re_dur.search(r"סוף\s+" + phrase, msg)),
        None,
    )
    if matched:
        n, unit = matched
    else:
        m = re.search(r"(\d+)\s*(שבוע|שבועות|ימים|יום|לילות|לילה)", msg)
        if not m:
            return {}
        n = int(m.group(1))
        unit = m.group(2)
    if n <= 0:
        return {}
    try:
        dep = date.fromisoformat(dep_raw)
    except ValueError:
        return {}
    if unit in ("שבוע","שבועות"):
        # "שבועיים" is commonly written without a numeral; handled below.
        delta_days = n * 7
    elif unit in ("לילות","לילה"):
        delta_days = n
    else:
        delta_days = max(0, n - 1)
    ret = dep + timedelta(days=delta_days)
    duration_days = (ret - dep).days + 1
    return {"dates":{"departure":dep.isoformat(),"return":ret.isoformat(),
        "period":f"{dep.strftime('%d.%m.%Y')}–{ret.strftime('%d.%m.%Y')}",
        "duration_days":duration_days,
        "needs_confirmation":False,"candidate_ranges":[]}}

def _accept_assistant_single_date_proposal(history, message, state=None):
    """Commit one concrete range proposed in Ariella's immediately previous reply when customer continues without changing dates."""
    import re
    state = state if isinstance(state, dict) else {}
    current = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    if current.get("departure") and current.get("return"):
        return {}
    # Only while dates are actually the thing being discussed (the flights
    # session). Two dd.mm.yyyy-looking numbers can show up in an itinerary/
    # route reply for an unrelated reason (a local festival's dates, a
    # recommended season window, etc.) - seen live: a trip-planning
    # conversation mentioned two such dates, the customer's next reply was an
    # ordinary continuation with no rejection wording, and this function
    # silently adopted them as the confirmed flight departure/return dates
    # the customer had never actually been asked about or given.
    if str(state.get("active_session") or "") == "trip_planning":
        return {}
    msg = str(message or "").strip().lower()
    # Explicit correction/rejection/date text means let the normal parsers handle it.
    # "תשני" ("change [it]") is deliberately NOT treated as a rejection here:
    # a live transcript showed "מצוין. תשני רק את תאריך החזרה" ("great, change
    # only the return date") - the customer AGREEING with Ariella's own just-
    # proposed date and asking for a specific follow-up - get bailed out on as
    # if the date itself had been rejected, leaving a stale, never-actually-
    # confirmed date silently stuck in state. A genuinely different new date
    # still overrides this correctly via the dedicated date-fact parsers that
    # run after this one, so dropping this one keyword is safe either way.
    if any(x in msg for x in ("לא", "במקום", "אחר", "לא מתאים")) or re.search(r"\d{1,2}[./-]\d{1,2}", msg):
        return {}
    assistant_text = ""
    for item in reversed(history or []):
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").lower()
        if role in ("assistant","ariella","tinkerbell"):
            assistant_text = str(item.get("content") or "")
            break
    if not assistant_text:
        return {}
    # Belt-and-suspenders alongside the trip_planning exclusion above: even
    # inside the flights session, two dates appearing in the text is not by
    # itself evidence they were offered AS a departure/return proposal (vs.
    # e.g. an unrelated aside). Require wording that actually frames them as
    # travel dates.
    date_proposal_cues = ("לצאת","לחזור","יציאה","חזרה","תאריך","נחיתה","טיסה","מתאים")
    if not any(cue in assistant_text for cue in date_proposal_cues):
        return {}
    found = re.findall(r"(?<!\d)(\d{1,2})[./-](\d{1,2})[./-](20\d{2})(?!\d)", assistant_text)
    parsed = []
    for day, month, year in found:
        try:
            d = date(int(year), int(month), int(day))
            if d not in parsed:
                parsed.append(d)
        except ValueError:
            pass
    # Exactly one pair only: if Ariella offered alternatives, customer must choose.
    if len(parsed) != 2 or parsed[1] <= parsed[0]:
        return {}
    dep, ret = parsed
    return {"dates":{
        "departure":dep.isoformat(),"return":ret.isoformat(),
        "period":f"{dep.strftime('%d.%m.%Y')}–{ret.strftime('%d.%m.%Y')}",
        "needs_confirmation":False,"candidate_ranges":[]
    }}


def _accept_single_proposed_date_range(message, state=None):
    """A single concrete date proposal becomes authoritative when the customer continues without rejecting/changing it."""
    import re
    state = state if isinstance(state, dict) else {}
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    candidates = dates.get("candidate_ranges") if isinstance(dates.get("candidate_ranges"), list) else []
    if not dates.get("needs_confirmation") or len(candidates) != 1:
        return {}
    msg = str(message or "").strip().lower()
    # "תשני" ("change [it]") deliberately excluded - see
    # _accept_assistant_single_date_proposal's docstring/comment for the
    # live-transcript false rejection this caused ("מצוין. תשני רק את תאריך
    # החזרה" read as rejecting the very date it was agreeing to).
    reject = ("לא", "במקום", "שני את", "אחר", "אחרת", "לא מתאים")
    if any(x in msg for x in reject):
        return {}
    chosen = str(candidates[0])
    found = re.findall(r"(\d{1,2})[./](\d{1,2})[./](20\d{2})", chosen)
    if len(found) != 2:
        return {}
    try:
        dep = date(int(found[0][2]), int(found[0][1]), int(found[0][0]))
        ret = date(int(found[1][2]), int(found[1][1]), int(found[1][0]))
    except ValueError:
        return {}
    if ret <= dep:
        return {}
    return {"dates":{
        "departure":dep.isoformat(),"return":ret.isoformat(),
        "period":f"{dep.strftime('%d.%m.%Y')}–{ret.strftime('%d.%m.%Y')}",
        "needs_confirmation":False,"candidate_ranges":[]
    }}


def _deterministic_candidate_choice_facts(message, state=None):
    """Resolve a customer's selected candidate date range into exact ISO dates."""
    import re
    state = state if isinstance(state, dict) else {}
    dates = state.get("dates") if isinstance(state.get("dates"), dict) else {}
    candidates = dates.get("candidate_ranges") if isinstance(dates.get("candidate_ranges"), list) else []
    if not dates.get("needs_confirmation") or not candidates:
        return {}
    msg = str(message or "").strip()
    # Accept an exact range repeated by the customer, or an ordinal choice such as
    # "הראשון/השני" after Ariella displayed candidate ranges.
    chosen = None
    ordinal_map = {"הראשון":0,"ראשון":0,"הראשונה":0,"השני":1,"שני":1,"השנייה":1,"השניה":1}
    for word, idx in ordinal_map.items():
        if word in msg and idx < len(candidates):
            chosen = candidates[idx]
            break
    if chosen is None:
        normalized_msg = msg.replace("–","-").replace("—","-").replace(" ","")
        for candidate in candidates:
            if str(candidate).replace("–","-").replace("—","-").replace(" ","") in normalized_msg:
                chosen = candidate
                break
    if chosen is None:
        # A natural short answer repeating just the two day-of-month numbers
        # Ariella herself just displayed ("18 עד 22") - not the full
        # "18.4.2027" with month/year, which the exact-substring check above
        # requires. Seen live: this fell through to {} every time, so the
        # choice was silently never recorded, and the customer got asked
        # for dates again several turns later as if she'd never answered.
        # Only matches when exactly one candidate's own (departure_day,
        # return_day) pair appears in that order in the message, so a
        # coincidental lone number elsewhere in a longer reply can't misfire.
        # A "D.M" token (e.g. "1.7") counts as a single day-number (the day),
        # not two separate bare numbers - otherwise "1.7 עד 27" (seen live:
        # the customer referencing the return date in day.month shorthand,
        # then the departure day bare, in REVERSE order) split into [1, 7, 27]
        # and never lined up against any candidate, so the choice silently
        # failed to resolve and Tinkerbell was left to free-text its own
        # guess at the dates - exactly the "never compute dates yourself"
        # mistake the prompt already warns against, just reached a different
        # way (no candidate matched, not no candidates at all).
        day_numbers = []
        for m in re.finditer(r"(?<!\d)(\d{1,2})\.(\d{1,2})(?!\d)|(?<!\d)(\d{1,2})(?!\d)", msg):
            day_numbers.append(int(m.group(1) if m.group(1) is not None else m.group(3)))
        if len(day_numbers) >= 2:
            candidate_day_pairs = []
            for candidate in candidates:
                found_days = re.findall(r"(\d{1,2})[./](\d{1,2})[./](20\d{2})", str(candidate))
                if len(found_days) == 2:
                    candidate_day_pairs.append((candidate, int(found_days[0][0]), int(found_days[1][0])))
            matches = [
                candidate for candidate, dep_day, ret_day in candidate_day_pairs
                for i in range(len(day_numbers) - 1)
                if (day_numbers[i] == dep_day and day_numbers[i + 1] == ret_day)
                or (day_numbers[i] == ret_day and day_numbers[i + 1] == dep_day)
            ]
            if len(matches) == 1:
                chosen = matches[0]
    if chosen is None:
        return {}
    found = re.findall(r"(\d{1,2})[./](\d{1,2})[./](20\d{2})", str(chosen))
    if len(found) != 2:
        return {}
    try:
        dep = date(int(found[0][2]), int(found[0][1]), int(found[0][0]))
        ret = date(int(found[1][2]), int(found[1][1]), int(found[1][0]))
    except ValueError:
        return {}
    if ret <= dep:
        return {}
    return {"dates":{
        "departure":dep.isoformat(),"return":ret.isoformat(),
        "period":f"{dep.strftime('%d.%m.%Y')}–{ret.strftime('%d.%m.%Y')}",
        "needs_confirmation":False,"candidate_ranges":[]
    }}


def _deterministic_only_flights_facts(message):
    """'Only flights' is an explicit decision for all four service domains."""
    msg = str(message or "").strip().lower()
    compact = " ".join(msg.split())
    only_flights = any(p in compact for p in (
        "רק טיסות", "טיסות בלבד", "רק טיסה", "טיסה בלבד",
        "only flights", "flights only"
    ))
    if not only_flights:
        return {}
    return {
        "search_intent": True,
        "requested_services": ["flights"],
        "service_decisions": {
            "flights": {"wanted": True, "source": "explicit_only_flights"},
            "lodging": {"wanted": False, "source": "explicit_only_flights"},
            "car": {"wanted": False, "source": "explicit_only_flights"},
            "trip_planning": {"wanted": False, "source": "explicit_only_flights"},
        },
        "session_status": {
            "flights": "active", "lodging": "declined",
            "car": "declined", "trip_planning": "declined"
        },
        "active_session": "flights",
    }


def _deterministic_budget_facts(message):
    """Treat explicit no-budget-limit language as a completed budget decision,
    and parse an explicit numeric budget amount directly - never depend on
    an LLM call alone for a fact this structured (the extractor, or the
    _budget_answer_by_meaning fallback below, each a single point of
    failure on their own). Seen live: "טרולי לכל אחד ותקציב של עד 1000
    לכרטיס" - a perfectly ordinary, common phrasing - was not captured, and
    Ariella asked for the budget again immediately after the customer had
    just stated it in the very same message."""
    msg = str(message or "").strip().lower()
    no_limit_phrases = (
        "אין תקציב", "אין לי תקציב", "ללא תקציב", "בלי תקציב", "בלי הגבלה", "ללא הגבלה",
        "אין הגבלת תקציב", "ללא הגבלת תקציב", "לא מוגבלת בתקציב",
        "לא מוגבל בתקציב", "אין מגבלת תקציב"
    )
    if any(p in msg for p in no_limit_phrases):
        return {"budget_per_person":{"amount":None,"currency":None,"status":"unlimited"}}
    # Either "תקציב ... <number>" (the word itself, a number shortly after -
    # "עד", "של", "בערך" etc. in between), or a bare "<number> <currency?>
    # לאדם/לכרטיס/לנוסע" even without the word "תקציב" at all.
    # The currency word/amount of intervening text varies too much to
    # require an exact enum right next to the number ("1000 שח לאדם" has no
    # gershayim, "1000 שקלים בערך לאדם" has an extra word) - same lazy
    # "any non-digit text within a short window" approach as the תקציב
    # pattern above, not a fixed phrase list.
    m = re.search(r"תקציב[^\d]{0,20}?(\d{2,6})", msg) \
        or re.search(r"(\d{2,6})[^\d]{0,15}?ל(?:כל\s+)?(?:אדם|כרטיס|נוסע|אחד)", msg)
    if m:
        amount = int(m.group(1))
        currency = "USD" if re.search(r"דולר|\$", msg) else "EUR" if re.search(r"יורו|€", msg) else "ILS"
        return {"budget_per_person": {"amount": amount, "currency": currency, "status": "known"}}
    return {}


def _budget_answer_by_meaning(message, history, state):
    """Seen live: Ariella replied "בלי הגבלת תקציב מוגדרת" - she understood
    there's no limit - but the phrase list above didn't match the
    customer's wording, budget stayed "unknown", and she asked about the
    budget again. When the last question was about the budget and it is
    still open, the answer is read by meaning (per product owner, not by a
    word list)."""
    budget = state.get("budget_per_person") if isinstance(state.get("budget_per_person"), dict) else {}
    if budget.get("amount") is not None or budget.get("status") in ("unlimited", "none", "no_limit"):
        return {}
    last_assistant = next(
        (str(x.get("content") or "") for x in reversed(history or [])
         if isinstance(x, dict) and x.get("role") == "assistant"), "")
    if "תקציב" not in last_assistant:
        return {}
    key = os.getenv("ANTHROPIC_API_KEY", "").strip()
    if not key:
        return {}
    model = os.getenv("ARIELLA_MODEL", "claude-sonnet-5").strip()
    prompt = (
        "את מסווגת תשובת לקוח לשאלת תקציב של סוכנת נסיעות. הביני לפי משמעות, בכל ניסוח. "
        "החזירי JSON בלבד: {\"budget\": \"unlimited\"} אם אין מגבלת תקציב / המחיר לא משנה / תקציב פתוח, "
        "{\"budget\": <מספר>, \"currency\": \"ILS\"|\"USD\"|\"EUR\"} אם נמסר סכום לאדם, "
        "או {\"budget\": null} אם התשובה לא עונה על שאלת התקציב."
    )
    try:
        raw = _post_claude(key, model, prompt, "", [], "שאלת הסוכנת: " + last_assistant[-500:] + "\nתשובת הלקוח: " + str(message or ""), 40, include_history=False, source="classifier")
        raw = raw.strip()
        data = json.loads(raw[raw.index("{"):raw.rindex("}") + 1])
    except Exception:
        return {}
    value = data.get("budget")
    if value == "unlimited":
        return {"budget_per_person": {"amount": None, "currency": None, "status": "unlimited"}}
    if isinstance(value, (int, float)) and value > 0:
        return {"budget_per_person": {"amount": value, "currency": data.get("currency") or "ILS", "status": "known"}}
    return {}


def _deterministic_baggage_facts(message):
    """Safety net for flight.baggage: a customer often answers baggage mixed
    into one longer reply that also covers origin airport, direct/connection
    preference and budget all at once. The extractor sometimes drops just the
    baggage part of a message like that, so Tinkerbell asks about baggage
    again next turn - even after it was already answered, sometimes more than
    once in a row. Matches only clear, unambiguous phrasing to avoid false
    positives; order matters, since "carry-on only" phrasing must be checked
    before a bare "no baggage" match ("רק טרולי" means a trolley, not nothing)."""
    import re
    msg = str(message or "")
    if not msg.strip():
        return {}
    # "X מספיק" ("X is enough") is as unambiguous a sufficiency statement as
    # "רק X"/"X בלבד" - seen live: "טרולי מספיק" answered the exact baggage
    # question (טרולי בלבד/גם מזוודה בבטן המטוס/רק תיק) and matched none of
    # the patterns below, so the same question was asked again verbatim
    # forever.
    if re.search(r"רק\s+טרולי|טרולי\s+בלבד|טרולי\s+לכל\s+אחד|רק\s+כבודת\s+עלי|טרולי\s+מספיק", msg):
        return {"flight": {"baggage": ["carry_on_only"]}}
    # "מזוודה למחסן" is kept alongside the correct "בטן המטוס" phrasing -
    # this only ever reads the CUSTOMER's own words, never Ariella's (the
    # system prompt rule, baggage_labels and _flight_gap_question above only
    # ever say "בבטן המטוס" now - "מחסן" isn't a real aviation term at all).
    if re.search(r"מזוודה\s+למחסן|מזוודה\s+בבטן\s+ה?מטוס|מזוודות?\s+גדול|יש\s+ל(נו|י)\s+מזוודה", msg):
        return {"flight": {"baggage": ["checked_bag"]}}
    if re.search(r"רק\s+תיק\s+יד|תיק\s+קטן\s+בלבד|רק\s+תיק(?!\s+עלי)|תיק\s+מספיק(?!\s+עלי)", msg):
        return {"flight": {"baggage": ["personal_item"]}}
    if re.search(r"אין\s+לי\s+שום\s+כבודה|בלי\s+שום\s+כבודה|בלי\s+כבודה\s+בכלל", msg):
        return {"flight": {"baggage": ["no_baggage"]}}
    return {}


def _deterministic_service_decline_facts(history, message):
    """Safety net for a short decline reply ("לא"/"גם לא"/"גם לא כרגע"/"לא
    תודה" etc.) to Ariella's own immediately previous question about a
    SPECIFIC service (lodging or car). A short, context-only reply like this
    names no service itself, and a live transcript showed the extractor lose
    track of which one it answered: a lodging decline got misattributed to
    the car question being re-asked, and by the time car was declined
    lodging had silently reverted to pending and got asked again from
    scratch - an outright loop between the two. Only fires when Ariella's
    own last message unambiguously named exactly one of the two services."""
    compact = " ".join(str(message or "").strip().split())
    decline_phrases = {
        "לא", "לא.", "לא!", "לא תודה", "גם לא", "גם לא כרגע", "לא כרגע",
        "לא צריך", "לא צריכים", "בלי", "לא תודה כרגע",
    }
    if compact not in decline_phrases:
        return {}
    assistant_text = ""
    for item in reversed(history or []):
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").lower()
        if role in ("assistant", "ariella", "tinkerbell"):
            assistant_text = str(item.get("content") or "")
            break
    if not assistant_text:
        return {}
    # Ariella's reply often acknowledges the PREVIOUS topic in one sentence
    # before asking about the new one ("understood, no lodging - now, about
    # a rental car?") - checking the whole message for either keyword would
    # see both and bail out as ambiguous. The actual question lives in the
    # final clause, so only that is checked.
    import re
    clauses = [c.strip() for c in re.split(r"[.!?]+", assistant_text) if c.strip()]
    last_clause = clauses[-1] if clauses else assistant_text
    lodging_kw = ("לינה", "מלון", "וילה", "דירה", "אכסניה")
    mentions_lodging = any(k in last_clause for k in lodging_kw)
    mentions_car = "רכב" in last_clause
    if mentions_lodging and not mentions_car:
        service = "lodging"
    elif mentions_car and not mentions_lodging:
        service = "car"
    else:
        return {}
    return {
        "service_decisions": {service: {"wanted": False, "source": "explicit_short_decline"}},
        "session_status": {service: "declined"},
    }


def _deterministic_named_decline_facts(message):
    """A decline that names its own service doesn't need the previous
    question for context at all ("רכב לא נדרש", "לא צריך לינה") - unlike
    _deterministic_service_decline_facts above, this never depends on
    matching Ariella's prior message. Seen live: "רכב לא נדרש" left as pure
    free text for the extractor to interpret, and the car session apparently
    never actually flipped to "declined" in the returned state even though
    the reply acknowledged it - leaving the four-session progression stuck
    with car neither complete nor declined, so the vacation could never be
    marked fully resolved and the client never navigated to the waiting
    page. Deliberately narrow (exact short phrases only) to avoid
    misreading a longer sentence that merely mentions the word "רכב".

    Two gaps found live, both in the same exchange: the customer answered
    an airport-choice question and, in the same message, proactively
    declined trip_planning before it was ever asked about - "תחפשי
    בשניהם. לא צריך מסלול כרגע" ("search both. don't need a route right
    now"). First gap: the "need" alternation only covered the FEMININE
    "צריכה" (plus "רוצה"/"רוצים") - "צריכה?" as a regex is "צריכ" with an
    optional trailing ה, which never matches the masculine "צריך" (different
    final letter, כ vs ך) at all, so a masculine decline was silently
    ignored regardless of anything else. Second gap: matching required the
    ENTIRE message to be nothing but the decline phrase (anchored ^...$
    against the whole string), so bundling it with an unrelated answer in
    the same message - exactly how a customer naturally writes two things
    at once - made it invisible. Fixed by checking each sentence clause of
    the message independently (not just the message as a whole) against a
    masculine/feminine/plural-covering pattern that also tolerates a
    trailing "כרגע"/"עכשיו" qualifier."""
    import re
    msg = str(message or "").strip()
    if not msg:
        return {}
    clauses = [c.strip() for c in re.split(r"[.!?]+", msg) if c.strip()] or [msg]
    need_word = r"(?:צריך|צריכה|רוצה|רוצים)"
    qualifier = r"(?:\s+(?:כרגע|עכשיו))?"
    patterns = {
        "car": (
            rf"^רכב\s+לא\s+נדרש{qualifier}\.?!?$",
            rf"^לא\s+{need_word}\s+רכב{qualifier}\.?!?$",
            r"^בלי\s+רכב\.?!?$",
        ),
        "lodging": (
            rf"^לינה\s+לא\s+נדרש[הת]?{qualifier}\.?!?$",
            rf"^לא\s+{need_word}\s+לינה{qualifier}\.?!?$",
            r"^בלי\s+לינה\.?!?$",
        ),
        "trip_planning": (
            rf"^מסלול\s+לא\s+נדרש{qualifier}\.?!?$",
            rf"^לא\s+{need_word}\s+מסלול{qualifier}\.?!?$",
        ),
    }
    for clause in clauses:
        if len(clause) > 40:
            continue
        for service, service_patterns in patterns.items():
            if any(re.match(p, clause) for p in service_patterns):
                return {
                    "service_decisions": {service: {"wanted": False, "source": "explicit_named_decline"}},
                    "session_status": {service: "declined"},
                }
    return {}


def _deterministic_period_facts(message, history=None):
    """Parse weekday/month windows ("סוף יוני, ראשון עד חמישי") into exact
    candidate ranges, so Ariella never computes calendar dates herself.

    Seen live: the customer wrote "סוף יוני" in one message and "ראשון עד
    חמישי" in the next. This used to require both in the SAME message, so no
    candidates were computed and the model invented its own: 28.6-2.7 and
    5.7-9.7 - Sunday-Thursday in the already-past 2026 calendar (Monday-Friday
    in 2027), the second one entirely in July. The month/part-of-month and
    the weekday pair may now come from the current message or the customer's
    recent messages. Per product owner: a range whose DEPARTURE is inside the
    requested part of the month is offered even if the return falls in the
    next month (end of June -> 27.6-1.7 is fine), but a range departing in
    the next month never is (5.7-9.7 for "end of June")."""
    import re, calendar
    months={"ינואר":1,"פברואר":2,"מרץ":3,"אפריל":4,"מאי":5,"יוני":6,"יולי":7,"אוגוסט":8,"ספטמבר":9,"אוקטובר":10,"נובמבר":11,"דצמבר":12}
    weekdays={"ראשון":6,"שני":0,"שלישי":1,"רביעי":2,"חמישי":3,"שישי":4,"שבת":5}
    day_alt="ראשון|שני|שלישי|רביעי|חמישי|שישי|שבת"
    msg=str(message or "").strip().lower()
    recent=[msg]+[str(x.get("content") or "").strip().lower() for x in reversed(history or [])
                  if isinstance(x,dict) and str(x.get("role") or "").lower()=="user"][:6]

    def find_month(text):
        # Whole word only (optionally ב/ל/מ/ו-prefixed): "מאיזה"/"מאיפה" are not May.
        for name,num in months.items():
            if re.search(r"(?<![\u05d0-\u05ea])(?:ב|ל|מ|ו|וב|ול|ומ)?"+name+r"(?![\u05d0-\u05ea])",text):
                return name,num
        return None,None

    def find_pair(text):
        return re.search(r"(?<![\u05d0-\u05ea])(?:מ|מיום\s+|יום\s+)?("+day_alt+r")\s*(?:עד|[-–])\s*(?:יום\s+)?("+day_alt+r")(?![\u05d0-\u05ea])",text)

    month_name,month=find_month(msg); pair=find_pair(msg)
    # Only complete a fact from recent messages when the current message
    # itself contributes one of the two - never re-fire on unrelated turns.
    if not (month or pair):return {}
    month_text=msg if month else None
    if not month:
        for t in recent[1:]:
            month_name,month=find_month(t)
            if month:month_text=t;break
    if not pair:
        for t in recent[1:]:
            pair=find_pair(t)
            if pair:break
    if not month or not pair:return {}
    today=date.today(); year=today.year+(1 if month<today.month else 0)
    start_wd,end_wd=weekdays[pair.group(1)],weekdays[pair.group(2)]; delta=(end_wd-start_wd)%7
    last=calendar.monthrange(year,month)[1]
    part=None
    for word,key in (("סוף","end"),("תחילת","start"),("בתחילת","start"),("אמצע","mid")):
        if word in month_text:part=key;break
    if part:
        window={"end":(last-13,last),"start":(1,14),"mid":(8,22)}[part]
        candidates=[]
        for day in range(max(1,window[0]),window[1]+1):
            d=date(year,month,day)
            if d.weekday()==start_wd and d>today:
                candidates.append((d,d+timedelta(days=delta)))
        candidates=candidates[-2:] if part=="end" else candidates[:2]
        labels=[f"{x.strftime('%d.%m.%Y')}–{y.strftime('%d.%m.%Y')}" for x,y in candidates]
        part_he={"end":"סוף","start":"תחילת","mid":"אמצע"}[part]
        return {"dates":{"departure":None,"return":None,"period":f"{part_he} {month_name} {year}, {pair.group(1)} עד {pair.group(2)}","constraints":[f"{pair.group(1)} עד {pair.group(2)}"],"candidate_ranges":labels,"needs_confirmation":True}}
    after=re.search(r"אחרי\s+(?:ה[- ]?)?(\d{1,2})",month_text or msg)
    # Without an anchor day ("אחרי ה-15") the month has 4-5 such weeks - that
    # is a choice for the customer, never the first week picked for her.
    if not after:return {"dates":{"period":f"{pair.group(1)} עד {pair.group(2)} ב{month_name} {year}"}}
    min_day=int(after.group(1))+1
    start=None
    for day in range(min_day,32):
        try:d=date(year,month,day)
        except ValueError:break
        if d.weekday()==start_wd:start=d;break
    if not start:return {"dates":{"period":f"{pair.group(1)} עד {pair.group(2)} ב{month_name} {year}"}}
    end=start+timedelta(days=delta)
    return {"dates":{"departure":start.isoformat(),"return":end.isoformat(),"period":f"{pair.group(1)} עד {pair.group(2)}","constraints":[f"אחרי {min_day-1}.{month}.{year}"]}}

def _deterministic_departure_airport_facts(message):
    """Capture an explicitly named Israeli departure airport so it never depends
    solely on the extractor remembering to copy it over in a dense message."""
    import re
    msg = str(message or "").strip().lower()
    tlv_phrases = (
        "נתבג", 'נתב"ג', "נתב’ג", "נתב'ג", "מנתבג", 'מנתב"ג',
        "בן גוריון", "בן-גוריון", "מבן גוריון", "מבן-גוריון", "tlv",
    )
    if any(p in msg for p in tlv_phrases):
        return {"departure_airport": "TLV"}
    # "חיפה" alone is ambiguous (a home city, not necessarily the airport), so
    # only match it when the message clearly ties it to departing/the airport.
    hfa_phrases = ("משדה חיפה", "משדה תעופה חיפה", "hfa")
    if any(p in msg for p in hfa_phrases):
        return {"departure_airport": "HFA"}
    if re.search(r"(נצא|לצאת|יציאה|טסים|נטוס)[^.,!?]{0,6}מחיפה", msg):
        return {"departure_airport": "HFA"}
    return {}


def _deterministic_trip_type_facts(message):
    """Capture an explicit vacation-type choice (regular/business/ski) so the
    opening question doesn't depend solely on the LLM extractor."""
    msg = str(message or "").strip().lower()
    # Short exact replies (matched only against the whole, trimmed message -
    # never as a substring) cover directly answering the opening question
    # ("regular vacation, business trip, or ski vacation?") with just one
    # word, without risking a false match inside an unrelated longer sentence.
    business_exact = {"עסקים", "נסיעת עסקים", "עסקי", "עסקית", "business"}
    ski_exact = {"סקי", "חופשת סקי", "ski"}
    standard_exact = {"רגילה", "חופשה רגילה", "רגיל", "standard", "regular"}
    if msg in business_exact:
        return {"trip_type": "business"}
    if msg in ski_exact:
        return {"trip_type": "ski"}
    if msg in standard_exact:
        return {"trip_type": "standard"}
    business_phrases = ("נסיעת עסקים", "נסיעה עסקית", "טיסת עסקים", "טיול עסקים", "business trip")
    ski_phrases = ("חופשת סקי", "טיול סקי", "נסיעת סקי", "לגלוש בסקי", "חופשת גלישה בשלג", "ski trip", "ski vacation")
    # A "family trip"/"family vacation" is unambiguously a standard leisure
    # vacation - not business, not specifically ski - even though the
    # customer never used the literal word "רגילה". Seen live: a customer
    # answered the opening trip-type question with "לתכנן טיול משפחתי" and
    # reasonably expected that to count, but the strict extractor rule
    # (never infer trip_type from context) left it stuck asking the same
    # opening question again much later, mid-conversation, after everything
    # else had already moved forward - confusing since the customer had
    # already, in their own words, answered it.
    standard_phrases = (
        "חופשה רגילה", "חופשת נופש", "לא, חופשה", "זו חופשה",
        "טיול משפחתי", "חופשה משפחתית", "נסיעה משפחתית", "טיול עם המשפחה", "חופשה עם המשפחה",
    )
    if any(p in msg for p in business_phrases):
        return {"trip_type": "business"}
    if any(p in msg for p in ski_phrases):
        return {"trip_type": "ski"}
    if any(p in msg for p in standard_phrases):
        return {"trip_type": "standard"}
    return {}


def _infer_standard_trip_type(state, message, history):
    """Seen live: after the whole route and the flights were already worked
    out for a customer who opened with "I want to plan a route in Croatia",
    the flights gap check still asked "regular vacation, business trip, or
    ski?" - the customer never said the literal word "רגילה" and the
    extractor is told never to infer trip_type. Asking for a route,
    attractions or places to go out is itself the answer: business and ski
    trips don't get an itinerary (see TINKERBELL_SYSTEM). Children alone are
    NOT evidence - families go on ski trips too - and a customer who only
    asked for flights/lodging/car still gets the question."""
    import re
    state = state if isinstance(state, dict) else {}
    if state.get("trip_type"):
        return {}
    texts = [str(message or "")]
    for item in reversed(history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "user":
            texts.append(str(item.get("content") or ""))
            if len(texts) >= 12:
                break
    blob = " ".join(texts).lower()
    ski_words = ("סקי", "שלג", "גלישה", "מדרון", "ski", "snow")
    business_words = ("עסקים", "עסקית", "עסקי", "כנס", "ועידה", "תערוכה", "פגישת", "business", "conference")
    if any(w in blob for w in ski_words + business_words):
        return {}
    ski_state = state.get("ski") if isinstance(state.get("ski"), dict) else {}
    if any(v for v in ski_state.values()):
        return {}
    decisions = state.get("service_decisions") if isinstance(state.get("service_decisions"), dict) else {}
    planning = decisions.get("trip_planning")
    wants_planning = (planning.get("wanted") if isinstance(planning, dict) else planning) is True
    itinerary_words = (
        "מסלול", "אטרקציות", "אטרקציה", "מקומות בילוי", "בילוי", "בילויים", "לבלות",
        "תכנון טיול", "לתכנן טיול", "לטייל", "סיור", "סיורים", "מה לעשות", "מה לראות", "itinerary", "attractions",
    )
    has_itinerary = any(re.search(r"(?<![א-ת])(?:ו|ה|ב|ל|וה|וב|ול)?" + re.escape(w) + r"(?![א-ת])", blob) for w in itinerary_words)
    if wants_planning or has_itinerary:
        return {"trip_type": "standard"}
    # Children + a destination that is not a ski destination = a family
    # vacation (per product owner). Children alone are not enough - families
    # ski too - so only when every named place is clearly not skiing: not a
    # ski country/resort from SKI_RESORTS, and not a mountain gateway city.
    travelers = state.get("travelers") if isinstance(state.get("travelers"), dict) else {}
    try:
        has_children = int(travelers.get("children") or 0) > 0
    except (TypeError, ValueError):
        has_children = False
    has_children = has_children or bool(travelers.get("child_ages"))
    destination = state.get("destination") if isinstance(state.get("destination"), dict) else {}
    places = [str(p).strip().lower() for p in (destination.get("places") or []) if str(p).strip()]
    if has_children and places and not any(_is_possible_ski_place(p) for p in places):
        return {"trip_type": "standard"}
    return {}


# Airports whose city is mainly a gateway to the mountains - a family flight
# there may well be a ski trip, unlike e.g. Barcelona or Prague which also
# appear as ski gateways in SKI_RESORTS but are first of all city breaks.
_MOUNTAIN_GATEWAY_AIRPORTS = {"INN", "GVA", "SZG", "TRN"}


def _is_possible_ski_place(place):
    place = str(place or "").strip().lower()
    if not place:
        return False
    names = set()
    for row in SKI_RESORTS:
        for key in ("country", "country_he", "resort", "resort_he"):
            value = str(row.get(key) or "").strip().lower()
            if value:
                names.add(value)
    for airport in _load_airports():
        if str(airport.get("code") or "").upper() in _MOUNTAIN_GATEWAY_AIRPORTS:
            for key in ("city_he", "city_en"):
                value = str(airport.get(key) or "").strip().lower()
                if value:
                    names.add(value)
    return any(n in place or place in n for n in names)


def _deterministic_airport_indifference(message, history, state):
    """Seen live: Ariella asked "land around Split or Dubrovnik?", the
    customer answered that they had no preference, and nothing was saved -
    so destination_airports stayed empty and the flight summary later asked
    all over again (offering "build the route first?" to a customer who had
    asked for a route in their very first message). An indifferent answer to
    an airport question means every airport that question offered."""
    import re
    state = state if isinstance(state, dict) else {}
    if state.get("destination_airports"):
        return {}
    msg = str(message or "").strip()
    indifferent = ("אין העדפה", "אין לי העדפה", "לא משנה", "לא אכפת", "שניהם", "שתיהן", "גם וגם", "כולם", "כל אחד מהם", "מה שזול")
    if not msg or len(msg) > 60 or not any(p in msg for p in indifferent):
        return {}
    prior_assistant = ""
    for item in reversed(history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "assistant":
            prior_assistant = str(item.get("content") or "")
            break
    if not prior_assistant or not re.search(r"לנחות|נחיתה|שדה|שדות|כניסה", prior_assistant):
        return {}
    codes = []
    for airport in _load_airports():
        city = str(airport.get("city_he") or "").strip()
        code = str(airport.get("code") or "").upper()
        if city and code and re.search(r"(?<![א-ת])(?:ו|ב|ל|מ|וב|ול|ומ)?" + re.escape(city) + r"(?![א-ת])", prior_assistant):
            if code not in codes:
                codes.append(code)
    if len(codes) < 2:
        return {}
    return {"destination_airports": codes}


def _deterministic_open_jaw_airports(message):
    """Capture an explicit open-jaw answer ("לנחות בפאפוס ולחזור מלרנקה")
    deterministically instead of trusting the extractor to split it into
    destination_airports (arrival) vs return_departure_airports (return)
    correctly on its own. Seen live: exactly this answer to Ariella's own
    open-jaw question got both airports merged into destination_airports
    (as if it were a 2-city trip) instead of split - the vacation title
    showed both cities and the scan searched an ordinary round trip to only
    one of them, silently dropping the open-jaw request the customer had
    just explicitly confirmed."""
    import re
    msg = str(message or "").strip()
    if not msg:
        return {}
    # Single Hebrew word only - a greedy multi-word capture bled across the
    # rest of the sentence with nothing to stop it at the real city-name
    # boundary (e.g. captured "פאפוס ולחזור מלרנקה" as one "city name"),
    # which then spuriously matched multiple airports in the lookup below.
    # Every airport this needs to resolve today has a single-word Hebrew
    # city name, so this trades rare multi-word names for correctness on
    # the common case instead of guessing where to stop.
    arrival_match = re.search(r"לנחות\s+ב([א-ת]+)", msg)
    return_match = re.search(r"לחזור\s+מ([א-ת]+)", msg)
    if not arrival_match or not return_match:
        return {}
    airports = _load_airports()

    def find_code(name):
        needle = str(name or "").strip().lower()
        if not needle:
            return None
        for airport in airports:
            for key in ("city_he", "city_en"):
                hay = str(airport.get(key) or "").strip().lower()
                if hay and (needle in hay or hay in needle):
                    return str(airport.get("code") or "").upper()
        return None

    arrival_code = find_code(arrival_match.group(1))
    return_code = find_code(return_match.group(1))
    if not arrival_code or not return_code or arrival_code == return_code:
        return {}
    return {
        "destination_airports": [arrival_code],
        "return_departure_airports": [return_code],
        "open_jaw_requested": True,
    }


def _deterministic_trip_planning_pace_facts(message, history):
    """trip_planning.details.pace has no deterministic writer anywhere else -
    only the LLM's own JSON extraction ever sets it, and when that silently
    fails to persist a one-word answer, _session_gaps keeps re-flagging pace
    as missing forever. Seen live: the customer answered "פעיל" (active) to
    "יש לכם קצב מועדף?" and Ariella asked the exact same pace question again
    on the very next turn, then again the turn after that - a genuine
    infinite loop, never progressing to actually build the itinerary."""
    msg = str(message or "").strip()
    if not msg:
        return {}
    active_words = ("פעיל", "אינטנסיבי", "המון תוכן", "יום מלא", "רצף פעיל", "כמה שיותר")
    relaxed_words = ("רגוע", "נחים", "ימי מנוחה", "לאט", "רגועים")
    pace = None
    if any(w in msg for w in active_words):
        pace = "active"
    elif any(w in msg for w in relaxed_words):
        pace = "relaxed"
    if not pace:
        return {}
    # Only apply right after Ariella actually asked about pace, so an
    # unrelated "פעיל"/"רגוע" mention elsewhere in the conversation is never
    # misread as answering a question that was never asked this turn.
    prior_assistant = ""
    for item in reversed(history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "assistant":
            prior_assistant = str(item.get("content") or "")
            break
    if "קצב" not in prior_assistant:
        return {}
    return {"trip_planning": {"details": {"pace": pace}}}


def _deterministic_car_vehicle_facts(message, history):
    """car.details.vehicle_type/transmission have no deterministic writer
    anywhere else - only the LLM's own JSON extraction ever sets them, and
    when that silently fails to persist a short one-word answer,
    _session_gaps keeps re-flagging the field as missing forever. Seen live:
    the customer answered "משפחתי" to the car-type question, Ariella
    acknowledged it ("בסדר, רכב משפחתי"), then asked a separate transmission
    question, got "אוטומטי" - and the very next turn asked the car-type
    question again from scratch, never having actually saved "משפחתי"."""
    msg = str(message or "").strip()
    if not msg:
        return {}
    prior_assistant = ""
    for item in reversed(history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "assistant":
            prior_assistant = str(item.get("content") or "")
            break

    result = {}

    # Canonical vehicle_type values (system prompt) - check the more
    # specific "משפחתי סטיישן" before the bare "משפחתי" so it isn't
    # shadowed by the shorter match.
    vehicle_values = [
        "משפחתי סטיישן", "מיניוואן 7 מקומות", "מיניוואן", "ג'יפ 4x4", "ג'יפ",
        "SUV", "סטיישן", "משפחתי", "קטן", "יוקרה",
    ]
    no_preference_words = ("אין העדפה", "לא משנה", "כל רכב מתאים", "מה שיש")
    # The exact lead-in phrasing varies ("סוג הרכב", "קטגוריית הרכב", ...),
    # but the menu of category options itself is distinctive - three or more
    # of them appearing together is a reliable signal this was the car-type
    # question, regardless of how the sentence around them was phrased.
    category_menu_words = ("קטן", "משפחתי", "סטיישן", "suv", "ג'יפ", "מיניוואן", "יוקרה")
    asked_vehicle_type = (
        any(p in prior_assistant for p in ("סוג הרכב", "סוג רכב", "קטגוריית הרכב", "קטגוריה של הרכב", "סוג/גודל רכב"))
        or sum(1 for w in category_menu_words if w in prior_assistant.lower()) >= 3
    )
    if asked_vehicle_type:
        if any(w in msg for w in no_preference_words):
            result.setdefault("car", {}).setdefault("details", {})["vehicle_type"] = "אין העדפה"
        else:
            for value in vehicle_values:
                if value.lower() in msg.lower():
                    result.setdefault("car", {}).setdefault("details", {})["vehicle_type"] = value
                    break

    # Transmission is asked as its own binary question ("אוטומטי או ידני?").
    asked_transmission = "אוטומטי" in prior_assistant and "ידני" in prior_assistant
    if asked_transmission:
        if "לא משנה" in msg or "אין העדפה" in msg:
            result.setdefault("car", {}).setdefault("details", {})["transmission"] = "לא משנה"
        elif "אוטומט" in msg:
            result.setdefault("car", {}).setdefault("details", {})["transmission"] = "אוטומטי"
        elif "ידני" in msg:
            result.setdefault("car", {}).setdefault("details", {})["transmission"] = "ידני"

    return result


def _deterministic_lodging_facts(message, history):
    """lodging.details.type/level/rooms have no deterministic writer anywhere
    else - only the LLM's own JSON extraction ever sets them, same gap as
    _deterministic_car_vehicle_facts above. Seen live: the customer answered
    "מלון לפחות 4 כוכבים" to the type question, then "יוקרתי" to the level
    question, then "3 חדרים זוגיים" to the rooms question - and kept getting
    asked the exact same already-answered questions again on every later
    turn, never having actually saved any of the three."""
    msg = str(message or "").strip()
    if not msg:
        return {}
    prior_assistant = ""
    for item in reversed(history or []):
        if isinstance(item, dict) and str(item.get("role") or "").lower() == "assistant":
            prior_assistant = str(item.get("content") or "")
            break

    result = {}
    no_preference_words = ("אין העדפה", "לא משנה", "מה שיש", "לא משנה לי")

    type_values = ["מלון", "דירה", "אפרטמנט", "וילה", "צימר"]
    asked_type = (
        any(p in prior_assistant for p in ("סוג הלינה", "סוג לינה"))
        or ("מלון" in prior_assistant and ("דירה" in prior_assistant or "וילה" in prior_assistant))
    )
    if asked_type:
        if any(w in msg for w in no_preference_words):
            result.setdefault("lodging", {}).setdefault("details", {})["type"] = "אין העדפה"
        else:
            for value in type_values:
                if value in msg:
                    result.setdefault("lodging", {}).setdefault("details", {})["type"] = "דירה" if value == "אפרטמנט" else value
                    break

    # Canonical values match the system prompt's own documented vocabulary
    # for lodging.details.level exactly ("יוקרתי"/"בסיסי"/"בינוני" - see the
    # ליינה rule above) - "בסיסי" was missing here entirely even though it's
    # literally one of the three options Ariella's own questions offer
    # ("יש לך העדפה (יוקרתי, בינוני, בסיסי)?"), so a customer answering with
    # the system's own vocabulary word was never captured.
    level_values = (
        ("יוקרתי", "יוקרתי"), ("יוקרה", "יוקרתי"), ("פאר", "יוקרתי"),
        ("בינוני", "בינוני"), ("בינונית", "בינוני"), ("סטנדרטי", "בינוני"),
        ("בסיסי", "בסיסי"), ("בסיסית", "בסיסי"),
        ("חסכוני", "בסיסי"), ("תקציבי", "בסיסי"), ("כלכלי", "בסיסי"), ("זול", "בסיסי"),
    )
    asked_level = (
        "רמת הנוחות" in prior_assistant
        or ("יוקרתי" in prior_assistant and ("בינונ" in prior_assistant or "חסכונ" in prior_assistant))
    )
    if asked_level:
        if any(w in msg for w in no_preference_words):
            result.setdefault("lodging", {}).setdefault("details", {})["level"] = "אין העדפה"
        else:
            for word, canon in level_values:
                if word in msg:
                    result.setdefault("lodging", {}).setdefault("details", {})["level"] = canon
                    break

    # Rooms is asked as "כמה חדרים" with a one-big-room-or-split framing.
    asked_rooms = any(p in prior_assistant for p in ("כמה חדרים", "חדר אחד גדול", "לחלק לשני חדרים", "חלוקת החדרים"))
    # A direct "is one room enough?" framing ("חדר זוגי אחד מספיק?") gets a
    # plain "כן" answer, which names no number at all - seen live: that
    # left rooms unset even though the customer had just confirmed it.
    asked_single_room_confirm = bool(re.search(r"חדר\s+\S*\s*אחד\s+מספיק", prior_assistant))
    if asked_rooms:
        rooms_match = re.search(r"(\d+)\s*חדר", msg)
        if rooms_match:
            result.setdefault("lodging", {}).setdefault("details", {})["rooms"] = int(rooms_match.group(1))
        elif any(w in msg for w in ("חדר אחד", "חדר גדול אחד")):
            result.setdefault("lodging", {}).setdefault("details", {})["rooms"] = 1
        elif asked_single_room_confirm and _normalize_confirm(msg).lower() in {"כן", "בטח", "מספיק", "נכון", "כן, מספיק"}:
            result.setdefault("lodging", {}).setdefault("details", {})["rooms"] = 1

    # locations is free text, unlike type/level above - no fixed value list
    # to match against, which is exactly why it had no deterministic writer
    # at all before this. Seen live: the customer volunteered a location
    # preference unprompted, in the very first message of the lodging
    # conversation ("קרוב להגיע לאתר סקי ללא רכב") - no "area" question was
    # ever asked (the type/rooms/level question above never asks about
    # area separately), so a cue-gated approach alone would never catch it.
    # The model's own free text correctly kept referencing this preference
    # all the way to its closing summary, but lodging.details.locations
    # itself apparently never got saved, so _required_state_gaps kept
    # silently blocking session_status.lodging from ever legitimately
    # reaching "complete" - invisible until the customer saw the closing
    # message declare the lodging "done" and then nothing actually happened
    # (no save-trip-lodging call, since the client only fires on a genuine
    # "complete" status in the returned trip_update).
    asked_area = any(p in prior_assistant for p in ("באיזה אזור", "איפה נוח", "מיקום", "אזור"))
    location_cues = ("קרוב ל", "ליד ה", "ליד ל", "במרחק הליכה", "קרוב לאתר", "קרוב למרכז", "לא רחוק מ", "באזור ה", "בלב ")
    if asked_area or any(c in msg for c in location_cues):
        result.setdefault("lodging", {}).setdefault("details", {})["locations"] = msg

    return result


def _protect_lodging_details_from_loss(previous, updated):
    """type/level/budget/rooms/locations keep vanishing once already
    answered - the same loss pattern seen with car.details (see
    _protect_car_details_from_loss). Force-restore them from the pre-turn
    state if the post-merge state lost them."""
    old_details = (previous.get("lodging") or {}).get("details") if isinstance(previous.get("lodging"), dict) else None
    if not isinstance(old_details, dict):
        return updated
    new_lodging = updated.get("lodging") if isinstance(updated.get("lodging"), dict) else {}
    new_details = new_lodging.get("details") if isinstance(new_lodging.get("details"), dict) else {}
    restored = dict(new_details)
    changed = False
    for field in ("type", "rooms", "bedrooms", "level", "budget", "locations", "areas"):
        if old_details.get(field) and not restored.get(field):
            restored[field] = old_details[field]
            changed = True
    if changed:
        updated = dict(updated)
        updated["lodging"] = dict(new_lodging, details=restored)
    return updated


def _deterministic_traveler_facts(message, existing=None):
    """Capture common Hebrew traveler phrases so semantic facts never depend on LLM luck.

    existing is the travelers dict already in state. A passing mention later
    in the conversation ("משהו שמתאים לילדה", "הילד בן 9 אוהב ים") must not
    overwrite what the customer already stated in full - seen live, the
    traveler composition kept shifting mid-conversation."""
    import re
    existing = existing if isinstance(existing, dict) else {}
    msg = str(message or "").strip().lower()
    facts = {}
    # "partner" (בן/בת זוג) is an adult, never a child.
    msg_no_partner = re.sub(r"(?:בן|בת)\s+(?:ה)?זוג\w*", " ", msg)
    # "זוג" as its own word - not "זוגי"/"זוגית" (a double room/bed) and not
    # "2 זוגות" (four adults). Any first-person-possessive mention of a
    # spouse/partner ("בעלי", "אשתי", "בן/בת הזוג שלי") implies the speaker
    # plus that spouse are two adults, regardless of where in the sentence
    # it appears or what exact words surround it - a fixed list of whole-
    # phrase word orders ("אני ובעלי") doesn't generalize to every natural
    # phrasing a customer actually uses. Seen live: "חופשה משפחתית עם בעלי
    # ובת 17 שלי" matched none of the listed phrases (it says "עם בעלי", not
    # "אני ובעלי"), so adults was silently never set, and the gap re-asked
    # for travelers again later in the conversation as if nothing had been
    # said at all.
    if re.search(r"(?<![\u05d0-\u05ea])(?:ו|ל|כ|ה)?זוג(?![\u05d0-\u05ea])", msg_no_partner) \
            or re.search(r"בעלי\b|אשתי\b|(?:בן|בת)\s*(?:ה)?זוג(?:י|ה)?\b|(?:ה)?בעל\s+שלי|(?:ה)?אישה\s+שלי", msg):
        facts["adults"] = 2
    m = re.search(r"(\d+)\s*זוגות", msg)
    if m:
        facts["adults"] = int(m.group(1)) * 2

    child_count = None
    singular = False
    if re.search(r"(?:(?<![\u05d0-\u05ea])ו|עם\s+)(?:ה)?(?:ילדה|בת)(?![\u05d0-\u05ea])", msg_no_partner):
        child_count, singular = 1, True
    elif re.search(r"(?:(?<![\u05d0-\u05ea])ו|עם\s+)(?:ה)?(?:ילד|בן)(?![\u05d0-\u05ea])", msg_no_partner):
        child_count, singular = 1, True
    m = re.search(r"(\d+)\s*(?:ילדים|ילדות)", msg)
    if m:
        child_count, singular = int(m.group(1)), False
    if child_count is not None and not (singular and existing.get("children")):
        facts["children"] = child_count

    # "בת"/"בן" must be a standalone word (optionally prefixed ו/ה) - seen
    # live: "חמישי שישי שבת 3 לילות" matched the "בת 3" inside "שבת" and
    # invented a 3-year-old daughter the customer never mentioned.
    # Plural "בני 9 ו-11"/"בנות 9, 11" lists every age after it (seen live:
    # "הילדים בני 9 11" was not captured at all, so the stray 3 survived).
    found = []
    for m in re.finditer(r"(?<![א-ת])(?:ו|ה|וה)?(בת|בן)\s*(\d{1,2})\b", msg):
        found.append((m.start(), int(m.group(2)), "female" if m.group(1) == "בת" else "male"))
    for m in re.finditer(r"(?<![א-ת])(?:ו|ה|וה)?(בני|בנות)\s*((?:\d{1,2}(?:\s*(?:,|ו-?|-)?\s*)){1,8})", msg):
        gender = "female" if m.group(1) == "בנות" else None
        for n in re.findall(r"\d{1,2}", m.group(2)):
            found.append((m.start(), int(n), gender))
    ages = []
    genders = []
    for _pos, age, gender in sorted(found, key=lambda f: f[0]):
        if 0 <= age <= 17:
            ages.append(age)
            genders.append(gender)
    existing_ages = existing.get("child_ages") if isinstance(existing.get("child_ages"), list) else []
    # A partial mention ("הילד בן 9 אוהב ים") must not shrink a full list the
    # customer already gave; only a complete list replaces it.
    if ages and existing_ages and len(ages) < len(existing_ages) and "children" not in facts:
        ages = []
    if ages:
        facts["child_ages"] = ages
        # "בת"/"בן" preceding the age is itself the customer's own gender
        # statement ("ילדה בת 17" = a girl, age 17) - carry it through so the
        # final summary can refer to the child correctly, instead of relying
        # on the model to guess (it doesn't: seen live defaulting a stated
        # "ילדה בת 17" to "נער בן 17" in the summary, since nothing preserved
        # the gender the customer actually gave).
        facts["child_genders"] = genders
        if "children" not in facts:
            facts["children"] = len(ages)

    if re.search(r"2\s*(?:הורים|מבוגרים)", msg):
        facts["adults"] = 2
    return {"travelers": facts} if facts else {}


_SERVICE_KEYWORDS = (
    ("trip_planning", ("מסלול", "מסלולים", "אטרקציות", "אטרקציה", "תכנון טיול")),
    # Plurals too - seen live: "אני רוצה שתחפשי לי גם דירות" wasn't
    # recognized as a lodging request at all.
    ("lodging", ("מלון", "מלונות", "לינה", "לינות", "וילה", "וילות", "דירה", "דירות", "צימר", "צימרים", "אירוח")),
    ("car", ("רכב", "רכבים", "השכרת רכב", "רכב שכור")),
    ("flights", ("טיסה", "טיסות", "לטוס", "טיסת")),
)
_REQUEST_CUES = (
    "גם", "רוצה", "רוצים", "נרצה", "צריך", "צריכה", "צריכים", "תבני", "תבנה", "תכנני",
    "תחפשי", "תחפש", "תמצאי", "תסדרי", "תזמיני", "אפשר", "בואי", "נעבור", "לעבור",
    "מעוניין", "מעוניינת", "מעוניינים", "תעזרי", "נמשיך", "להמשיך", "נתקדם", "ועכשיו", "עכשיו",
    "לשנות", "לחזור", "נחזור", "תחזרי", "לתקן", "לעדכן", "תשני", "תעדכני",
    # Seen live: "אין צורך ברכב אבל כן תמליצי לי על מקום לינה..." - the
    # customer declined the service just asked about and asked for a
    # DIFFERENT one in the same breath, using "תמליצי" (recommend), which
    # named no cue here, so the lodging request went undetected entirely
    # and the turn just closed out ("מעבירה אותך לתוצאות") with no lodging
    # search ever triggered.
    "תמליצי", "תמליץ", "תמליצו", "מומלץ", "תציעי", "תציע", "תציעו",
)


_STRONG_REQUEST_CUES = (
    "גם", "תבני", "תבנה", "תחפשי", "תחפש", "תמצאי", "תסדרי", "תזמיני", "בואי", "נעבור",
    "לעבור", "נמשיך", "להמשיך", "נתקדם", "ועכשיו", "עכשיו",
    # Going back to change an earlier session is always allowed (e.g.
    # "רוצה לשנות את הטיסה" from inside the route).
    "לשנות", "לחזור", "נחזור", "תחזרי", "לתקן", "לעדכן", "תשני", "תעדכני",
    "תמליצי", "תמליץ", "תמליצו", "מומלץ", "תציעי", "תציע", "תציעו",
)


def _classify_service_request(message, history):
    """Meaning-based fallback for _explicit_service_request (per product
    owner: understand the request by meaning, not a word list - "גם דירות",
    "איפה נישן?", "נצטרך גם איך להתנייד" all ask for a service). Used where
    a missed request matters most: a new message after a vacation was
    closed, which decides whether to attach the service to that vacation.
    Returns lodging/car/trip_planning/flights or None."""
    key = os.getenv("ANTHROPIC_API_KEY", "").strip()
    if not key or not str(message or "").strip():
        return None
    model = os.getenv("ARIELLA_MODEL", "claude-sonnet-5").strip()
    last_assistant = next(
        (str(x.get("content") or "") for x in reversed(history or [])
         if isinstance(x, dict) and x.get("role") == "assistant"), "")
    prompt = (
        "את מסווגת הודעת לקוח בשיחה עם סוכנת נסיעות. האם הלקוח מבקש עכשיו להוסיף/לחפש אחד מהשירותים: "
        "lodging (לינה: מלון, דירה, וילה, צימר וכו'), car (השכרת רכב), trip_planning (מסלול/אטרקציות), flights (טיסות)? "
        "הביני לפי משמעות, בכל ניסוח, סלנג ושגיאות כתיב. אזכור שירות בלי בקשה (למשל 'בלי רכב', 'נסענו ברכב') אינו בקשה. "
        'החזירי JSON בלבד: {"service": "lodging"|"car"|"trip_planning"|"flights"|null}'
    )
    try:
        raw = _post_claude(key, model, prompt, "", [], "הודעת הסוכנת הקודמת: " + last_assistant[-600:] + "\nהודעת הלקוח: " + str(message), 40, include_history=False, source="classifier")
        raw = raw.strip()
        service = json.loads(raw[raw.index("{"):raw.rindex("}") + 1]).get("service")
    except Exception:
        return None
    return service if service in ("lodging", "car", "trip_planning", "flights") else None


def _explicit_service_request(message, state):
    """Which of the four services the customer is explicitly asking to move
    to, if any. Seen live, repeatedly: this used to be a bare substring check,
    so any answer that merely MENTIONED a service word switched the whole
    conversation - "no long drives by car" (ברכב) mid-route opened a car
    rental session marked as explicitly requested, "2 nights of lodging in
    one place" opened lodging, "the day after the flight" jumped to flights -
    and the route being built was abandoned mid-way (the "stuck" planning
    conversations). A mention now counts only as the opening request (no
    session in progress yet) or when phrased as a request ("גם רכב", "תחפשי
    לי מלון", "בואי נעבור לטיסות"), never after a negation, and never as a
    descriptive ב/מ-prefixed word ("ברכב", "במלון", "במסלול")."""
    import re
    state = state if isinstance(state, dict) else {}
    text = str(message or "").strip().lower()
    if not text:
        return None
    statuses = state.get("session_status") if isinstance(state.get("session_status"), dict) else {}
    in_progress = bool(state.get("active_session")) or any(v == "active" for v in statuses.values())
    words = re.findall(r"[א-תa-z\"'׳״]+", text)
    prefix = r"(?:ו|ה|ל|ש|וה|ול|וש|שה|לה)?"
    for service, keywords in _SERVICE_KEYWORDS:
        for kw in keywords:
            kw_words = kw.split()
            n = len(kw_words)
            first_re = re.compile(r"^" + prefix + re.escape(kw_words[0]) + r"$")
            for i in range(len(words) - n + 1):
                if not first_re.match(words[i]) or words[i + 1:i + n] != kw_words[1:]:
                    continue
                before = words[max(0, i - 4):i]
                # Negation right before the keyword ("בלי רכב", "לא צריך
                # רכב") - only the adjacent words, so an earlier, unrelated
                # "בלי" in the same sentence doesn't cancel a real request.
                if any(w in ("לא", "בלי", "אין", "ללא") for w in words[max(0, i - 2):i]):
                    continue
                if not in_progress:
                    return service
                # "3 לילות באותו מקום" while building a route is a route
                # constraint, not a request to search lodging.
                if service == "lodging" and state.get("active_session") == "trip_planning" and re.search(r"לילה|לילות", text):
                    continue
                cues = _REQUEST_CUES
                if state.get("active_session") == "trip_planning":
                    # A route is a long, multi-turn build. Answers inside it
                    # ("רוצה לטוס ב-16.5", "רוצה טיסה ישירה") are details,
                    # not a request to abandon it - leaving takes a clear
                    # switch ("בואי נעבור לטיסות", "תחפשי לי גם מלון").
                    cues = _STRONG_REQUEST_CUES
                if any(w in cues or (w.startswith("ו") and w[1:] in cues) for w in before):
                    return service
                if words[i].startswith("ו") and words[i][1:].startswith(kw_words[0]) and i == 0:
                    return service
    return None


def _is_itinerary_acceptance(message):
    """Did the customer accept the itinerary just proposed? The exact-phrase
    set this replaced missed ordinary approvals ("מאשרת את המסלול", "נשמע
    מושלם, תודה", "אהבתי!") so the planning session never closed and Ariella
    kept re-proposing or re-asking the route. Short positive replies count;
    anything asking for a change or asking a question does not."""
    import re
    msg = _normalize_confirm(message).lower()
    if not msg or len(msg) > 80 or "?" in str(message or ""):
        return False
    change_markers = (
        "אבל", "לשנות", "תשני", "שני את", "במקום", "בלי", "תוסיפי", "להוסיף", "תורידי",
        "להוריד", "פחות", "יותר", "אפשר", "מה עם", "למה", "לא מתאים", "לא טוב", "לא אוהב",
    )
    if any(m in msg for m in change_markers):
        return False
    # Seen live: "לא. זה נשמע מצוין" ("no [nothing to change], it sounds
    # great") is a common acceptance pattern - a standalone "לא" clause
    # followed by a clearly positive one - but the blanket "any לא anywhere
    # = reject" rule below caught it regardless, so the itinerary never
    # closed and kept getting re-presented/re-asked. A "לא" that negates an
    # actual following word ("לא מתאים", "לא אהבתי") is still a real
    # rejection and stays blocked; only a "לא" standing on its own (right
    # before a sentence break or the end of the message) is exempted.
    if re.search(r"(?<![\u05d0-\u05ea])לא(?![\u05d0-\u05ea])(?!\s*[.,!?]|\s*$)", msg):
        return False
    positives = (
        "כן", "מאשר", "מאשרת", "מתאים", "מתאימה", "מעולה", "מצוין", "מצויין", "אחלה", "נשמע טוב",
        "נשמע מעולה", "נשמע אחלה", "נשמע סבבה", "נשמע מושלם", "סבבה", "אהבתי", "מושלם", "יופי",
        "בדיוק", "נהדר", "מדהים", "סגור", "סגרנו", "יאללה", "טוב מאוד", "בסדר גמור", "perfect",
    )
    return any(re.search(r"(?<![\u05d0-\u05ea])" + re.escape(p) + r"(?![\u05d0-\u05ea])", msg) for p in positives)


_POST_FLIGHT_LABELS = {"lodging": "לינה", "car": "השכרת רכב", "trip_planning": "תכנון מסלול ואטרקציות"}


def _post_flight_offer_answer(message, state, key=None, model=None, history=None):
    """The customer's answer to "the flights are being scanned - want help
    with lodging, car or route too?" (asked right after flight approval).
    Returns {service: wanted_bool} for each offered service the answer
    settles, or {} when it doesn't settle anything (Ariella then continues
    the conversation normally).

    Per product owner: customers phrase this in endless ways ("יאללה בואי
    נסגור גם מלון", "אני אסתדר לבד עם השאר", "לא בטוחה, אולי מסלול"), so
    the meaning is understood by the model. Only very short, unambiguous
    replies are read directly, without a model call."""
    import re
    state = state if isinstance(state, dict) else {}
    offered = [s for s in (state.get("post_flight_offer") or []) if s in _POST_FLIGHT_LABELS]
    if not offered:
        return {}
    msg = _normalize_confirm(message).lower()
    if not msg:
        return {}
    if msg in {"לא", "לא עכשיו", "לא תודה", "לא צריך", "לא צריכה", "לא צריכים", "זהו", "זה הכל", "זה הכול", "סיימנו", "אין צורך"}:
        return {s: False for s in offered}
    if msg in {"כן", "בטח", "בהחלט", "כולם", "הכל", "הכול", "את הכל", "את הכול", "כן הכל", "כן הכול", "כן בבקשה", "כן, בבקשה"}:
        return {s: True for s in offered}
    # "תעבירי"/"תעביר אותי" - the customer is asking to actually be taken to
    # the flight results now, exactly the alternative Ariella herself offered
    # alongside the lodging/car/route question ("אם לא עכשיו, אעביר אותך
    # לתוצאות"). Seen live: the model-only path below has no way to express
    # "navigate the customer" (it only ever returns true/false per service),
    # so this got answered with chat text claiming a transfer that never
    # actually happened - the client never got a signal to navigate anywhere.
    # Treat it like "not now" for the offered extra services, plus the
    # sentinel key below so the caller can set the real navigation flag.
    if msg in {"תעבירי", "תעביר", "תעביר אותי", "תעבירי אותי", "קחי אותי לתוצאות", "העבירי אותי", "לתוצאות", "תעבירי לתוצאות"}:
        return {"_transfer_to_results": True, **{s: False for s in offered}}
    if not key:
        return {}
    offered_text = ", ".join(f"{s} ({_POST_FLIGHT_LABELS[s]})" for s in offered)
    prompt = (
        "את מסווגת תשובת לקוח. אריאלה שאלה את הלקוח, אחרי שאישר את הטיסה, אם הוא רוצה עזרה גם באחד או יותר מהשירותים: "
        + offered_text + ".\n"
        "הביני את משמעות התשובה בכל ניסוח, כולל סלנג ושגיאות כתיב. לכל שירות החזירי true אם הלקוח רוצה אותו עכשיו, "
        "false אם הוא לא רוצה אותו עכשיו (כולל 'אחר כך', 'אסתדר לבד', 'זהו'), או null אם אי אפשר לדעת מהתשובה. "
        "'כן' כללי בלי פירוט = true לכולם. סירוב כללי בלי פירוט = false לכולם. "
        "אם הלקוח מתלבט או שואל שאלה בלי להחליט - null. "
        "החזירי JSON בלבד, בפורמט {\"lodging\": true|false|null, ...} רק עם המפתחות: " + ", ".join(offered) + "."
    )
    try:
        raw = _post_claude(key, model, prompt, "", [], "תשובת הלקוח: " + str(message or ""), 60, include_history=False, source="classifier")
        raw = raw.strip()
        if raw.startswith("```"):
            raw = raw.strip("`").replace("json", "", 1).strip()
        data = json.loads(raw[raw.index("{"):raw.rindex("}") + 1])
    except Exception:
        return {}
    # Per product owner: a service the customer didn't address at all is
    # never inferred as declined, even when she clearly said yes to a
    # different offered service in the same reply ("כן תחפשי לי דירות..."
    # says nothing about the car). It stays pending and gets asked about
    # on its own once the service she did address reaches completion -
    # same as the symmetric case (car answered first, lodging asked later).
    # Only a service the model actually returned true/false for is settled
    # here; anything left null/missing is simply not touched.
    return {s: data.get(s) for s in offered if isinstance(data.get(s), bool)}


_REOPEN_LABELS = {"lodging": "לינה", "car": "רכב שכור", "trip_planning": "מסלול ואטרקציות"}
_REOPEN_FIRST_QUESTION = {
    "lodging": "איזה סוג לינה מתאים לכם (מלון, דירה או וילה), כמה חדרים, ובאיזו רמה?",
    "car": "איזה רכב מתאים לכם, ואיפה נוח לאסוף ולהחזיר אותו?",
    "trip_planning": "ספרי לי מה אתם אוהבים לעשות בחופשה, ובאיזה קצב - רגוע או פעיל?",
}
_PENDING_KEYS = (
    "ready_for_summary", "search_intent", "missing_required", "next_session", "reset_pending",
    "reset_change_request", "reset_scope", "post_flight_offer", "reopen_trip_pending",
    "destination_change_pending", "new_trip_pending", "profile",
)


def _he_date_window(text):
    import re
    return re.sub(r"(\d{4})-(\d{2})-(\d{2})", lambda m: f"{int(m.group(3))}.{int(m.group(2))}.{m.group(1)}", str(text or ""))


def _service_missing_on_trip(answers, service):
    answers = answers if isinstance(answers, dict) else {}
    if service == "lodging":
        return not (answers.get("_lodging_search_finished") or answers.get("lodging_type"))
    if service == "car":
        return not (answers.get("_car_search_finished") or answers.get("car_vehicle_type") or answers.get("car_pickup"))
    if service == "trip_planning":
        return not answers.get("_approved_itinerary") and answers.get("vacation_type") not in ("business", "ski")
    return False


def _known_place_names():
    names = set(d["name"] for d in DESTINATIONS)
    for airport in _load_airports():
        for key in ("city_he", "country_he"):
            value = str(airport.get(key) or "").strip()
            if value:
                names.add(value)
    return names


def _mentioned_places(message):
    """Known city/country names the customer mentioned (whole words, with
    the usual ל/ב/מ/ו prefixes)."""
    import re
    msg = str(message or "")
    found = []
    for name in _known_place_names():
        if len(name) >= 2 and re.search(r"(?<![\u05d0-\u05ea])(?:ל|ב|מ|ו|ול|וב)?" + re.escape(name) + r"(?![\u05d0-\u05ea])", msg):
            found.append(name)
    return found


def _place_countries(names):
    """Hebrew country for each known city/country name (a country maps to itself)."""
    countries = set()
    for airport in _load_airports():
        city, country = str(airport.get("city_he") or ""), str(airport.get("country_he") or "")
        for n in names:
            n = str(n or "").strip()
            if n and (n == city or n == country):
                countries.add(country)
    return countries


def _place_codes(names):
    """Airport codes of the mentioned cities/countries (catalog-based)."""
    names = {str(n or "").strip() for n in names if str(n or "").strip()}
    return {
        str(a.get("code") or "").upper() for a in _load_airports()
        if str(a.get("city_he") or "") in names or str(a.get("country_he") or "") in names
    }


def _reopenable_trips(member_id, service, message, limit=3):
    """The customer's upcoming active vacations that don't have `service`
    yet - candidates for "add lodging/car/route to an existing vacation".
    If the message names a place, only vacations to that place count."""
    try:
        conn = sqlite3.connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT id, request_name, travel_window, answers_json FROM trip_requests "
            "WHERE member_id=? AND status='active' ORDER BY id DESC LIMIT 20",
            (member_id,),
        ).fetchall()
        conn.close()
    except Exception:
        return []
    mentioned = _mentioned_places(message)
    mentioned_countries = _place_countries(mentioned)
    today = date.today().isoformat()
    trips = []
    for row in rows:
        try:
            answers = json.loads(row["answers_json"] or "{}")
        except Exception:
            continue
        # Only vacations still ahead of today (per product owner: never ask
        # about a vacation whose dates already passed). Exact dates: the
        # departure must be after today; month-only requests: the month
        # must not be over yet.
        dep = str(answers.get("departure_date") or "")[:10]
        month = str(answers.get("travel_month") or answers.get("outbound_month") or "")[:7]
        if dep and dep <= today:
            continue
        if not dep and month and month < today[:7]:
            continue
        if not dep and not month:
            continue
        if not _service_missing_on_trip(answers, service):
            continue
        name = str(row["request_name"] or "").strip()
        if mentioned:
            trip_places = [p.strip() for p in name.split(" • ") if p.strip()]
            # Not only an exact title match: a vacation titled "ניו יורק (JFK)"
            # or "ניו יורק, ארה\"ב" (or with only airport codes saved) must
            # still be found when the customer says "בניו יורק" - otherwise
            # the request is treated as a brand-new trip.
            trip_codes = {c.strip().upper() for c in str(answers.get("destinations") or "").split(",") if c.strip()}
            if not (
                set(trip_places) & set(mentioned)
                or any(m in name for m in mentioned)
                or _place_countries(trip_places) & mentioned_countries
                or trip_codes & _place_codes(mentioned)
            ):
                continue
        trips.append({"id": int(row["id"]), "name": name or "החופשה", "window": _he_date_window(row["travel_window"]), "answers": answers})
        if len(trips) >= limit:
            break
    return trips


def _upcoming_vacations(member_id, limit=3):
    """The customer's upcoming active vacations and which of lodging/car/
    route each still lacks - so a customer coming back after "not now"
    is offered to continue that vacation instead of being greeted as if
    starting from scratch (seen live with a New York trip)."""
    seen, result = set(), []
    for service in ("lodging", "car", "trip_planning"):
        for trip in _reopenable_trips(member_id, service, "", limit=20):
            if trip["id"] in seen:
                continue
            seen.add(trip["id"])
            answers = trip["answers"]
            missing = [
                _REOPEN_LABELS[s] for s in ("lodging", "car", "trip_planning")
                if _service_missing_on_trip(answers, s)
            ]
            ages = answers.get("age_groups") or []
            travelers = ""
            if answers.get("adults"):
                travelers = f"{answers.get('adults')} מבוגרים"
                if answers.get("children"):
                    travelers += f", {answers.get('children')} ילדים" + (f" (גילאים {', '.join(str(a) for a in ages)})" if ages else "")
            result.append({"name": trip["name"], "window": trip["window"], "travelers": travelers, "missing": missing})
    return result[:limit]


def _state_from_trip(trip, service):
    """Rebuild the conversation state of an already-approved vacation so a
    customer coming back to add `service` continues from what was agreed."""
    answers = trip.get("answers") or {}
    stored = answers.get("_ariella_trip_state")
    if isinstance(stored, dict) and stored:
        state = json.loads(json.dumps(stored))
    else:
        codes = [c for c in str(answers.get("destinations") or "").split(",") if c]
        places = [p.strip() for p in str(trip.get("name") or "").split(" • ") if p.strip() and p.strip() != "החופשה"]
        origins = answers.get("origin_airports") or []
        state = {
            "trip_type": answers.get("vacation_type") or "standard",
            "destination": {"places": places, "mode": "specific", "status": "known"},
            "destination_airports": codes,
            "departure_airport": origins[0] if origins else None,
            "dates": {"departure": answers.get("departure_date"), "return": answers.get("return_date"), "needs_confirmation": False},
            "travelers": {"adults": answers.get("adults"), "children": answers.get("children"), "child_ages": answers.get("age_groups") or []},
        }
    for key in _PENDING_KEYS:
        state.pop(key, None)
    statuses = dict(state.get("session_status") or answers.get("_session_status") or {})
    decisions = dict(state.get("service_decisions") or {})
    statuses["flights"] = "complete"
    for s in ("lodging", "car", "trip_planning"):
        if s == service:
            statuses[s] = "active"
        elif not _service_missing_on_trip(answers, s):
            statuses[s] = "complete"
        elif statuses.get(s) != "complete":
            # Not asked for now: stays closed so finishing `service` closes
            # the visit; the customer can still ask for it explicitly. The
            # decision must be closed too - a stale {"wanted": True} kept in
            # the stored pre-approval state (e.g. "גם רכב" said mid-flights)
            # otherwise makes _sessionize_state re-activate it, and Ariella
            # asks about a car the customer never came back for (and keeps
            # asking on every return visit, even after a "no").
            statuses[s] = "declined"
            decisions[s] = {"wanted": False, "source": "reopened_trip_not_requested"}
    decisions[service] = {"wanted": True, "source": "reopened_trip"}
    services = set(state.get("requested_services") or []) | {"flights", service}
    state.update({
        "session_status": statuses, "service_decisions": decisions, "requested_services": sorted(services),
        "active_session": service, "post_flight_continuation": True, "search_confirmed": True,
        "reopened_trip_id": trip["id"],
    })
    return state


def _reopen_question(service, trips):
    """Per product owner: a customer may well be tracking several vacations
    at once, not just the one most recently touched. With exactly one or
    two candidates, listing them is still a short, scannable question. With
    more than two, enumerating all of them floods the message (a customer
    with ten parallel vacations should never see all ten spelled out) - ask
    an open question instead and let the customer answer freely (by
    destination/date); _pick_reopen_option already matches a free-text
    answer against the full candidate list regardless of how many there
    are."""
    label = _REOPEN_LABELS[service]
    if len(trips) == 1:
        t = trips[0]
        return f"להוסיף {label} לחופשה ל{t['name']} ({t['window']})? (כן = לחופשה הזו, לא = חופשה חדשה)"
    if len(trips) == 2:
        lines = "\n".join(f"{i + 1}. {t['name']} ({t['window']})" for i, t in enumerate(trips))
        return f"לאיזו חופשה להוסיף {label}?\n{lines}\nאו שזו חופשה חדשה?"
    return f"יש לך כמה חופשות פעילות במקביל - לאיזו מהן להוסיף {label}? אפשר לציין יעד או תאריך, או להגיד שזו חופשה חדשה."


def _pick_reopen_option(message, options, key=None, model=None, history=None):
    """Which offered vacation the customer chose: an index, "new", or None."""
    import re
    msg = _normalize_confirm(message).lower()
    if re.search(r"(?<![\u05d0-\u05ea])(?:חדשה|חדש|אחרת)(?![\u05d0-\u05ea])", msg):
        return "new"
    if len(options) == 1:
        if msg in {"כן", "כן בבקשה", "נכון", "בדיוק", "לזו", "לחופשה הזו", "לאותה חופשה", "בטח", "יאללה"}:
            return 0
        if msg in {"לא", "לא תודה"}:
            return "new"
    else:
        m = re.fullmatch(r"(?:ל)?(\d)", msg)
        if m and 1 <= int(m.group(1)) <= len(options):
            return int(m.group(1)) - 1
        ordinals = {"הראשונה": 0, "ראשונה": 0, "הראשון": 0, "השנייה": 1, "השניה": 1, "שנייה": 1, "השני": 1, "השלישית": 2, "שלישית": 2}
        for word, idx in ordinals.items():
            if word in msg and idx < len(options):
                return idx
    def _name_variants(name):
        # An option's name is stored however the vacation was originally
        # titled (often the English city name, e.g. "New York") while the
        # customer naturally replies in Hebrew ("ניו יורק") - check the
        # airport catalog for the matching city_he so either language
        # resolves the same option, not just an exact-string match.
        variants = {name.strip().lower()}
        try:
            for airport in _load_airports():
                city_en = str(airport.get("city_en") or "").strip()
                city_he = str(airport.get("city_he") or "").strip()
                if city_en and city_en.lower() == name.strip().lower() and city_he:
                    variants.add(city_he.lower())
        except Exception:
            pass
        return variants

    hits = [
        i for i, o in enumerate(options)
        if any(
            part.strip() and any(v in msg for v in _name_variants(part))
            for part in str(o.get("name") or "").split(" • ")
        )
    ]
    if len(hits) == 1:
        return hits[0]
    if len(options) == 1 and key:
        intent = _interpret_pending_choice(key, model, history, message, "new_vacation")
        if intent == "keep":
            return 0
        if intent == "new":
            return "new"
    return None


def _member_profile(member_id):
    """Authoritative name/gender for personalizing the conversation. Always
    read fresh from the registration data - never trust a client-supplied
    profile, which can be stale, spoofed, or (as the client widget did)
    silently defaulted to a wrong gender."""
    try:
        conn = sqlite3.connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        row = conn.execute("SELECT full_name, gender, country, preferred_airports FROM members WHERE id=?", (member_id,)).fetchone()
        conn.close()
    except Exception:
        return {"first_name": "", "gender": None}
    if not row:
        return {"first_name": "", "gender": None}
    full_name = str(row["full_name"] or "").strip()
    first_name = full_name.split()[0] if full_name else ""
    gender = str(row["gender"] or "").strip().lower() or None
    try:
        home_airports = [str(c).strip().upper() for c in json.loads(row["preferred_airports"] or "[]") if str(c).strip()]
    except Exception:
        home_airports = []
    return {
        "first_name": first_name, "gender": gender,
        # Chosen at registration (and editable in account details) - the
        # departure default, so the site works the same from any country.
        "home_airports": home_airports,
        "country": str(row["country"] or "").strip().upper(),
    }


def _remember_turn_reset_trip(member_id, history, message, reply, fresh_trip_state):
    """Used on a new-vacation boundary: this turn still joins the one
    continuous conversation history, but the structured vacation data
    starts over. The conversation itself is never erased."""
    try:
        existing = load_ariella_conversation(member_id)
        full_history = list((existing or {}).get('history') or history) + [
            {'role': 'user', 'content': message},
            {'role': 'assistant', 'content': reply},
        ]
        save_ariella_conversation(member_id, full_history[-80:], fresh_trip_state)
    except Exception:
        logging.exception("Failed to persist Ariella conversation reset for member %s", member_id)


# Per product owner: a customer who goes quiet mid-planning and comes back
# much later should never have the old, unfinished (or already-closed)
# vacation's fields silently bleed into whatever they say next - seen live
# as destination/date/baggage facts from a previous conversation leaking
# into an unrelated new one. Requiring the customer to say the magic words
# "חופשה חדשה" (handled separately above) isn't realistic; most customers
# just start talking about the new thing. A stale gap is itself the signal.
_STALE_SESSION_MINUTES = 60


def _has_vacation_progress(trip_state):
    """True when trip_state holds real in-progress vacation facts worth
    clearing - a blank/fresh state has nothing to reset."""
    if not isinstance(trip_state, dict):
        return False
    destination = trip_state.get("destination")
    if isinstance(destination, dict) and destination.get("places"):
        return True
    for key in ("dates", "flight", "lodging", "car", "trip_planning", "ski"):
        value = trip_state.get(key)
        if isinstance(value, dict) and any(v not in (None, "", [], {}) for v in value.values()):
            return True
    travelers = trip_state.get("travelers")
    if isinstance(travelers, dict) and (travelers.get("composition") or travelers.get("adults")):
        return True
    if trip_state.get("trip_type"):
        return True
    statuses = trip_state.get("session_status")
    if isinstance(statuses, dict) and any(v not in (None, "pending") for v in statuses.values()):
        return True
    return False


def _reset_stale_trip_state(trip_state, message):
    """Same clean-slate shape used for an explicit 'new vacation' request
    (see new_vacation_language above), but triggered by elapsed time instead
    of the customer having to say so. Only facts in the CURRENT message seed
    the fresh state - never the old, now-stale history."""
    fresh = {
        'session_status': {'flights': 'pending', 'lodging': 'pending', 'car': 'pending', 'trip_planning': 'pending'},
        'active_session': None,
    }
    seed = _deterministic_destination_facts([], message, {})
    if seed:
        fresh = _merge_trip_state(fresh, seed)
    return fresh


def _minutes_since(updated_at):
    if not updated_at:
        return None
    try:
        then = datetime.fromisoformat(str(updated_at))
    except ValueError:
        return None
    if then.tzinfo is None:
        then = then.replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - then).total_seconds() / 60.0


@ariella_chat_clean.get('/api/ariella/resume')
def chat_resume():
    """Let a page load hydrate the member's own in-progress conversation from
    the server, so it's available on any device/browser they log into, not
    only the one it was saved from."""
    if not session.get('member_id'):
        return jsonify({'status': 'error', 'message': 'נדרשת התחברות כדי לשוחח עם אריאלה.'}), 401
    saved = load_ariella_conversation(session['member_id'])
    if not saved:
        return jsonify({'status': 'success', 'history': [], 'trip_state': {}})
    return jsonify({'status': 'success', 'history': saved.get('history') or [], 'trip_state': saved.get('trip_state') or {}})


@ariella_chat_clean.post('/api/ariella/reset-conversation')
def chat_reset_conversation():
    """A full, permanent reset of the member's own saved conversation - not
    the ordinary "new vacation" reset (which only clears structured trip
    facts and keeps history growing), but a genuine start-from-nothing wipe
    of the visible chat itself, on explicit customer request only."""
    if not session.get('member_id'):
        return jsonify({'status': 'error', 'message': 'נדרשת התחברות כדי לשוחח עם אריאלה.'}), 401
    clear_ariella_conversation(session['member_id'])
    return jsonify({'status': 'success'})


@ariella_chat_clean.post('/api/ariella/chat-clean')
def chat_clean():
    if not session.get('member_id'):
        return jsonify({'status': 'error', 'message': 'נדרשת התחברות כדי לשוחח עם אריאלה.', 'engine_version': ENGINE_VERSION}), 401

    set_ai_usage_context(
        member_id=session.get('member_id'),
        is_test=str(get_setting('qa_test_mode', '0') or '0') == '1',
        # Task 006a: set only by whatsapp_bridge.ariella_turn (via a session
        # flag, before it calls this exact route through the Flask test
        # client) - an ordinary website call never sets this, so its own
        # ai_usage rows are unaffected.
        channel=('whatsapp' if session.get('ariella_channel') == 'whatsapp' else None),
    )
    body = request.get_json(silent=True) or {}
    message = str(body.get('message') or '').strip()
    if not message:
        return jsonify({'status': 'error', 'message': 'message is required', 'engine_version': ENGINE_VERSION}), 400

    history = body.get('history') if isinstance(body.get('history'), list) else []
    trip_state = body.get('trip_state') if isinstance(body.get('trip_state'), dict) else {}
    # Always consult the server-side record, even when the browser already
    # sent its own trip_state - it's the only place that carries a reliable,
    # server-controlled "when did we last actually talk" timestamp (the
    # client's own copy has none), needed below for the stale-session reset.
    saved_conversation = load_ariella_conversation(session['member_id'])
    # The browser's local cache is per-device and empties on logout/switching
    # devices. When it has no progress at all, resume the member's own
    # server-saved conversation instead of starting over.
    if not trip_state:
        if saved_conversation and (saved_conversation.get('trip_state') or saved_conversation.get('history')):
            history = saved_conversation.get('history') or history
            trip_state = saved_conversation.get('trip_state') or trip_state
    # Per product owner: a long silent gap is itself a boundary, exactly like
    # an explicit "new vacation" request - clear unfinished/stale vacation
    # fields so they can never leak into whatever the customer says next.
    # upcoming_vacations (loaded further below from the DB, independent of
    # this reset) still lets Ariella naturally offer to continue a real
    # saved trip when one exists.
    # The full transcript is still what gets persisted below (never erase
    # chat history), but every deterministic fact-scan and the model's own
    # conversational context for THIS turn use `history`, which a stale
    # reset below truncates - otherwise destination/date/etc. facts that
    # were just cleared from trip_state would simply be re-mined straight
    # back out of the old messages (seen live, in testing this exact fix).
    history_before_gap = history
    _idle_minutes = _minutes_since((saved_conversation or {}).get('updated_at'))
    if _idle_minutes is not None and _idle_minutes >= _STALE_SESSION_MINUTES and _has_vacation_progress(trip_state):
        trip_state = _reset_stale_trip_state(trip_state, message)
        history = []
    key = os.getenv('ANTHROPIC_API_KEY', '').strip()
    model = os.getenv('ARIELLA_MODEL', 'claude-sonnet-5').strip()

    # A customer question about a DIFFERENT/past vacation ("את זוכרת את
    # הטיסה לניו יורק?") must be answered from their real trip history, not
    # left for the model to (truthfully) say it has no record of, or worse,
    # guess at. This is a deterministic lookup - exactly one correct answer -
    # so it short-circuits before any LLM call, and never touches the
    # current conversation's own trip_state.
    past_trip_triggers = (
        "זוכרת את", "את זוכרת", "זוכר את", "אתה זוכר",
        "שסגרנו", "שכבר תכננו", "שכבר סגרנו", "שכבר הזמנו",
        "מהטיול ש", "מהחופשה ש", "לטיול הישן", "לחופשה הישנה",
    )
    if any(p in message for p in past_trip_triggers):
        import re as _re

        def _he_window(trip):
            # Match the day.month.year layout used everywhere else customer-
            # facing (confirmed against the flight-leg date display) - never
            # the raw ISO year-first storage format.
            return _re.sub(
                r"(\d{4})-(\d{2})-(\d{2})",
                lambda m: f"{m.group(3)}.{m.group(2)}.{m.group(1)}",
                str(trip.get('travel_window') or ''),
            )

        member_id = session.get('member_id')
        matches = find_member_trip_by_mention(member_id, message) if member_id else []
        if len(matches) == 1:
            trip = matches[0]
            reply = (
                f"כן, זוכרת! {trip['request_name']} ({_he_window(trip)}). "
                "אפשר להמשיך את החופשה הזו ישירות מהכרטיסייה שלך - שם אפשר גם לבקש למצוא לינה או רכב עבורה."
            )
            return jsonify({
                'status': 'success', 'agent': 'Ariella', 'engine_version': ENGINE_VERSION,
                'reply': reply, 'trip_update': trip_state, 'start_flight_search': False,
                'open_existing_trip_id': trip['id'],
            })
        elif len(matches) > 1:
            # Each candidate needs its own date and id shown - two same-named
            # vacations ("קפריסין, קפריסין") are otherwise indistinguishable,
            # leaving the customer no way to say which one they meant.
            listed = "; ".join(
                f"{m['request_name']} ({_he_window(m)}, מספר חופשה {m['id']})"
                for m in matches[:5]
            )
            reply = f"מצאתי כמה חופשות שיכולות להתאים: {listed}. לאיזו מהן התכוונת?"
            return jsonify({
                'status': 'success', 'agent': 'Ariella', 'engine_version': ENGINE_VERSION,
                'reply': reply, 'trip_update': trip_state, 'start_flight_search': False,
            })
        # No match: fall through to the normal model call, which already
        # knows (per its own instructions) to say honestly that it has no
        # record rather than invent one.

    # Coming back to add lodging/car/route to a vacation that was already
    # approved and closed (per product owner): find the customer's upcoming
    # vacations still missing that service and confirm which one - place and
    # dates - before continuing it. Never guess, never offer a past vacation.
    pending_reopen = trip_state.get("reopen_trip_pending") if isinstance(trip_state.get("reopen_trip_pending"), dict) else None
    if pending_reopen:
        options = pending_reopen.get("options") or []
        service = pending_reopen.get("service")
        choice = _pick_reopen_option(message, options, key, model, history)
        member_id = session['member_id']
        if choice == "new" and pending_reopen.get("keep_state"):
            # Offered because an open conversation matched an existing
            # vacation; "no" means keep planning it as a separate trip.
            kept = dict(trip_state)
            kept.pop("reopen_trip_pending", None)
            kept["reopen_offer_declined"] = True
            reply = "בסדר, נמשיך עם זה כחופשה נפרדת."
            return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':reply,'trip_update':kept,'start_flight_search':False})
        if choice == "new":
            # Same "destination stated in the same message" rule as the other
            # new-vacation resets (new_vacation_language above, and the
            # _previous_asked_new_vacation confirm branch below) - seen live:
            # answering "reopen the old vacation or something new?" with
            # "חופשה חדשה לויאטנם" still lost Vietnam entirely here, because
            # this branch never looked at the message for a destination at
            # all, unlike its siblings.
            fresh = {'session_status':{'flights':'pending','lodging':'pending','car':'pending','trip_planning':'pending'},'active_session':None}
            seed = _deterministic_destination_facts([], message, {})
            if seed:
                fresh = _merge_trip_state(fresh, seed)
            places = ((fresh.get('destination') or {}).get('places') or []) if isinstance(fresh.get('destination'), dict) else []
            reply = (f"בסדר, מתחילים חופשה חדשה ל{places[0]}. באיזו תקופה תרצי לטוס?"
                     if places else "בסדר, נתכנן חופשה חדשה. לאן תרצי לטוס ובאיזו תקופה?")
            _remember_turn_reset_trip(member_id, history, message, reply, fresh)
            return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':reply,'trip_update':fresh,'start_flight_search':False,'trip_state_reset':True})
        if isinstance(choice, int) and service in _REOPEN_LABELS:
            chosen = next((t for t in _reopenable_trips(member_id, service, "", limit=20) if t["id"] == options[choice].get("id")), None)
            if chosen:
                reopened = _state_from_trip(chosen, service)
                reopened["profile"] = _member_profile(member_id)
                reply = f"מעולה, ממשיכות עם {_REOPEN_LABELS[service]} לחופשה ל{chosen['name']} ({chosen['window']}). {_REOPEN_FIRST_QUESTION[service]}"
                _remember_turn_reset_trip(member_id, history, message, reply, reopened)
                return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':reply,'trip_update':reopened,'start_flight_search':False,'reopen_trip_id':chosen['id']})
        reply = _reopen_question(service, options) if service in _REOPEN_LABELS else "לאיזו חופשה התכוונת?"
        return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':"רק כדי לוודא - " + reply,'trip_update':trip_state,'start_flight_search':False})

    # An open conversation about a destination that already has an upcoming
    # vacation, but was never linked to it (seen live: "אטרקציות בניו יורק"
    # opened a fresh New York conversation, and the next "הי אריאלה" asked
    # again for days and travelers the New York vacation already has).
    # Offer once to attach it to that vacation.
    open_places = (trip_state.get("destination") or {}).get("places") if isinstance(trip_state.get("destination"), dict) else None
    if open_places and not (
        trip_state.get("search_confirmed") or trip_state.get("post_flight_continuation")
        or trip_state.get("reopened_trip_id") or trip_state.get("reopen_offer_declined")
    ):
        linked_service = trip_state.get("active_session") if trip_state.get("active_session") in _REOPEN_LABELS else None
        if not linked_service:
            linked_service = next((s for s in ("trip_planning", "lodging", "car") if s in (trip_state.get("requested_services") or [])), None)
        if linked_service:
            candidates = _reopenable_trips(session['member_id'], linked_service, " ".join(str(p) for p in open_places), limit=20)
            if candidates:
                pending = dict(trip_state)
                pending["reopen_trip_pending"] = {
                    "service": linked_service, "keep_state": True,
                    "options": [{"id": t["id"], "name": t["name"], "window": t["window"]} for t in candidates],
                }
                return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':_reopen_question(linked_service, candidates),'trip_update':pending,'start_flight_search':False})

    trip_is_empty = not ((trip_state.get("destination") or {}).get("places") if isinstance(trip_state.get("destination"), dict) else None) \
        and not trip_state.get("active_session") and not trip_state.get("reset_pending")
    if trip_is_empty:
        requested_service = _explicit_service_request(message, trip_state) or _classify_service_request(message, history)
        if requested_service in _REOPEN_LABELS:
            candidates = _reopenable_trips(session['member_id'], requested_service, message, limit=20)
            if candidates:
                pending = dict(trip_state)
                pending["reopen_trip_pending"] = {
                    "service": requested_service,
                    "options": [{"id": t["id"], "name": t["name"], "window": t["window"]} for t in candidates],
                }
                return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':_reopen_question(requested_service, candidates),'trip_update':pending,'start_flight_search':False})

    # The customer's saved vacations, every turn - so Ariella answers from
    # them instead of asking again for facts they already hold (seen live:
    # "תחפשי בחופשות שלי" about New York was answered with "כמה ימים ומי
    # נוסע?" although the New York vacation has both).
    trip_state = dict(trip_state)
    upcoming = _upcoming_vacations(session['member_id'])
    if upcoming:
        trip_state["upcoming_vacations"] = upcoming
    else:
        trip_state.pop("upcoming_vacations", None)

    # After the flight handoff, keep the same vacation as the default context.
    # When the customer asks for one of the remaining services, deterministically
    # activate that session and keep it active across follow-up answers.
    msg_lower = message.lower()
    existing_active = str(trip_state.get("active_session") or "")
    service_request = _explicit_service_request(message, trip_state)
    if service_request == existing_active:
        service_request = None
    flights_status = str((trip_state.get("session_status") or {}).get("flights") or "pending")
    flights_settled = flights_status in ("complete", "declined")
    if service_request and service_request != "flights" and not flights_settled:
        # Product decision: flights always come first, no exception for an
        # explicit mid-flights request to jump ahead (that was the previous,
        # now deliberately removed, behavior - see git history). Record what
        # the customer asked for so it opens automatically, without asking
        # again, the moment flights is complete or declined - but do not
        # switch active_session away from flights for it.
        continued = dict(trip_state)
        statuses = dict(continued.get("session_status") or {})
        decisions = dict(continued.get("service_decisions") or {})
        services = list(continued.get("requested_services") or [])
        decisions[service_request] = {"wanted": True, "source": "explicit_request_deferred_to_after_flights"}
        if service_request not in services:
            services.append(service_request)
        statuses["flights"] = "active"
        continued["session_status"] = statuses
        continued["service_decisions"] = decisions
        continued["requested_services"] = services
        continued["active_session"] = "flights"
        continued["next_session"] = None
        trip_state = continued
    elif service_request:
        # Either the customer explicitly asked for flights (always allowed -
        # this is also how "go back and change the flight" works once a
        # later session is active), or flights is already settled and moving
        # to another domain is exactly the intended next step.
        continued = dict(trip_state)
        statuses = dict(continued.get("session_status") or {})
        decisions = dict(continued.get("service_decisions") or {})
        services = list(continued.get("requested_services") or [])
        if statuses.get("flights") == "active" and service_request != "flights":
            statuses["flights"] = "pending"
        statuses[service_request] = "active"
        decisions[service_request] = {"wanted": True, "source": "explicit_request"}
        if service_request not in services:
            services.append(service_request)
        continued["session_status"] = statuses
        continued["service_decisions"] = decisions
        continued["requested_services"] = services
        continued["active_session"] = service_request
        continued["next_session"] = None
        trip_state = continued
    elif existing_active in {"lodging", "car", "trip_planning"}:
        # Ordinary answers inside a chosen session must not let the
        # extractor/sessionizer jump back to flights or another pending
        # service, whether or not flights was already approved.
        locked = dict(trip_state)
        statuses = dict(locked.get("session_status") or {})
        statuses[existing_active] = "active"
        locked["session_status"] = statuses
        locked["active_session"] = existing_active
        trip_state = locked

    # A request for a genuinely new vacation after a completed/approved trip is
    # a hard boundary, not a field edit. Clear the old structured trip immediately
    # and seed only facts explicitly present in the new request.
    new_vacation_language = any(x in msg_lower for x in ("חופשה חדשה","טיול חדש","חיפוש חדש לגמרי","חופשה אחרת","טיול אחר"))
    old_trip_committed = bool(trip_state.get("search_confirmed") or trip_state.get("post_flight_continuation"))
    # Own pending questions (new trip vs. destination change) are answered by
    # their own handlers below - "חופשה חדשה" there is the answer, not a new request.
    own_pending_question = bool(trip_state.get("new_trip_pending") or trip_state.get("reopen_trip_pending"))
    if new_vacation_language and old_trip_committed and not own_pending_question:
        fresh = {
            'session_status':{'flights':'pending','lodging':'pending','car':'pending','trip_planning':'pending'},
            'active_session':None
        }
        seed = _deterministic_destination_facts([], message, {})
        if seed:
            fresh = _merge_trip_state(fresh, seed)
        if any(x in msg_lower for x in ("טיסה","טיסות")):
            fresh['requested_services'] = ['flights']
            fresh['active_session'] = 'flights'
            fresh['session_status']['flights'] = 'active'
            fresh['service_decisions'] = {'flights':{'wanted':True,'source':'explicit_new_vacation'}}
        places = ((fresh.get('destination') or {}).get('places') or []) if isinstance(fresh.get('destination'), dict) else []
        reply = (f"בשמחה. מתחילים חופשה חדשה ל{places[0]}. באיזו תקופה תרצי לטוס?"
                 if places else "בשמחה. מתחילים חופשה חדשה. לאן תרצי לטוס ובאיזו תקופה?")
        _remember_turn_reset_trip(session['member_id'], history, message, reply, fresh)
        return jsonify({
            'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
            'reply':reply,'trip_update':fresh,'start_flight_search':False,'trip_state_reset':True
        })

    # Returning to an already-approved flight-only vacation is a navigation
    # action, not a new conversational turn and never a reason to launch a
    # duplicate scan. The browser will reopen the existing vacation's flight tab.
    flight_only_return = (
        bool(trip_state.get("post_flight_continuation"))
        and bool(trip_state.get("search_confirmed"))
        and any(x in msg_lower for x in ("רק טיסה","רק טיסות","טיסה בלבד","טיסות בלבד"))
    )
    if flight_only_return:
        return jsonify({
            'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
            'reply':'פרטי הטיסה כבר אושרו. אני מחזירה אותך לטיסות של החופשה הזו.',
            'trip_update':trip_state,'start_flight_search':False,'open_existing_flights':True
        })

    # Interpret answers to a pending "same vacation or new vacation?" question
    # semantically. The customer can answer naturally; there are no magic phrases.
    last_assistant = ""
    _triggering_user_message = None
    _seen_last_assistant = False
    for _item in reversed(history):
        if not isinstance(_item, dict):
            continue
        _role = str(_item.get("role") or "").lower()
        if not _seen_last_assistant and _role == "assistant":
            last_assistant = str(_item.get("content") or "").strip().lower()
            _seen_last_assistant = True
            continue
        if _seen_last_assistant and _role == "user":
            _triggering_user_message = str(_item.get("content") or "")
            break
    # A vague "משהו אחר" ("something else") answering Ariella's own
    # "continue the upcoming vacation, or is this something else?" framing
    # (the continuity prompt rule driven by upcoming_vacations, further
    # below) must not just re-ask the identical question in slightly
    # different words - seen live, it looped twice in a row with near-
    # identical phrasing because "something else" alone never cleared the
    # model's own bar for "a clear request for a new vacation/destination".
    # Break the loop deterministically: once the customer's answer doesn't
    # name a concrete destination either, open the question up instead of
    # repeating the same binary choice again.
    _previous_offered_continue_or_other = (
        ("ממשיכים" in last_assistant or "להמשיך" in last_assistant) and "אחר" in last_assistant
    )
    _vague_something_else = _normalize_confirm(message).strip() in {
        "משהו אחר", "דבר אחר", "נושא אחר", "משהו אחר לגמרי", "לא זה", "עניין אחר", "לא קשור",
    }
    if _previous_offered_continue_or_other and _vague_something_else and not own_pending_question:
        if not _deterministic_destination_facts([], message, {}):
            open_reply = "בטח, ספרי לי - במה אפשר לעזור?"
            try:
                saved_history = list(history_before_gap) + [
                    {'role': 'user', 'content': message},
                    {'role': 'assistant', 'content': open_reply},
                ]
                save_ariella_conversation(session['member_id'], saved_history[-80:], trip_state)
            except Exception:
                logging.exception("Failed to persist Ariella conversation for member %s", session.get('member_id'))
            return jsonify({
                'status': 'success', 'agent': 'Ariella', 'engine_version': ENGINE_VERSION,
                'reply': open_reply, 'trip_update': trip_state, 'start_flight_search': False,
            })
    _previous_asked_new_vacation = (
        "חופשה" in last_assistant and "חדשה" in last_assistant
        and ("הקודמת" in last_assistant or "הנוכחית" in last_assistant or "אותה חופשה" in last_assistant or "למחוק" in last_assistant or "להתחיל" in last_assistant)
    )
    if _previous_asked_new_vacation and not own_pending_question:
        _intent = _interpret_pending_choice(key, model, history, message, "new_vacation")
        if _intent == "new":
            # The destination was very often already stated in the one
            # message that triggered this "start fresh or just change?"
            # question (e.g. "לא, בואי נתכנן חופשה חדשה לקפריסין") - by the
            # time the customer confirms "כן" here, that's 1 turn back, not
            # in the current message. Scoped to exactly that one triggering
            # message (not the full history) deliberately: a genuine "בואי
            # נתחיל מהתחלה" with no destination of its own must never pull
            # in an unrelated destination mentioned somewhere earlier in a
            # long conversation (a previous, already-finished vacation) -
            # seen live, right after the equivalent full-history version of
            # this fix shipped: "לרנקה" from an old vacation got silently
            # adopted as the new one's destination with nothing said about
            # it this time.
            _fresh_new = {'session_status':{'flights':'pending','lodging':'pending','car':'pending','trip_planning':'pending'},'active_session':None}
            _trigger_history = [{"role": "user", "content": _triggering_user_message}] if _triggering_user_message else []
            _seed_new = _deterministic_destination_facts(_trigger_history, message, {})
            if _seed_new:
                _fresh_new = _merge_trip_state(_fresh_new, _seed_new)
            _places_new = ((_fresh_new.get('destination') or {}).get('places') or []) if isinstance(_fresh_new.get('destination'), dict) else []
            _reply_new = (f"בשמחה 😊 מתחילים חופשה חדשה ל{_places_new[0]}. באיזו תקופה תרצי לטוס?"
                          if _places_new else 'בשמחה 😊 לאן תרצי לטוס ובאיזו תקופה?')
            _remember_turn_reset_trip(session['member_id'], history, message, _reply_new, _fresh_new)
            return jsonify({
                'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                'reply':_reply_new,
                'trip_update':_fresh_new,
                'start_flight_search':False,'trip_state_reset':True
            })
        if _intent == "keep":
            kept = dict(trip_state)
            kept["reset_pending"] = False
            kept.pop("reset_change_request", None)
            return jsonify({
                'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                'reply':'בשמחה. מה תרצי לשנות בחופשה הנוכחית?',
                'trip_update':kept,'start_flight_search':False
            })

    # General restart/change-of-direction always enters a simple yes/no gate.
    # Never erase collected trip facts before an explicit confirmation.
    if _reset_intent(message) and not trip_state.get("reset_pending") and not own_pending_question:
        pending = dict(trip_state)
        pending["reset_pending"] = True
        pending["reset_change_request"] = message
        # Narrowing to a flights-only reset must require the customer to
        # actually SAY it's just the flight - defaulting to "flights-only
        # whenever flights happen to already be complete and nothing else is
        # active" was wrong far more often than right. Seen live repeatedly:
        # a customer restarting after an already-approved ski vacation always
        # matches that exact session shape (flights complete, nothing else
        # active) even when she is plainly describing an entirely different
        # trip (destination, dates, trip type) - a flights-only reset only
        # clears flight-search fields, so trip_type/destination/ski state
        # (and anything else outside that narrow field list) silently
        # survives and keeps leaking into what she clearly means as a new
        # vacation. Trying to enumerate every "I mean everything" phrasing
        # ("הכל"/"הכול"/"לגמרי"/"מהיסוד"...) chased one live failure at a
        # time without fixing the actual default. A full vacation reset is
        # the safe default instead: at worst it re-asks a fact the customer
        # would have repeated anyway; a wrongly-scoped flights-only reset
        # silently keeps wrong facts she never gets a chance to correct.
        explicit_flight_only = any(
            w in str(message or "") for w in ("רק את הטיסה", "רק הטיסה", "רק פרטי הטיסה", "רק טיסה", "רק תאריכי הטיסה")
        )
        flight_only_reset = explicit_flight_only
        pending["reset_scope"] = "flights" if flight_only_reset else "vacation"
        # Per product owner: one plain yes/no question only - do not spell
        # out the alternative ("or keep everything and just change X") in
        # the question itself. The answer alone decides which path runs.
        question = (
            "למחוק את פרטי הטיסה ולהתחיל מחדש?"
            if flight_only_reset else
            "למחוק את כל הפרטים ולהתחיל חופשה חדשה מאפס?"
        )
        return jsonify({
            'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
            'reply':question,
            'trip_update':pending,'start_flight_search':False
        })

    if trip_state.get("reset_pending"):
        msg_norm = str(message or "").strip().lower()
        yes_answers = {"כן", "כן.", "כן!", "בטח", "בהחלט"}
        no_answers = {"לא", "לא.", "לא!", "לא תודה"}

        if msg_norm in yes_answers:
            original_change = str(trip_state.get("reset_change_request") or "").strip()
            if trip_state.get("reset_scope") == "flights":
                fresh = dict(trip_state)
                for key_name in ("departure_airport","destination_airports","flight","budget_per_person","search_confirmed","ready_for_summary"):
                    fresh.pop(key_name, None)
                fresh["dates"] = {}
                statuses_fresh = dict(fresh.get("session_status") or {})
                statuses_fresh["flights"] = "active"
                fresh["session_status"] = statuses_fresh
                fresh["active_session"] = "flights"
                fresh["search_intent"] = True
                fresh["reset_pending"] = False
                fresh.pop("reset_scope", None)
                fresh.pop("reset_change_request", None)
                return jsonify({
                    'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                    'reply':'בסדר. מחקתי את פרטי הטיסה. לאן תרצי לטוס ובאיזו תקופה?',
                    'trip_update':fresh,'start_flight_search':False
                })
            # The message that triggered the reset gate may already contain facts
            # for the NEW vacation ("I want you to plan Greece"). Preserve those
            # facts across the confirmation instead of asking for them again.
            fresh = {
                'session_status':{'flights':'pending','lodging':'pending','car':'pending','trip_planning':'pending'},
                'active_session':None
            }
            pending_destination = _deterministic_destination_facts([], original_change, {})
            if pending_destination:
                fresh = _merge_trip_state(fresh, pending_destination)
            if any(x in original_change.lower() for x in ("מסלול","לתכנן טיול","תכנון טיול","אטרקציות")):
                fresh['requested_services'] = ['trip_planning']
                fresh['active_session'] = 'trip_planning'
                fresh['session_status']['trip_planning'] = 'active'
                fresh['service_decisions'] = {'trip_planning':{'wanted':True}}
            places = ((fresh.get('destination') or {}).get('places') or []) if isinstance(fresh.get('destination'), dict) else []
            if places:
                reply = f"בשמחה. מתחילים חופשה חדשה ל{places[0]}. נמשיך מכאן בתכנון הטיול — באיזו תקופה תרצי לנסוע?"
            else:
                reply = 'בסדר. מתחילים חופשה חדשה. לאן מתחשק לך לטוס ובאיזו תקופה?'
            _remember_turn_reset_trip(session['member_id'], history, message, reply, fresh)
            return jsonify({
                'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                'reply':reply,'trip_update':fresh,'start_flight_search':False,'trip_state_reset':True
            })

        if msg_norm in no_answers:
            original_change = str(trip_state.get("reset_change_request") or "").strip()
            kept = dict(trip_state)
            kept["reset_pending"] = False
            kept.pop("reset_change_request", None)
            # If the original message only expressed a general wish to change,
            # ask what to change. If it already named the requested change, keep
            # the trip facts and let the next turn continue from that context.
            return jsonify({
                'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                'reply':('מה תרצי לשנות בפרטי הטיסה?' if trip_state.get("reset_scope") == "flights" else 'מה תרצי לשנות בחופשה הנוכחית?'),
                'trip_update':kept,'start_flight_search':False
            })

        # While awaiting this gate, do not let the model reinterpret or mutate
        # the trip. Keep the question binary and deterministic.
        pending = dict(trip_state)
        return jsonify({
            'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
            'reply':('רק כדי לוודא: למחוק הכול ולהתחיל טיסה חדשה, או להשאיר ולשנות רק פרט אחד? (כן = למחוק ולהתחיל מחדש, לא = להשאיר ולשנות)' if trip_state.get("reset_scope") == "flights" else 'רק כדי לוודא: למחוק הכול ולהתחיל חופשה חדשה, או להשאיר ולשנות רק פרט אחד? (כן = למחוק ולהתחיל מחדש, לא = להשאיר ולשנות)'),
            'trip_update':pending,'start_flight_search':False
        })

    # Destination replacement is the only ordinary field change that requires
    # confirmation because route/lodging/car destination-dependent facts become stale.
    # A real customer's destination-change wasn't caught here because this list only
    # named 8 countries - "ספרד" (Spain) wasn't one of them, so the swap fell through
    # to plain extraction with no confirmation/rebuild step, in a conversation Tinkerbell
    # itself was already confused by. Every city already in DESTINATIONS is covered
    # automatically now, plus every country those cities sit in, so a newly-added
    # destination city doesn't reopen this same gap.
    import re
    known_destinations = (
        "יוון", "קפריסין", "הונגריה", "אוסטריה", "בולגריה", "צ'כיה", "איטליה", "צרפת",
        "הולנד", "ספרד", "פורטוגל", "בריטניה", "גרמניה", "שוויץ", "בלגיה", "רומניה",
        "פולין", "גאורגיה", "ארמניה", "סרביה", "מקדוניה", "מונטנגרו", "קרואטיה",
        "סלובניה", "תאילנד", "ארה\"ב", "אלבניה", "איחוד האמירויות", "אזרבייג'ן",
        "מולדובה", "מלטה",
    ) + tuple(d["name"] for d in DESTINATIONS)
    current_destination = trip_state.get("destination") if isinstance(trip_state.get("destination"), dict) else {}
    current_places = current_destination.get("places") or []
    destination_change = None
    possible_new_trip = None
    # A place that is part of the current vacation's own country (e.g.
    # "איטליה" while planning Rome) is never a different destination.
    current_countries = _place_countries(current_places) | set(current_places)

    _HEBREW_PREFIX_LETTERS = "ובכלמשה"

    def _candidate_mentioned(candidate, text):
        # Plain substring matching treats a known destination name as
        # "mentioned" even when it's just a few letters inside a longer,
        # unrelated word - seen live: "לכיוון" (direction/towards) contains
        # "יוון" (Greece) as a bare substring. A Cyprus-trip customer asking
        # "וכל יום לנסוע לכיוון אחר?" (can we travel in a different
        # direction each day?) about splitting up lodging nights got read as
        # wanting to change the destination to Greece, and landed on a
        # confusing "change destination and rebuild everything?" prompt that
        # had nothing to do with her actual question.
        # Hebrew glues a preposition directly onto the next word with no
        # space ("ליוון" = "to Greece"), so a bare word-boundary check alone
        # would also reject that genuine mention. Allow stepping back over
        # exactly one such prefix letter (ו/ב/כ/ל/מ/ש/ה); beyond that single
        # letter the preceding character must not be Hebrew at all, or the
        # match is just a fragment of a longer unrelated word with a
        # coincidental run of letters in it ("כיוון" swallows "יוון" one
        # letter in, not at any real word boundary).
        for m in re.finditer(re.escape(candidate), text):
            start, end = m.start(), m.end()
            left = start
            if left > 0 and text[left - 1] in _HEBREW_PREFIX_LETTERS:
                left -= 1
            before_ok = left == 0 or not ("א" <= text[left - 1] <= "ת")
            after_ok = end == len(text) or not ("א" <= text[end] <= "ת")
            if before_ok and after_ok:
                return True
        return False

    for candidate in known_destinations:
        if _candidate_mentioned(candidate, message) and current_places and candidate not in current_places:
            if candidate in current_countries or _place_countries([candidate]) & current_countries:
                continue
            if any(token in message for token in ("במקום","רוצה לטוס ל","היעד","לשנות")):
                destination_change = candidate
                break
            # Seen as a gap: "ומה עם טיסה לפריז בדצמבר?" in the middle of an
            # open Rome vacation had no "new"/"instead" wording, so Paris and
            # December could silently merge into the Rome trip. A different
            # destination asked about as a trip of its own gets a question
            # instead. Never inside route planning, where other places come
            # up naturally (day trips, comparisons).
            if str(trip_state.get("active_session") or "") == "trip_planning":
                continue
            trip_cues = ("טיסה ל","לטוס ל","טיסות ל","חופשה ב","חופשה ל","טיול ל","נסיעה ל","לנסוע ל")
            cue_adjacent = any(cue + candidate in message or cue + "ה" + candidate in message for cue in trip_cues)
            # Seen live: once a trip is already committed (flights searched/
            # booked - search_confirmed or post_flight_continuation), a bare
            # mention of a different known destination with no adjacent cue
            # at all ("קפריסין, 27 ליוני...") silently merged into the OLD
            # committed trip instead of asking - old dates/destination/
            # travelers/session_status then bled into what the customer
            # clearly meant as a brand new, separate vacation. Past this
            # point in a trip's life "day trip comparison" is far less
            # likely than it is during open route-planning chat, so a bare
            # known-destination mention is itself a strong enough signal -
            # no cue phrase required.
            trip_already_committed = bool(trip_state.get("search_confirmed") or trip_state.get("post_flight_continuation"))
            if cue_adjacent or trip_already_committed:
                possible_new_trip = candidate
                break

    # Seen live: the customer says "אני רוצה מקום אחר" (no candidate yet, so
    # none of the cues above fire and the model just asks "where to?" in free
    # text), then answers with a bare place name ("פראג") - which also has
    # none of "במקום"/"לשנות" etc., so it matched nothing here either. The
    # model's free-text reply acknowledged the swap, but trip_state.destination
    # never changed, and every later question kept being about the old place.
    # A bare place name right after the customer's own stated wish to replace
    # the destination is the same intent as the explicit cues above.
    if not destination_change and not possible_new_trip and current_places:
        general_replace_phrases = (
            "מקום אחר", "יעד אחר", "לא מתאים לי", "רוצה להחליף", "רוצה לשנות יעד",
            "רוצה לשנות את היעד", "לא רוצה את היעד", "יעד שונה",
        )
        prior_user_wanted_different_place = False
        seen_assistant = False
        for _item in reversed(history or []):
            if not isinstance(_item, dict):
                continue
            role = str(_item.get("role") or "").lower()
            if role == "assistant":
                seen_assistant = True
                continue
            if role == "user" and seen_assistant:
                prior_user_wanted_different_place = any(p in str(_item.get("content") or "") for p in general_replace_phrases)
                break
        if prior_user_wanted_different_place:
            for candidate in known_destinations:
                if _candidate_mentioned(candidate, message) and candidate not in current_places:
                    if candidate in current_countries or _place_countries([candidate]) & current_countries:
                        continue
                    destination_change = candidate
                    break

    pending_new_trip = trip_state.get("new_trip_pending")
    if pending_new_trip:
        msg_norm = _normalize_confirm(message).lower()
        if any(w in msg_norm for w in ("חדשה", "חדש", "נפרדת", "נפרד", "אחרת")):
            intent = "new"
        elif any(w in msg_norm for w in ("שינוי", "לשנות", "הנוכחית", "במקום", "להחליף")):
            intent = "keep"
        else:
            intent = _interpret_pending_choice(key, model, history, message, "new_vacation")
        if intent == "new":
            fresh = {'session_status':{'flights':'pending','lodging':'pending','car':'pending','trip_planning':'pending'},'active_session':None,
                     'destination':{'places':[pending_new_trip],'mode':'specific','status':'known'}}
            reply = f"בסדר, מתחילים חופשה חדשה ל{pending_new_trip}. באיזו תקופה תרצי לטוס?"
            _remember_turn_reset_trip(session['member_id'], history, message, reply, fresh)
            return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,'reply':reply,'trip_update':fresh,'start_flight_search':False,'trip_state_reset':True})
        if intent == "keep":
            kept = dict(trip_state)
            kept.pop("new_trip_pending", None)
            kept["destination_change_pending"] = pending_new_trip
            return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                            'reply':'שינוי היעד משנה גם את המסלול, הלינה, נקודות הרכב ופרטי הטיסה שתלויים ביעד. למחוק את הפרטים שתלויים ביעד ולבנות אותם מחדש ליעד החדש?',
                            'trip_update':kept,'start_flight_search':False})
        return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                        'reply':f"רק כדי לוודא - {pending_new_trip}: זו חופשה חדשה ונפרדת, או שינוי יעד בחופשה הנוכחית ל{', '.join(current_places)}?",
                        'trip_update':trip_state,'start_flight_search':False})

    if possible_new_trip and not trip_state.get("destination_change_pending"):
        pending = dict(trip_state)
        pending["new_trip_pending"] = possible_new_trip
        return jsonify({'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                        'reply':f"רגע, לפני שממשיכים - {possible_new_trip}: זו חופשה חדשה ונפרדת, או שינוי יעד בחופשה הנוכחית ל{', '.join(current_places)}?"
                                + ("" if (trip_state.get("search_confirmed") or trip_state.get("post_flight_continuation"))
                                   else f" (החופשה ל{', '.join(current_places)} עוד לא אושרה, אז בחופשה חדשה הפרטים שלה יימחקו.)"),
                        'trip_update':pending,'start_flight_search':False})

    if destination_change and not trip_state.get("destination_change_pending"):
        pending = dict(trip_state)
        pending["destination_change_pending"] = destination_change
        return jsonify({
            'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
            'reply':'שינוי היעד משנה גם את המסלול, הלינה, נקודות הרכב ופרטי הטיסה שתלויים ביעד. למחוק את הפרטים שתלויים ביעד ולבנות אותם מחדש ליעד החדש?',
            'trip_update':pending,'start_flight_search':False
        })

    if trip_state.get("destination_change_pending"):
        msg_norm = str(message or "").strip().lower()
        if msg_norm in {"כן","כן.","כן!","בטח","בהחלט"}:
            changed = dict(trip_state)
            new_destination = changed.pop("destination_change_pending")
            changed["destination"] = {"places":[new_destination],"mode":"specific","status":"known"}
            # The old destination's arrival/return gateway codes are specific
            # to that place (e.g. BUD for Budapest) and the system prompt
            # treats destination_airports as locked once set, so a swap that
            # left them in place would permanently strand the new destination
            # on the old airport.
            changed.pop("destination_airports", None)
            changed.pop("return_departure_airports", None)
            old_lodging = changed.get("lodging") if isinstance(changed.get("lodging"), dict) else {}
            old_car = changed.get("car") if isinstance(changed.get("car"), dict) else {}
            old_plan = changed.get("trip_planning") if isinstance(changed.get("trip_planning"), dict) else {}
            changed["lodging"] = {"interested":old_lodging.get("interested","unknown"),"details":{}}
            changed["car"] = {"interested":old_car.get("interested","unknown"),"details":{}}
            changed["trip_planning"] = {"interested":old_plan.get("interested","unknown"),"details":{}}
            changed["ready_for_summary"] = False
            changed["search_confirmed"] = False
            changed["missing_required"] = []
            return jsonify({
                'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                'reply':'בסדר. היעד עודכן. את המסלול, הלינה והרכב נבנה מחדש בהתאם ליעד החדש.',
                'trip_update':changed,'start_flight_search':False
            })
        if msg_norm in {"לא","לא.","לא!","לא תודה"}:
            kept = dict(trip_state)
            kept.pop("destination_change_pending", None)
            return jsonify({
                'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
                'reply':'בסדר, נשאיר את היעד הקיים.',
                'trip_update':kept,'start_flight_search':False
            })
        return jsonify({
            'status':'success','agent':'Ariella','engine_version':ENGINE_VERSION,
            'reply':'לשנות את היעד ולבנות מחדש את הפרטים שתלויים בו? כן או לא?',
            'trip_update':trip_state,'start_flight_search':False
        })

    # A confirmed/new-trip boundary prevents old vacation facts from being
    # resurrected by the model or deterministic history scanners.
    if trip_state.get("conversation_boundary") == "current_trip":
        history = _current_trip_history(history, trip_state)

    # Seen live: Ariella offered two pre-computed candidate ranges (both
    # already weekday-validated at generation time), the customer picked
    # one by replying "27 עד 1.7" (departure day bare, return date in
    # day.month shorthand), and _weekday_date_conflict's own independent,
    # naive date-extraction only found the ONE full "D.M" token (1.7 -
    # the return date) in the message - it has no way to parse a bare day
    # number like "27" as a date. That single found date then got
    # positionally zipped against [departure_weekday, return_weekday] as
    # if it were the departure, producing a false "01.07.2027 is Thursday,
    # but you wanted Sunday" conflict for a choice that was correct all
    # along. _deterministic_candidate_choice_facts is the authoritative,
    # already-validated mechanism for resolving a reply against pre-
    # computed candidates - when it actually resolves this message, trust
    # it and skip the separate, more fragile weekday-conflict heuristic
    # entirely rather than let two independent parsers of the same text
    # disagree.
    if not _deterministic_candidate_choice_facts(message, trip_state):
        date_conflict = _weekday_date_conflict(message, history)
        if date_conflict:
            return jsonify({'status':'success','agent':'Tinkerbell','engine_version':ENGINE_VERSION,'reply':date_conflict,'trip_update':trip_state})
    key = os.getenv('ANTHROPIC_API_KEY', '').strip()
    if not key:
        return jsonify({'status': 'error', 'message': 'טינקרבל לא זמינה כרגע.', 'engine_version': ENGINE_VERSION}), 503
    model = os.getenv('ARIELLA_MODEL', 'claude-sonnet-5').strip()

    try:
        # Tinkerbell's data-transfer pass tells Ariella what changed.
        # Ariella owns and merges the cumulative state.
        extracted = _extract_trip_update(key, model, history, message, trip_state)
        trip_update = _merge_trip_state(trip_state, extracted)
        trip_update = _clear_stale_gateway_airports(trip_update)
        trip_update = _keep_declines(trip_state, trip_update, service_request)
        trip_update = _roll_past_dates(trip_update, message, history)
        trip_update = _split_car_transmission(trip_update)
        trip_update = _protect_car_details_from_loss(trip_state, trip_update)
        trip_update = _protect_lodging_details_from_loss(trip_state, trip_update)
        # Service intent is semantic. When the extractor explicitly resolves a
        # domain as wanted/not-wanted, that decision is authoritative even if an
        # older requested_services list still contains the domain.
        extracted_decisions = extracted.get("service_decisions") if isinstance(extracted, dict) and isinstance(extracted.get("service_decisions"), dict) else {}
        if extracted_decisions:
            decisions = dict(trip_update.get("service_decisions") or {})
            statuses = dict(trip_update.get("session_status") or {})
            services = set(trip_update.get("requested_services") or [])
            prior_statuses = trip_state.get("session_status") if isinstance(trip_state.get("session_status"), dict) else {}
            prior_decisions = trip_state.get("service_decisions") if isinstance(trip_state.get("service_decisions"), dict) else {}
            # A domain untouched by this message must never silently flip
            # from pending to declined just because the customer engaged
            # with a DIFFERENT domain this turn - the extractor's own rules
            # already forbid concluding another service was declined just
            # because one was mentioned, but it doesn't reliably follow
            # that. Seen live: offered lodging+car+trip_planning together,
            # the customer engaged only with the route and then lodging,
            # and car - never discussed at all - silently went straight
            # from pending to "declined" with no decline of any kind from
            # the customer. Per product owner: a domain stays open until
            # the customer actually answers no to it; it is never inferred
            # from silence. A pending domain not named anywhere in this
            # message keeps its prior status instead of trusting the
            # extractor's unexplained "wanted=false". A domain already
            # being actively discussed (session_status "active") is not
            # gated here - the conversation IS about it this turn, so a
            # genuine "actually, never mind" is trustworthy there.
            service_name_cues = {
                "lodging": ("לינה","מלון","וילה","דירה","אכסניה"),
                "car": ("רכב",),
                "trip_planning": ("מסלול","אטרקצי","תכנון הטיול","תוכנית הטיול"),
            }
            msg_text = str(message or "")
            for service in ("flights","lodging","car","trip_planning"):
                d = extracted_decisions.get(service)
                wanted = d.get("wanted") if isinstance(d, dict) else d
                if wanted is True:
                    services.add(service)
                    statuses[service] = statuses.get(service) if statuses.get(service) == "complete" else "active"
                elif wanted is False:
                    prior_status = prior_statuses.get(service)
                    if prior_status in (None, "pending"):
                        cues = service_name_cues.get(service, ())
                        if not any(c in msg_text for c in cues):
                            # _merge_trip_state already merged the extractor's
                            # unproven "wanted=false" into trip_update's own
                            # service_decisions before this block ever runs -
                            # _sessionize_state (inside _advance_sessions,
                            # called later this same turn, and again on
                            # every future turn) reads that field directly
                            # and would unconditionally re-derive
                            # session_status="declined" from it regardless
                            # of what this guard decides here. The merged
                            # value must be rolled back to what it was
                            # before this turn, not just left unused.
                            decisions[service] = prior_decisions.get(service)
                            continue
                    services.discard(service)
                    statuses[service] = "declined"
            trip_update["requested_services"] = list(services)
            trip_update["service_decisions"] = decisions
            trip_update["session_status"] = statuses
        # Safety net for a short decline ("לא"/"גם לא כרגע" etc.) to Ariella's
        # own previous lodging/car question. Applied the same way as the
        # extractor's own decisions above so it authoritatively overrides a
        # misattributed or dropped extraction - see the function's docstring
        # for the live-transcript loop this fixes.
        post_flight_answer = _post_flight_offer_answer(message, trip_state, key, model, history)
        if post_flight_answer.pop("_transfer_to_results", False):
            # The customer asked to be taken to the results now, exactly the
            # alternative Ariella's own offer named - settle it immediately
            # and deterministically (declining the offered extras, same as a
            # plain "לא") rather than falling through to the normal model
            # reply, which has no way to also navigate and previously just
            # described a transfer that never happened.
            decisions = dict(trip_update.get("service_decisions") or {})
            statuses = dict(trip_update.get("session_status") or {})
            services = set(trip_update.get("requested_services") or [])
            for service in post_flight_answer:
                decisions[service] = {"wanted": False, "source": "post_flight_offer"}
                services.discard(service)
                statuses[service] = "declined"
            trip_update["requested_services"] = list(services)
            trip_update["service_decisions"] = decisions
            trip_update["session_status"] = statuses
            trip_update["post_flight_offer"] = []
            transfer_reply = "מעבירה אותך לתוצאות הטיסות. תמיד אפשר לחזור לכאן בהמשך ולהוסיף עוד."
            try:
                saved_history = list(history_before_gap) + [
                    {'role': 'user', 'content': message},
                    {'role': 'assistant', 'content': transfer_reply},
                ]
                save_ariella_conversation(session['member_id'], saved_history[-80:], trip_update)
            except Exception:
                logging.exception("Failed to persist Ariella conversation for member %s", session.get('member_id'))
            return jsonify({
                'status': 'success', 'agent': 'Ariella', 'engine_version': ENGINE_VERSION,
                'reply': transfer_reply, 'trip_update': trip_update, 'start_flight_search': False,
                'open_existing_flights': True,
            })
        if post_flight_answer:
            decisions = dict(trip_update.get("service_decisions") or {})
            statuses = dict(trip_update.get("session_status") or {})
            services = set(trip_update.get("requested_services") or [])
            for service, wanted in post_flight_answer.items():
                decisions[service] = {"wanted": wanted, "source": "post_flight_offer"}
                if wanted:
                    services.add(service)
                    if statuses.get(service) != "complete":
                        statuses[service] = "active"
                else:
                    services.discard(service)
                    statuses[service] = "declined"
            trip_update["requested_services"] = list(services)
            trip_update["service_decisions"] = decisions
            trip_update["session_status"] = statuses
            trip_update["post_flight_offer"] = []
            first_wanted = next((s for s in ("trip_planning","lodging","car") if post_flight_answer.get(s)), None)
            if first_wanted:
                trip_update["active_session"] = first_wanted
        deterministic_decline = _deterministic_service_decline_facts(history, message)
        decline_decisions = deterministic_decline.get("service_decisions") if isinstance(deterministic_decline, dict) else None
        if decline_decisions:
            decisions = dict(trip_update.get("service_decisions") or {})
            statuses = dict(trip_update.get("session_status") or {})
            services = set(trip_update.get("requested_services") or [])
            for service, d in decline_decisions.items():
                decisions[service] = d
                if (d.get("wanted") if isinstance(d, dict) else d) is False:
                    services.discard(service)
                    statuses[service] = "declined"
            trip_update["requested_services"] = list(services)
            trip_update["service_decisions"] = decisions
            trip_update["session_status"] = statuses
        named_decline = _deterministic_named_decline_facts(message)
        named_decline_decisions = named_decline.get("service_decisions") if isinstance(named_decline, dict) else None
        if named_decline_decisions:
            decisions = dict(trip_update.get("service_decisions") or {})
            statuses = dict(trip_update.get("session_status") or {})
            services = set(trip_update.get("requested_services") or [])
            for service, d in named_decline_decisions.items():
                decisions[service] = d
                if (d.get("wanted") if isinstance(d, dict) else d) is False:
                    services.discard(service)
                    statuses[service] = "declined"
            trip_update["requested_services"] = list(services)
            trip_update["service_decisions"] = decisions
            trip_update["session_status"] = statuses
        # Safety net for facts that must never be re-asked. This helper already
        # existed but was not wired into the live chat path. Run it before
        # missing-field/session calculation so an explicitly stated destination
        # remains authoritative even when the LLM extractor misses it.
        trip_update = _merge_trip_state(
            trip_update,
            _deterministic_destination_facts(history, message, trip_state)
        )
        trip_update = _merge_trip_state(
            trip_update,
            _deterministic_date_facts(history, message, trip_state)
        )
        # Closed exact dates are sticky. Once the customer has an authoritative
        # departure+return range, an unrelated later turn (route, attractions,
        # car, lodging, "sounds good", etc.) must never reopen date selection.
        # Dates may change only when the current message itself contains a new
        # deterministic date fact/range.
        prior_dates = trip_state.get("dates") if isinstance(trip_state.get("dates"), dict) else {}
        current_date_facts = _deterministic_date_facts([], message, {})
        current_dates = current_date_facts.get("dates") if isinstance(current_date_facts, dict) and isinstance(current_date_facts.get("dates"), dict) else {}
        # An explicit new date range in the CURRENT customer message overrides the
        # old approved range. Sticky dates protect against unrelated turns only;
        # they must never block a correction such as "change it to 23-27 May 2027".
        if current_dates:
            trip_update["dates"] = dict(current_dates)
            trip_update["dates"]["needs_confirmation"] = False
            trip_update["dates"]["candidate_ranges"] = []
            trip_update["search_confirmed"] = False
            trip_update["ready_for_summary"] = False
        elif prior_dates.get("departure") and prior_dates.get("return"):
            locked_dates = dict(prior_dates)
            # Exact dates are authoritative. Do not preserve stale proposal flags
            # from an earlier candidate-selection phase.
            locked_dates["needs_confirmation"] = False
            locked_dates.pop("candidate_ranges", None)
            locked_dates.pop("candidates", None)
            trip_update["dates"] = locked_dates
        only_flights_facts = _deterministic_only_flights_facts(message)
        trip_update = _merge_trip_state(trip_update, only_flights_facts)
        # "Only flights" is a replacement decision, not an additive merge.
        # The generic recursive merge intentionally preserves lists, so enforce
        # the exclusive service set after extraction to prevent lodging/car/plan
        # from being resurrected by prior state or the LLM.
        if only_flights_facts:
            trip_update["requested_services"] = ["flights"]
            decisions = dict(trip_update.get("service_decisions") or {})
            decisions.update(only_flights_facts["service_decisions"])
            trip_update["service_decisions"] = decisions
            statuses = dict(trip_update.get("session_status") or {})
            statuses.update(only_flights_facts["session_status"])
            trip_update["session_status"] = statuses
            trip_update["active_session"] = "flights"
            trip_update["next_session"] = None
        trip_update = _merge_trip_state(trip_update, _deterministic_budget_facts(message))
        trip_update = _merge_trip_state(trip_update, _budget_answer_by_meaning(message, history, trip_update))
        trip_update = _merge_trip_state(trip_update, _deterministic_baggage_facts(message))
        trip_update = _merge_trip_state(trip_update, _deterministic_departure_airport_facts(message))
        trip_update = _merge_trip_state(trip_update, _deterministic_open_jaw_airports(message))
        trip_update = _merge_trip_state(trip_update, _deterministic_airport_indifference(message, history, trip_update))
        trip_update = _merge_trip_state(trip_update, _deterministic_trip_planning_pace_facts(message, history))
        trip_update = _merge_trip_state(trip_update, _deterministic_car_vehicle_facts(message, history))
        trip_update = _merge_trip_state(trip_update, _deterministic_lodging_facts(message, history))
        trip_update = _merge_trip_state(trip_update, _deterministic_trip_type_facts(message))
        # A "new vacation" reset (e.g. the customer replying "new" to "is this
        # a new plan or continuing the ski trip?") clears trip_type, but the
        # message that actually triggered the reset often already named the
        # trip type ("let's ALSO plan a family vacation") - seen live: the
        # customer got asked "regular/business/ski?" again right after saying
        # "family vacation", which reasonably felt like Ariella not listening.
        # Only the single most recent prior user message is checked, mirroring
        # how the explicit reset-gate flow above scopes reset_change_request.
        if not trip_update.get("trip_type"):
            for _item in reversed(history or []):
                if isinstance(_item, dict) and str(_item.get("role") or "").lower() == "user":
                    trip_update = _merge_trip_state(trip_update, _deterministic_trip_type_facts(_item.get("content")))
                    break
        trip_update = _merge_trip_state(trip_update, _deterministic_traveler_facts(message, trip_state.get("travelers")))
        trip_update = _merge_trip_state(trip_update, _infer_standard_trip_type(trip_update, message, history))
        trip_update = _merge_trip_state(trip_update, _deterministic_duration_facts(message, trip_state))
        # If Ariella's immediately previous reply proposed one concrete date range
        # and the customer simply continued (e.g. supplied the airport), accept it.
        trip_update = _merge_trip_state(trip_update, _accept_assistant_single_date_proposal(history, message, trip_state))
        # A single proposed range is accepted when the customer naturally continues
        # without rejecting/changing it. Multiple alternatives still require a choice.
        trip_update = _merge_trip_state(trip_update, _accept_single_proposed_date_range(message, trip_state))
        # If Ariella offered concrete date ranges and the customer chose one,
        # convert that choice to authoritative exact dates before any summary/search.
        trip_update = _merge_trip_state(trip_update, _deterministic_candidate_choice_facts(message, trip_state))
        # Current message + Ariella state only. Never resurrect facts from old chat history.
        # Weekday/month wording opens a date choice only while dates are still
        # open - never reopens dates the customer already closed (mid-route
        # "סוף מאי, ראשון עד חמישי" is context, not a new request).
        if not (prior_dates.get("departure") and prior_dates.get("return")):
            trip_update = _merge_trip_state(trip_update, _deterministic_period_facts(message, history))

        # A normal trip request to a destination implies Ariella should handle
        # flights unless the customer explicitly says flights are booked/not needed.
        dest_state = trip_update.get("destination") if isinstance(trip_update.get("destination"), dict) else {}
        decisions_state = trip_update.get("service_decisions") if isinstance(trip_update.get("service_decisions"), dict) else {}
        flight_decision = decisions_state.get("flights")
        flight_wanted = flight_decision.get("wanted") if isinstance(flight_decision, dict) else flight_decision
        if dest_state.get("places") and flight_wanted is not False:
            services_state = list(trip_update.get("requested_services") or [])
            if "flights" not in services_state:
                services_state.append("flights")
            trip_update["requested_services"] = services_state
            decisions_state = dict(decisions_state)
            if flight_decision is None:
                decisions_state["flights"] = {"wanted": True, "source": "destination_trip_intent"}
            trip_update["service_decisions"] = decisions_state

        # During a chosen post-flight service, preserve the session lock unless
        # the customer explicitly selected another service above.
        locked_post_flight_session = str(trip_state.get("active_session") or "")
        if trip_state.get("post_flight_continuation") and locked_post_flight_session in {"lodging","car","trip_planning"}:
            statuses_lock = dict(trip_update.get("session_status") or {})
            statuses_lock[locked_post_flight_session] = "active"
            trip_update["session_status"] = statuses_lock
            trip_update["active_session"] = locked_post_flight_session
        # A confirmed route settles the flight gateway even if the extractor
        # forgot to copy it into destination_airports this turn.
        trip_update = _resolve_destination_airports_from_route(trip_update)
        # A ski trip's gateway is derived from the ski resort catalog instead.
        trip_update = _resolve_ski_destination_airports(trip_update)
        # Once the customer names one specific gateway among the resort's
        # several candidates (e.g. "Verona"), stop searching the rest.
        trip_update = _narrow_ski_gateway_airport(trip_update, message)
        # Once the route is approved and the customer answers the
        # post-approval "narrow to one gateway or keep both?" question (see
        # the flight.gateway_narrow gap), resolve that one answer.
        trip_update = _narrow_gateway_airport_after_route(trip_update, message)
        # An approved route already answers "where do you want to stay" -
        # lodging search on the same vacation must not re-ask it.
        trip_update = _resolve_lodging_locations_from_route(trip_update)
        # The customer's name/gender/home airports always come fresh from
        # their registration data, never from client-supplied state, which
        # can be stale or wrong. Loaded before the sessions advance so the
        # departure default counts toward the flight gaps.
        trip_update["profile"] = _member_profile(session["member_id"])
        trip_update = _apply_home_airport(trip_update)
        # trip_planning must never silently activate itself without a
        # genuine customer decision - see the function's own docstring.
        trip_update = _reject_unrequested_trip_planning_activation(trip_state, trip_update, message, history)
        # Ariella, not chat history, owns the four-session progression.
        trip_update = _advance_sessions(trip_update)
        if trip_update["profile"].get("gender"):
            trip_update["user_gender"] = trip_update["profile"]["gender"]

        # If the customer has just declined/deferred the remaining optional
        # services and every wanted service is already complete, skip the
        # conversational acknowledgement turn. Go straight to the final summary.
        # This is service-agnostic: flights/lodging/car/trip planning behave alike.
        statuses_now = trip_update.get("session_status") if isinstance(trip_update.get("session_status"), dict) else {}
        decisions_now = trip_update.get("service_decisions") if isinstance(trip_update.get("service_decisions"), dict) else {}
        resolved_all_services = all(
            statuses_now.get(s) in ("complete","declined")
            or ((decisions_now.get(s) or {}).get("wanted") is False if isinstance(decisions_now.get(s), dict) else decisions_now.get(s) is False)
            for s in ("flights","lodging","car","trip_planning")
        )
        force_summary_now = bool(trip_update.get("ready_for_summary")) and resolved_all_services

        # A natural confirmation of an already-proposed itinerary closes only
        # the planning session. Persist the approved plan context for the vacation
        # card; enrichment (DB prices/ticket links) can consume this state without
        # reopening the conversation as a questionnaire.
        msg_confirm = _normalize_confirm(message).lower()
        planning_active = str(trip_state.get("active_session") or "") == "trip_planning"
        # Seen live: a route built up incrementally, one day (or a couple of
        # days) proposed per turn rather than the whole itinerary in one
        # message - by the time the customer finally confirms ("לא, זה נשמע
        # מצוין"), only the last day or two is still within a narrow recent
        # window, so day_mention_count below never reaches 2 even though the
        # full route was genuinely built and just approved. The customer
        # kept getting asked about the same route again and again, since
        # _is_itinerary_acceptance below could never actually close
        # trip_planning. Widened from the last 4 history items (~2
        # exchanges) to 16 (~8 exchanges) - generous enough to span a
        # typical multi-day route built turn by turn, still bounded so it
        # can't reach back into an unrelated earlier conversation.
        prior_assistant = " ".join(
            str(x.get("content") or "") for x in (history or [])[-16:]
            if isinstance(x, dict) and str(x.get("role") or "").lower() == "assistant"
        )
        # The message actually being approved right now is NOT reliably "the
        # immediately-preceding assistant message" - seen live even with the
        # already_approved guard below in place: the customer asked a
        # tangential question about the route ("מה עם לרנקה?") right after
        # the real itinerary was proposed, got an answer, and only THEN said
        # something that counted as acceptance - so the message directly
        # before that acceptance was the tangential answer, not the day-by-
        # day plan, and it was that tangential answer getting captured and
        # saved as the itinerary text on the very first (and only) capture,
        # with the guard having nothing to protect against since it never
        # fires twice here. Search backward for the most recent assistant
        # message that actually LOOKS like a day-by-day itinerary (multiple
        # "יום <weekday>" markers) and prefer that; fall back to the
        # immediately-preceding message only if nothing matches that shape.
        import re as _re_itinerary
        # A day mention ("יום 1 (ראשון)", "יום ראשון", "יום שני:"...) counts
        # as itinerary shape UNLESS it's immediately preceded by a calendar
        # date - that specific pattern ("27.06.2027 (יום ראשון)") is how a
        # flight-approval summary states which weekday a date falls on, not
        # a day-by-day plan. A first attempt required the literal "יום <N> ("
        # format, which correctly rejected the flight summary but also
        # rejected real itineraries the model phrased slightly differently
        # ("יום ראשון:", no leading number) - seen live: that stricter check
        # then found nothing at all and left the מסלול/אטרקציות tab
        # completely empty instead of wrong-but-present.
        _day_mention_re = _re_itinerary.compile(
            r"יום\s+(?:\d{1,2}\s*)?\(?(?:ראשון|שני|שלישי|רביעי|חמישי|שישי|שבת)\)?"
        )
        _date_just_before_re = _re_itinerary.compile(r"\d{1,2}\.\d{1,2}\.\d{2,4}\s*\(?$")

        # Itineraries are just as often numbered ("יום 1: הגעה...", "יום 2:
        # פליטביצה") with no weekday at all - seen live in the Croatia test:
        # a full numbered route never counted as an itinerary, so the
        # customer's approval of it was never recognized and the planning
        # session could never close. Two distinct day numbers count too.
        _numbered_day_re = _re_itinerary.compile(r"(?<![\u05d0-\u05ea])יום\s+(\d{1,2})(?!\d)")

        def day_mention_count(text):
            text = str(text or "")
            count = 0
            for m in _day_mention_re.finditer(text):
                prefix = text[max(0, m.start() - 20):m.start()]
                if _date_just_before_re.search(prefix):
                    continue
                count += 1
            numbered = {m.group(1) for m in _numbered_day_re.finditer(text)}
            return max(count, len(numbered))


        last_assistant_text = ""
        itinerary_shaped_text = ""
        for item in reversed(history or []):
            if not isinstance(item, dict) or str(item.get("role") or "").lower() != "assistant":
                continue
            content = str(item.get("content") or "").strip()
            if not last_assistant_text:
                last_assistant_text = content
            if not itinerary_shaped_text and day_mention_count(content) >= 2:
                itinerary_shaped_text = content
                break
        last_assistant_text = itinerary_shaped_text or last_assistant_text
        # trip_planning already fully approved once must never re-fire this.
        # Without this guard, a later, unrelated follow-up question about the
        # already-approved route (e.g. "מה עם לרנקה?") can reopen
        # trip_planning as active_session (the explicit-request handoff
        # above honors that immediately, by design), and if the customer's
        # NEXT reply to Ariella's answer happens to land in the accept-phrase
        # set below while that answer itself mentions "מסלול" (easy for an
        # answer ABOUT the route to do), this fired again - silently
        # overwriting trip_planning.approved_text with that tangential
        # answer instead of the real itinerary, which is exactly what ended
        # up saved to the vacation card in a live conversation, with the
        # actual day-by-day plan lost entirely.
        already_approved = bool((trip_state.get("trip_planning") or {}).get("approved")) if isinstance(trip_state.get("trip_planning"), dict) else False
        # Require actual day-by-day itinerary shape (2+ "יום <weekday>" markers)
        # in the recent assistant messages, not just the word "מסלול"/"אטרק"
        # appearing somewhere. That bare substring check fired even on a
        # narrow sub-question mid-planning that happens to mention "מסלול" in
        # a different sense - e.g. "לגבי הטיסה - נוח לך יותר לצאת ממלרנקה
        # ולחזור מפאפוס?" (an open-jaw airport preference, not the day-by-day
        # plan) - seen live: a plain "מצוין" answering that narrow question
        # closed the whole trip_planning session and told the customer it was
        # time to move on to flights/lodging/car, which made no sense since
        # she was still mid-flight-conversation and had approved nothing like
        # a full itinerary.
        planning_accept = planning_active and not already_approved \
            and _is_itinerary_acceptance(message) and day_mention_count(prior_assistant) >= 2
        if planning_accept:
            statuses_plan = dict(trip_update.get("session_status") or {})
            statuses_plan["trip_planning"] = "complete"
            trip_update["session_status"] = statuses_plan
            trip_update["active_session"] = None
            plan = dict(trip_update.get("trip_planning") or {})
            plan["interested"] = True
            plan["approved"] = True
            plan["enrichment_pending"] = True
            # Capture the actual itinerary text right now, while it's still
            # unambiguously the message being approved. Left for later (a
            # backward scan through the full history at flight-approval time,
            # in ariella_start_flight_search) it silently grabs whatever
            # assistant message happens to be last by then instead - seen
            # live: the itinerary card ended up showing the flight-approval
            # confirmation text ("הבקשה אושרה ואני יוצאת לסריקת טיסות...")
            # instead of the route/attractions plan, because that had since
            # become the last non-excluded assistant message in history.
            if last_assistant_text:
                plan["approved_text"] = last_assistant_text
            trip_update["trip_planning"] = plan

        try:
            reply = _call_tinkerbell(key, model, history, message, trip_update)
        except Exception as exc:
            logging.exception("Tinkerbell reply failed after state update: %s", exc)
            # Preserve Ariella's newly collected state even if the conversational
            # model has a transient failure. The next user turn can continue.
            reply = "קלטתי את הפרטים. נמשיך מכאן."
        reply = _fix_child_gender_wording(reply, trip_update)
        reply = _fix_itinerary_intro_day_count(reply)
        if post_flight_answer and not any(post_flight_answer.values()):
            reply = "בסדר גמור. מעבירה אותך לתוצאות הטיסה - ותמיד אפשר לחזור לכאן כדי להוסיף לינה, רכב או מסלול."

        # "מאשר/מאשרת" (and the "סיכום" framing that leads into it) may only
        # ever appear once every one of the four domains - flights included,
        # per product owner - has reached a final answer (complete or
        # declined): that's the single real combined-approval moment, not
        # each domain's own completion. Recomputed fresh here (not trusted
        # from trip_update["ready_for_summary"], which can still be a turn
        # stale right after e.g. planning_accept just flipped trip_planning
        # to "complete" above, before _advance_sessions recomputes it below).
        # Two mistakes seen live, both caught the same way: (1) Tinkerbell
        # showed a "סיכום הטיסה: ..." block and asked for approval while a
        # genuinely required fact (budget, ישיר/קונקשן...) was still
        # missing; (2) once a single domain's own details were complete, it
        # asked for the reserved מאשר/מאשרת word for THAT domain alone (a
        # car or route summary), even though the word is reserved for the
        # one final combined approval. Never a guess from the word
        # "סיכום"/"מאשר" alone - only acted on when the authoritative
        # session_status disagrees.
        # Recompute session_status fresh right before this check (not just
        # relying on whatever _advance_sessions last set, earlier in the
        # turn) - any state mutation between that earlier call and here
        # (e.g. a domain's last required detail merging in THIS turn, or a
        # post-hoc closure like planning_accept below) would otherwise leave
        # this check reading stale statuses, wrongly concluding a domain is
        # still open when it just closed - and derailing a genuinely
        # complete request into the generic fallback close instead of the
        # real final approval. Seen live: all four domains visibly complete
        # in Tinkerbell's own summary, yet the reply ended in the neutral
        # "ממשיכה מכאן" close instead of "כתבי מאשרת".
        trip_update = _advance_sessions(trip_update)
        _all_domains_decided_now = all(
            str((trip_update.get("session_status") or {}).get(_s) or "pending") in ("complete", "declined")
            for _s in ("flights", "lodging", "car", "trip_planning")
        )
        if any(p in str(reply or "") for p in ("כתבי מאשרת", "כתוב מאשר", "מאשר/מאשרת", "סיכום")) and not _all_domains_decided_now:
            premature_gap_question = _flight_gap_question(_session_gaps(trip_update, "flights"), trip_update)
            if premature_gap_question:
                reply = premature_gap_question
            else:
                # Flights itself has no real gap left - what's actually still
                # open is one of the other three domains, not yet decided.
                # Per Carmit: don't first ask a vague "is everything correct?"
                # (whose כן/לא answer doesn't even say what it's answering)
                # and then, once that's settled, ask again for the real
                # מאשרת - that is two rounds for what should be one. Ask the
                # single concrete question that's actually still open (do you
                # want lodging/car/route too?) instead of a generic neutral
                # close; only once that's answered - and every domain really
                # is decided - does the one real מאשרת request appear.
                _next_premature = trip_update.get("next_session")
                if _next_premature in _POST_FLIGHT_LABELS:
                    reply = f"מעולה, פרטי הטיסה מלאים. תרצי שאמשיך גם עם {_POST_FLIGHT_LABELS[_next_premature]}?"
                    trip_update["post_flight_offer"] = [_next_premature]
                else:
                    # Not phrased as "is it all correct or do you want to fix
                    # something?" - that compound question leaves a plain
                    # כן/לא answer with no way to tell which half it answers.
                    # A single, non-question continuation instead.
                    for _approval_phrase, _neutral_close in (
                        ("אם כל הפרטים נכונים, כתבי מאשרת.", "ממשיכה מכאן - אם יש משהו לתקן, תגידי לי בכל שלב."),
                        ("אם כל הפרטים נכונים, כתוב מאשר.", "ממשיך מכאן - אם יש משהו לתקן, תגיד לי בכל שלב."),
                        ("אם כל הפרטים נכונים, יש לרשום מאשר/מאשרת.", "ממשיכה מכאן - אם יש משהו לתקן, תגידו לי בכל שלב."),
                    ):
                        if _approval_phrase in str(reply or ""):
                            reply = str(reply).replace(_approval_phrase, _neutral_close).strip()
                            break

        if planning_accept:
            # Approval closes only the itinerary session. Name whichever of the
            # other three domains are still genuinely open - this must never
            # assume flights was already handled. trip_planning can be the
            # FIRST session a customer goes through (asking for route/
            # destination ideas before ever discussing a flight), not only
            # the usual last one after a flight search. Seen live: a customer
            # who planned Cyprus's itinerary first got told "great, itinerary
            # approved" with only lodging/car offered next - flights was
            # silently skipped entirely, because this reply used to hardcode
            # "לינה או השכרת רכב" unconditionally regardless of what was
            # actually still pending.
            statuses_after_plan = trip_update.get("session_status") if isinstance(trip_update.get("session_status"), dict) else {}
            remaining_labels = {"flights":"טיסות", "lodging":"לינה", "car":"השכרת רכב"}
            # Per product owner: flights takes absolute priority over
            # everything else, regardless of which topic the customer
            # started with - if she built the route before ever discussing
            # flights, approving the route must hand straight back to
            # flights, not to a combined "flights or lodging or car?"
            # question. Flights also isn't a yes/no offer the way
            # lodging/car are (rule: a destination already implies flights
            # are wanted by default) - it needs its own summary/approval
            # flow, which _advance_sessions below will now correctly expose
            # (ready_for_summary=True) once this turn's flights gaps are
            # empty, instead of silently marking flights "complete" and
            # skipping that step entirely (the bug seen live: after route
            # approval the flight search never ran at all).
            if statuses_after_plan.get("flights") not in ("complete", "declined"):
                reply = "מצוין, המסלול מאושר. בואי נוודא שגם פרטי הטיסה שלמים."
                trip_update["active_session"] = "flights"
            else:
                remaining = [
                    s for s in ("lodging","car")
                    if statuses_after_plan.get(s, "pending") not in ("complete","declined")
                ]
                if remaining:
                    next_domain = remaining[0]
                    reply = f"מצוין, המסלול מאושר. תרצי שאמשיך גם עם {remaining_labels[next_domain]} לחופשה הזו?"
                    # Remember what was just offered, so a plain "כן"/"לא" next
                    # turn settles it via _post_flight_offer_answer. Without this
                    # the "כן" reached the model with no record of the question,
                    # and it asked about the car all over again (seen live).
                    trip_update["post_flight_offer"] = [next_domain]
                else:
                    reply = "מצוין, המסלול מאושר."

        # Never let the conversation claim it is ready for a final summary when
        # the structured source of truth is missing required facts. This keeps
        # the visible summary and downstream execution on the same data object.
        trip_update = _advance_sessions(trip_update)

        # Deceptive-success safety net: a reply that declares the whole
        # vacation closed/finished must never win over an authoritative
        # still-pending domain. Seen live: the customer explicitly asked for
        # car (skipping past the still-pending, never-discussed lodging
        # session via the service_request shortcut above); once car and
        # trip_planning were both done, Tinkerbell declared "everything is
        # closed now - flights, itinerary and car" and never circled back to
        # ask about lodging at all, even though _advance_sessions correctly
        # still reports it as next_session. Free text has too many equivalent
        # "we're all done" phrasings to allow-list exactly, so this matches on
        # closing/finished language the same way claims_execution (above,
        # flight-approval case) matches on execution language - and only
        # overrides when the authoritative state genuinely disagrees.
        closing_claim = any(p in str(reply or "") for p in (
            # "כל הפרטים" alone is too loose: it's a substring of the
            # ordinary per-domain approval phrasing ("אם כל הפרטים נכונים,
            # כתבי מאשרת") used on a genuine first-time flight/lodging/car
            # summary, which must NEVER be treated as a closing claim. The
            # real source text this was meant to catch was "כל פרטי החופשה
            # שלך סגורים עכשיו" - match that specific phrase instead.
            "הכל סגור", "כל פרטי החופשה", "סגורים עכשיו", "החופשה שלך מוכנה",
            "הכל מאושר", "סיימנו", "הכל מוכן", "זה סוגר את כל", "כל התחומים",
            # Seen live: "בסדר גמור. מעבירה אותך לתוצאות הטיסה..." after a
            # lodging request went undetected (car was declined in the same
            # message) - Tinkerbell claimed a handoff to results/the vacation
            # page while lodging was still genuinely open. The client only
            # navigates anywhere when the backend's own resolved state says
            # every requested domain is actually done, so this text was pure
            # fiction and the customer saw "nothing happened" after it.
            "מעבירה אותך", "מעביר אותך",
            # Seen live: the route-approval closing line itself ("אני אשלח
            # לך את כל האינפורמציה לכרטיסיית האטרקציות... מאחלת לך חופשה
            # נעימה") fired even though flights had never actually been
            # finished and lodging had never even been asked about -
            # planning_accept's own "is this really route acceptance"
            # detection missed the turn, so Tinkerbell's free-form judgment
            # produced this canned "we're completely done" sign-off on its
            # own, unchecked. None of the other closing phrases above
            # happen to appear in this exact wording, so it slipped past
            # this same safety net - add its own distinguishing phrases.
            "מאחלת לך חופשה נעימה", "מאחל לך חופשה נעימה", "לכרטיסיית האטרקציות",
        ))
        pending_domain = trip_update.get("next_session") if isinstance(trip_update, dict) else None
        if not pending_domain and isinstance(trip_update, dict):
            # next_session is only ever set when NOTHING is active (an
            # optional domain waiting to be offered). Flights is different:
            # once it's the one thing left, _advance_sessions puts it
            # straight into active_session instead (it's mandatory, never
            # offered as a yes/no choice) - so next_session stays None even
            # though flights still very much needs attention. Seen live:
            # active_session was correctly "flights" here, but this check
            # only looked at next_session, so the wrong "all done" closing
            # text still won.
            _still_active = trip_update.get("active_session")
            if _still_active and (trip_update.get("session_status") or {}).get(_still_active) not in ("complete", "declined"):
                pending_domain = _still_active
        if closing_claim and pending_domain:
            # Flights is never an optional "or is that all for now?" offer
            # the way lodging/car/route are - it must always be resolved
            # first (fixed session order, per product owner). The generic
            # yes/no-offer phrasing below would wrongly imply flights can
            # just be skipped, so it gets the same direct redirect
            # planning_accept's own success path already uses.
            if pending_domain == "flights":
                # The bare "let's make sure flight details are complete"
                # line leaves the customer with no way to know what to
                # actually answer (the same problem already fixed elsewhere
                # for the approval-gap and premature-מאשר safety nets below)
                # - append the real concrete question when one is available
                # (e.g. the new post-route gateway-narrow question), instead
                # of silently masking it behind this generic redirect.
                reply = "עוד דבר אחד לפני שסוגרים - בואי נוודא שגם פרטי הטיסה שלמים."
                concrete_gap_question = _flight_gap_question(_session_gaps(trip_update, "flights"), trip_update)
                if concrete_gap_question:
                    reply += " " + concrete_gap_question
                trip_update["active_session"] = "flights"
            else:
                remaining_labels = {"lodging": "לינה", "car": "השכרת רכב", "trip_planning": "מסלול ואטרקציות"}
                label = remaining_labels.get(pending_domain, pending_domain)
                reply = f"עוד דבר אחד לפני שסוגרים - תרצי שאעזור גם עם {label}, או שזה הכל להפעם?"

        # Search approval is a system event, not a language-model decision.
        approval = _approval_trigger(message, history, trip_state)
        # A typo that resembles approval must never produce a false "search started"
        # message. Keep the hard execution gate exact, and ask for the exact word.
        if not approval and _looks_like_approval_typo(message, trip_state, history):
            gender = str((trip_state or {}).get("user_gender") or "").lower()
            if gender == "male":
                reply = "לא הבנתי, האם התכוונת לאשר? אם כן, כתוב מאשר."
            elif gender == "female":
                reply = "לא הבנתי, האם התכוונת לאשר? אם כן, כתבי מאשרת."
            else:
                reply = "לא הבנתי, האם התכוונת לאשר? אם כן, יש לכתוב מאשר/מאשרת."
        # Deceptive-success safety net: the prompt tells Tinkerbell that once the
        # summary was already shown and the customer answers affirmatively, it
        # should "briefly confirm the request was received and proceed to
        # execution" - free text, written on the assumption that the real
        # deterministic approval gate (_approval_trigger, above) actually fired
        # this turn. Seen live TWICE, with two different phrasings each time
        # ("הבקשה יוצאת עכשיו לחיפוש... אחזור אלייך עם התוצאות", then later
        # "אני שולחת אותה לסריקה ונחזור אלייך עם התוצאות") - free text has
        # endless equivalent phrasings, so matching a fixed list of exact
        # phrases missed the second one entirely. Detect it instead as a
        # co-occurrence of an action verb ("שולחת/יוצאת/התחלתי/נשלח/נקלט"...)
        # with a search/results noun ("לחיפוש/לסריקה/תוצאות"...) anywhere in
        # the reply - robust to whichever way the model phrases the same claim.
        elif not approval:
            action_verbs = (
                "יוצאת","יוצא","שולחת","שולח","נשלח","נשלחה","התחלתי",
                "מתחילה","מתחיל","נקלט","נקלטה","ממשיכה","ממשיך","מעבדת","מעבד",
            )
            # "לחפש"/"לסרוק" (infinitive "to search"/"to scan") are distinct
            # strings from "לחיפוש"/"לסריקה" (the noun forms already listed) -
            # seen live: "יוצאים לחפש" ("heading out to search") slipped past
            # this exact gap, claiming a scan had launched via a phrasing this
            # list didn't cover.
            action_targets = ("לחיפוש","לסריקה","סריקת טיסות","בסריקה","בחיפוש","תוצאות","לחפש","לסרוק")
            # A reply that already ends with the real approval request
            # ("כתבי מאשרת" etc.) is not a false completion claim, even if it
            # also happens to mention what will happen once approved (e.g.
            # "לאחר אישור אני יוצאת לחיפוש") - that is a true, correctly-
            # phrased statement about the future, not a claim that the search
            # already ran. Without this guard, the override below replaced an
            # already-correct summary+approval-request with a near-duplicate
            # of itself, so the customer saw the same flight summary twice in
            # a row for no reason.
            already_asks_for_approval = (
                "כתבי מאשרת" in str(reply or "")
                or "כתוב מאשר" in str(reply or "")
                or "מאשר/מאשרת" in str(reply or "")
            )
            claims_execution = (
                not already_asks_for_approval
                and any(v in str(reply or "") for v in action_verbs)
                and any(t in str(reply or "") for t in action_targets)
            )
            if claims_execution:
                # If a real required fact is still missing, the honest and
                # useful reply is the actual pending question - not a vague
                # "just retype מאשרת", which is actively misleading here: a
                # gap means retyping מאשרת alone will not start anything, and
                # telling her to do that is exactly what produced the next
                # false claim in the same live transcript.
                gap_question = _flight_gap_question(_session_gaps(trip_update, "flights"), trip_update)
                if gap_question:
                    reply = gap_question
                else:
                    # No real gap left - show the actual summary instead of a
                    # bare "type מאשרת" with nothing to approve. Falls back to
                    # the old bare instruction only if state somehow has too
                    # little to summarize (should not happen once gaps are
                    # genuinely empty, but never block approval entirely).
                    summary = _flight_summary_text(trip_update)
                    if summary:
                        reply = "עדיין לא יצאתי לחיפוש בפועל - הנה הסיכום, ורק לאחר אישור במילה המדויקת אני יוצאת לדרך:\n\n" + summary
                    else:
                        gender = str((trip_state or {}).get("user_gender") or "").lower()
                        if gender == "male":
                            reply = "עדיין לא יצאתי לחיפוש בפועל - צריך לכתוב בדיוק את המילה מאשר כדי להתחיל."
                        elif gender == "female":
                            reply = "עדיין לא יצאתי לחיפוש בפועל - צריך לכתוב בדיוק את המילה מאשרת כדי להתחיל."
                        else:
                            reply = "עדיין לא יצאתי לחיפוש בפועל - צריך לכתוב בדיוק את המילה מאשר/מאשרת כדי להתחיל."
        # A generic "yes" during normal data collection is NEVER a search approval.
        # It must only approve an explicit final approval question / ready state.
        msg_norm = _normalize_confirm(message).lower()
        generic_yes = msg_norm in {"כן","נכון","מעולה","מצוין","מצויין","סבבה","אחלה","נשמע טוב","נשמע אחלה"}
        if generic_yes and not approval:
            # Do not let extractor/model turn this ordinary conversational answer
            # into search intent or missing-data validation.
            trip_update["search_intent"] = bool(trip_state.get("search_intent"))
            trip_update["search_confirmed"] = bool(trip_state.get("search_confirmed"))
            trip_update["ready_for_summary"] = bool(trip_state.get("ready_for_summary"))
        if approval:
            merged = _merge_trip_state(trip_state, trip_update if isinstance(trip_update, dict) else {})
            # Flight approval closes only session 1. Keep the shared trip facts and
            # leave lodging/car/planning available for continuation after the scan.
            statuses_after_flight = dict(merged.get("session_status") or {})
            statuses_after_flight["flights"] = "complete"
            # Flight approval must not erase prior service decisions. Pending stays
            # pending, completed stays completed, and an explicit decline stays declined.
            for optional_service in ("lodging","car","trip_planning"):
                statuses_after_flight.setdefault(optional_service, "pending")
            merged["session_status"] = statuses_after_flight
            merged["active_session"] = None
            merged["post_flight_continuation"] = True
            # Approval must execute exactly the dates the customer already approved.
            # The extractor response to the word מאשרת must never erase/replace them.
            if isinstance(trip_state.get('dates'), dict) and trip_state.get('dates', {}).get('departure') and trip_state.get('dates', {}).get('return'):
                merged['dates'] = dict(trip_state['dates'])
            # Never approve/launch a scan while a required flight fact is still
            # missing. Ask for that fact first, then summarize and request approval again.
            approval_gaps = _session_gaps(merged, "flights")
            if approval_gaps:
                merged["search_intent"] = True
                merged["search_confirmed"] = False
                merged["ready_for_summary"] = False
                merged["session_status"] = dict(merged.get("session_status") or {})
                merged["session_status"]["flights"] = "active"
                merged["active_session"] = "flights"
                trip_update = merged
                # Every gap _session_gaps can actually return for "flights" needs
                # its own specific question here. A generic fallback ("one
                # detail is missing") leaves the customer with no way to know
                # what to answer - seen live: she got exactly that generic
                # line, asked "מה עכשיו?" (what now?), and had no way forward
                # other than guessing.
                reply = _flight_gap_question(approval_gaps, trip_update)
                approval = False
            else:
                # This whole branch used to end here, with everything below it
                # (search_confirmed=True, the "approved" reply, etc.) sitting
                # OUTSIDE this else at the same indent as the if/else itself -
                # so it ran unconditionally no matter which branch had just
                # executed. That silently undid the approval_gaps branch above:
                # a customer told "כתבי מאשרת" was accepted and a scan was
                # starting even when a required flight fact (destination
                # airport, budget, etc.) was still genuinely missing, which
                # then made the actual /start-flight-search call fail with an
                # unrelated-looking error instead of asking the missing
                # question in the first place. All of this must only run when
                # approval_gaps was actually empty.
                merged["search_intent"] = True
                merged["search_confirmed"] = True
                merged["ready_for_summary"] = True
                merged["user_gender"] = _user_gender_from_approval(message, merged)
                services = list(merged.get("requested_services") or [])
                # Approval at a flight confirmation stage is authoritative: mark flights requested.
                if "flights" not in services:
                    services.append("flights")
                flight_state = merged.get("flight") if isinstance(merged.get("flight"), dict) else {}
                has_flight_data = bool(
                    merged.get("departure_airport")
                    or flight_state.get("connection_preference")
                    or flight_state.get("cabin")
                    or flight_state.get("baggage")
                    or (merged.get("dates") or {}).get("departure")
                    or (merged.get("dates") or {}).get("return")
                )
                history_text = " ".join(str(x.get("content") or "") for x in history if isinstance(x, dict))
                if ("flights" not in services) and (has_flight_data or any(word in history_text for word in ("טיסה","טיסות","טיסות ישירות"))):
                    services.append("flights")
                merged["requested_services"] = services
                trip_update = merged
                # By construction this is the single, final approval: it only
                # ever fires once ready_for_summary is true, which _advance_
                # sessions only sets once every one of the four domains has
                # already reached complete/declined (see its docstring -
                # flights closes itself like the others now, no separate
                # mid-conversation מאשר/מאשרת gate). There is no "also want
                # lodging?" offer left to make here; everything requested was
                # already decided earlier in the conversation. State the
                # truth: the combined search (whichever domains were
                # actually wanted) is starting now.
                remaining_labels = {
                    "lodging":"לינה", "car":"השכרת רכב", "trip_planning":"מסלול ואטרקציות"
                }
                wanted_extra = [
                    remaining_labels[s] for s in ("trip_planning", "lodging", "car")
                    if statuses_after_flight.get(s) == "complete"
                ]
                if wanted_extra:
                    joined = wanted_extra[0] if len(wanted_extra) == 1 else " ו".join([", ".join(wanted_extra[:-1]), wanted_extra[-1]])
                    reply = f"הבקשה אושרה ואני יוצאת עכשיו לחיפוש המלא - טיסות ו{joined}. אעדכן אותך כשהתוצאות יהיו מוכנות."
                else:
                    reply = "הבקשה אושרה ואני יוצאת לסריקת טיסות. אעדכן אותך כשהתוצאות יהיו מוכנות."
    except Exception as exc:
        logging.exception("ariella chat-clean pipeline failed: %s", exc)
        return jsonify({'status': 'error', 'message': 'טינקרבל לא זמינה כרגע.', 'engine_version': ENGINE_VERSION}), 503

    if not isinstance(trip_update, dict):
        trip_update = {}
    try:
        persist_trip_plan = bool(locals().get("planning_accept", False)) \
            and bool((trip_update.get("dates") or {}).get("departure")) \
            and bool((trip_update.get("dates") or {}).get("return"))
    except Exception:
        logging.exception("persist_trip_plan computation failed; defaulting to False")
        persist_trip_plan = False
    try:
        # Per product owner: the actual flight scan (the real paid API call)
        # must not fire the moment flights alone are approved - a customer
        # who also wants a route can end up changing the flight dates/
        # gateway once the route is actually built, and an already-launched
        # scan is wasted (or worse, locks in criteria the route then
        # contradicts). Defer the launch until EVERY domain the customer
        # asked for - trip_planning, lodging, car - has reached a final
        # answer (complete or declined), then launch everything together:
        # the flight scan, and (via _attach_decided_post_flight_domains in
        # public_site.py) the lodging/car searches and the approved
        # itinerary, all in that one combined call. A flights-only customer
        # sees no change - the other three are already "declined" the
        # moment that's explicit, so this fires on the very same turn as
        # approval exactly as it always did.
        _domains_decided = all(
            str((trip_update.get('session_status') or {}).get(_svc) or 'pending') in ('complete', 'declined')
            for _svc in ('trip_planning', 'lodging', 'car')
        )
        _combined_search_already_launched = bool(trip_update.get('combined_search_launched'))
        start_flight_search = (
            bool(trip_update.get('search_confirmed'))
            and _domains_decided
            and not _combined_search_already_launched
        )
        if start_flight_search:
            trip_update['combined_search_launched'] = True
    except Exception:
        logging.exception("start_flight_search computation failed; defaulting to False")
        start_flight_search = False
    profile_for_response = trip_update.get('profile')

    # Once all four service domains (flights/lodging/car/trip_planning) have
    # each reached a final answer - complete OR declined, either way - the
    # vacation is unambiguously done. Nothing about it should leak into
    # whatever the customer asks for next (a real bug: a couple with a
    # 17-year-old daughter carried over into a new trip as a 17-year-old son,
    # because the old structured state was never actually cleared). This is
    # deliberately silent - no "delete everything?" gate - because completion
    # is already certain once every domain answered either way; that gate
    # exists for the ambiguous case where the customer might still be
    # mid-trip, which this is not.
    # Defensive: this reset must never be allowed to crash the whole request.
    # Whatever shape trip_update happens to be in, the worst acceptable outcome
    # is skipping the reset for this turn, never a 500 that blocks the chat.
    trip_state_reset = False
    resolved_trip_state = None
    try:
        final_statuses = trip_update.get("session_status") if isinstance(trip_update.get("session_status"), dict) else {}
        final_decisions = trip_update.get("service_decisions") if isinstance(trip_update.get("service_decisions"), dict) else {}
        # flights="complete" means only that every required field is filled and
        # the summary/approval prompt is ready to show - NOT that the customer
        # has actually approved yet (that only happens inside the explicit
        # "מאשר/מאשרת" gate, which sets post_flight_continuation). Treating
        # "complete" alone as resolved here wiped the whole trip state the
        # instant flights became data-complete whenever lodging/car/
        # trip_planning already happened to be declined too (e.g. a business
        # trip, where trip_planning auto-declines) - before the customer ever
        # got to see the summary or approve, silently discarding
        # destination/dates/everything and breaking the actual search.
        flights_resolved = bool(trip_update.get("post_flight_continuation")) or final_statuses.get("flights") == "declined"
        other_domains_resolved = all(
            final_statuses.get(s) in ("complete", "declined")
            or ((final_decisions.get(s) or {}).get("wanted") is False if isinstance(final_decisions.get(s), dict) else final_decisions.get(s) is False)
            for s in ("lodging", "car", "trip_planning")
        )
        trip_fully_resolved = flights_resolved and other_domains_resolved and not bool(locals().get("approval", False))
        if trip_fully_resolved:
            trip_state_reset = True
            # The chat page still needs the completed vacation facts this
            # turn to send the just-settled service (lodging/car/route) to
            # its search before handing off to the waiting page.
            resolved_trip_state = trip_update
            fresh_after_completion = {
                'session_status': {'flights': 'pending', 'lodging': 'pending', 'car': 'pending', 'trip_planning': 'pending'},
                'active_session': None,
            }
            # Member-level facts (not trip facts) survive the reset - no need to
            # re-ask gender for the next vacation.
            if trip_update.get('profile'):
                fresh_after_completion['profile'] = trip_update['profile']
            if trip_update.get('user_gender'):
                fresh_after_completion['user_gender'] = trip_update['user_gender']
            trip_update = fresh_after_completion
    except Exception:
        logging.exception("Auto-reset-on-completion check failed; leaving trip_update untouched")
        trip_state_reset = False

    # The moment a destination country is known, make sure the attractions
    # DB (itinerary_cards.py, data/attractions*.json) actually covers it -
    # per product owner, this must never again be a gap someone notices
    # live (as happened with Malta). Fire-and-forget: ensure_country_coverage
    # is a cheap no-op when the country is already covered or already being
    # researched, and otherwise kicks off a background SerpAPI-grounded
    # research job without delaying this chat turn at all. Reads from
    # resolved_trip_state when this turn just reset trip_update to a fresh
    # vacation (the destination info would otherwise already be gone).
    #
    # Keyed off destination.places (the free-text name(s) the customer
    # actually said), not destination_airports - seen live: a customer deep
    # into approving a Vietnam trip still had no attractions researched,
    # because destination_airports in this conversational state is only
    # required when destination_mode is "country"/"region"/"broad"
    # (_required_state_gaps); for an ordinary single-gateway country like
    # Vietnam it can stay empty in trip_update the entire conversation - the
    # real gateway code only gets resolved just-in-time, separately, inside
    # ariella_start_flight_search (public_site.py) from destination.places
    # at the moment the search actually launches. Waiting for
    # destination_airports here meant this trigger could fire late or never.
    # destination.places is set as soon as the customer names a destination
    # at all, so this now starts the research as early as possible.
    try:
        _state_for_coverage = locals().get("resolved_trip_state") or trip_update
        _dest_info = _state_for_coverage.get("destination") if isinstance(_state_for_coverage, dict) else None
        _places = (_dest_info.get("places") if isinstance(_dest_info, dict) else None) or []
        if _places:
            import attractions_coverage
            _seen_countries = set()
            for _place in _places:
                _needle = str(_place or "").strip()
                if not _needle:
                    continue
                _needle_lower = _needle.lower()
                for _airport in _load_airports():
                    _hay = " ".join(str(_airport.get(k) or "") for k in ("country_he","country_en","city_he","city_en")).lower()
                    if _hay and (_needle_lower in _hay or _hay in _needle_lower):
                        _country_he = str(_airport.get("country_he") or "").strip()
                        _country_en = str(_airport.get("country_en") or "").strip()
                        if _country_he and _country_he not in _seen_countries:
                            _seen_countries.add(_country_he)
                            attractions_coverage.ensure_country_coverage(_country_he, _country_en)
                        break
    except Exception:
        logging.exception("Attraction coverage check failed to queue")

    # Server-side copy of the conversation so it survives logout and follows
    # the account across devices, not just this browser's local cache.
    try:
        saved_history = list(history_before_gap) + [
            {'role': 'user', 'content': message},
            {'role': 'assistant', 'content': reply or 'אני איתך 😊'},
        ]
        save_ariella_conversation(session['member_id'], saved_history[-80:], trip_update)
    except Exception:
        logging.exception("Failed to persist Ariella conversation for member %s", session.get('member_id'))

    return jsonify({
        'status': 'success',
        'agent': 'Tinkerbell',
        'engine_version': ENGINE_VERSION,
        'reply': reply or 'אני איתך 😊',
        'trip_update': trip_update,
        'profile': profile_for_response,
        # Save only an itinerary approved against the current structured state.
        'persist_trip_plan': persist_trip_plan,
        # Execution is allowed only when the deterministic approval gate fired
        # on THIS user message. Never let model-extracted state start a scan.
        'start_flight_search': start_flight_search,
        'trip_state_reset': trip_state_reset,
        'resolved_trip_state': resolved_trip_state,
    })
